window.YUWEN_QUESTIONS = {"meta":{"subject":"山东专升本大学语文","groups":11,"per_group":"20+10+20","total":549,"unique":549,"rebuilt":"2026-10-29","types":["句子→篇目","释义→词条","作品→作者","实词辨析","句子翻译"],"note":"仅取 25 篇课文素材与同类词条；实词题强制校验例句含该词；释义题干扰项限定同分类；脏数据全部剔除"},"groups":[{"no":1,"date":"2026-10-29","date_end":"2026-10-30","pieces":["季氏将伐颛臾","鸿门宴","传是楼记","勾践灭吴","子路曾皙冉有公西华侍坐","逍遥游"],"theme":"综合练习 1","p1":[{"q":"「旦为行云，暮为行雨，朝朝暮暮，阳台之下」出自（　）","opts":["《许行》","《鸿门宴》","《邹忌讽齐王纳谏》","《巫山巫峡》"],"ans":"D","atext":"《巫山巫峡》","src":"句子→篇目","note":"出自《巫山巫峡》。参考译文：早晨她化为飘浮的云，傍晚化为降落的雨，天天早晚都在阳台之下。"},{"q":"「昔天以越予吴，而吴不受命；今天以吴予越，越可以无听天之命，而听君之令乎！」出自（　）","opts":["《论贵粟疏》","《留侯论》","《勾践灭吴》","《齐桓公伐楚》"],"ans":"C","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：从前上天把越给吴，吴不接受；如今上天把吴给越，越怎能不听天命而听您的命令呢！"},{"q":"「夫物不产于秦，可宝者多；士不产于秦，而愿忠者众。今逐客以资敌国，损民以益雠，内自虚而外树怨于诸侯，求国无危，不可得也。」出自（　）","opts":["《小翠》","《许行》","《六国论》","《谏逐客书》"],"ans":"D","atext":"《谏逐客书》","src":"句子→篇目","note":"出自《谏逐客书》。参考译文：物品不出产在秦国，可宝贵的很多；士人不生在秦国，但愿效忠的很多。如今驱逐客卿来资助敌国，损害人民来增益仇敌，对内自取空虚而对外在诸侯中树立怨恨，想求得国家没有危险，是不可能的。"},{"q":"「因指书而欣然笑曰：“所传者惟是矣！”」出自（　）","opts":["《报任安书》","《传是楼记》","《秋水》","《勾践灭吴》"],"ans":"B","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：于是指着书高兴地笑着说：“我传给你们的，就是这些了！”"},{"q":"「当韩之亡，秦之方盛也，以刀锯鼎镬待天下之士。其平居无罪夷灭者，不可胜数。虽有贲、育，无所复施。夫持法太急者，其锋不可犯，而其势未可乘。子房不忍忿忿之心，以匹夫之力而逞于一击之间；当此之时，子房之不死者，其间不能容发，盖亦已危矣。」出自（　）","opts":["《报任安书》","《传是楼记》","《鸿门宴》","《留侯论》"],"ans":"D","atext":"《留侯论》","src":"句子→篇目","note":"出自《留侯论》。参考译文：当韩国灭亡、秦国正强盛的时候，用刀锯鼎镬来对待天下的士人，那些平白无故被灭族的人，多得数不清。即使有孟贲、夏育那样的勇士，也无法施展。执法太急的，它的锋芒不可触犯，而它的形势还没有"},{"q":"「今者项庄拔剑舞，其意常在沛公也。」出自（　）","opts":["《齐桓公伐楚》","《鸿门宴》","《六国论》","《留侯论》"],"ans":"B","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：现在项庄拔剑起舞，他的用意常在沛公身上啊。"},{"q":"「得西山后八日，寻山口西北道二百步，又得钴鉧潭。西二十五步，当湍而浚者为鱼梁。梁之上有丘焉，生竹树。其石之突怒偃蹇，负土而出，争为奇状者，殆不可数：其嶔然相累而下者，若牛马之饮于溪；其冲然角列而上者，若熊罴之登于山。」出自（　）","opts":["《勾践灭吴》","《钴鉧潭西小丘记》","《郑伯克段于鄢》","《吕相绝秦》"],"ans":"B","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：发现西山后八天，沿着山口向西北走二百步，又发现了钴鉧潭。潭西二十五步，正对着水流湍急而深的地方是鱼梁。鱼梁上面有个小丘，生长着竹子和树木。那些石头突起高耸、从土里钻出来、争相呈现奇"},{"q":"「夫如是，故远人不服，则修文德以来之。既来之，则安之。」出自（　）","opts":["《谏逐客书》","《子路曾皙冉有公西华侍坐》","《钴鉧潭西小丘记》","《季氏将伐颛臾》"],"ans":"D","atext":"《季氏将伐颛臾》","src":"句子→篇目","note":"出自《季氏将伐颛臾》。参考译文：这样，远方之人不归服，就修明文德使他们来归；已经使他们来了，就使他们安定下来。"},{"q":"「既而大叔命西鄙北鄙贰于己。公子吕曰：“国不堪贰，君将若之何？欲与大叔，臣请事之；若弗与，则请除之，无生民心。”公曰：“无庸，将自及。”大叔又收贰以为己邑，至于廪延。子封曰：“可矣。厚将得众。”公曰：“不义不暱，厚将崩。”」出自（　）","opts":["《季氏将伐颛臾》","《郑伯克段于鄢》","《留侯论》","《吕相绝秦》"],"ans":"B","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：不久，太叔命令西部和北部的边邑也两面归属自己。公子吕说：\"国家不能容忍两属的情况，您打算怎么办？如果想把政权交给太叔，就请允许我去侍奉他；如果不给，就请除掉他，不要让百姓产生二心。"},{"q":"「锲而舍之，朽木不折；锲而不舍，金石可镂。」出自（　）","opts":["《劝学》","《小翠》","《留侯论》","《六国论》"],"ans":"A","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：雕刻几下就停下，腐朽的木头也刻不断；不停地雕刻，金属石头也能雕出花纹。"},{"q":"「是故明君贵五谷而贱金玉。」出自（　）","opts":["《论贵粟疏》","《齐桓公伐楚》","《秋水》","《齐桓晋文之事》"],"ans":"A","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：因此英明的君主重视五谷而轻视金玉。"},{"q":"「制，岩邑也，虢叔死焉，佗邑唯命。」出自（　）","opts":["《传是楼记》","《郑伯克段于鄢》","《报任安书》","《子路曾皙冉有公西华侍坐》"],"ans":"B","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：制是个险要的城邑，虢叔就死在那里，其他城邑都唯命是从。"},{"q":"黄鹤楼（武汉）、岳阳楼（岳阳）、滕王阁（南昌）、鹳雀楼（永济）。（　）","opts":["衣冠禽兽本义","三大石窟","四大名楼","四大名亭"],"ans":"C","atext":"四大名楼","src":"释义→词条","note":"四大名楼：黄鹤楼（武汉）、岳阳楼（岳阳）、滕王阁（南昌）、鹳雀楼（永济）。"},{"q":"黄鹤楼、岳阳楼、滕王阁；滕王阁、岳阳楼、黄鹤楼（　）","opts":["江南三大名楼","花中四君子","三大石窟","四大名亭"],"ans":"A","atext":"江南三大名楼","src":"释义→词条","note":"江南三大名楼：黄鹤楼、岳阳楼、滕王阁；滕王阁、岳阳楼、黄鹤楼"},{"q":"对笔、墨、纸、砚四种文具的统称。（　）","opts":["文房四宝","古代建筑构件","花中四君子","江南三大名楼"],"ans":"A","atext":"文房四宝","src":"释义→词条","note":"文房四宝：对笔、墨、纸、砚四种文具的统称。"},{"q":"醉翁亭（滁州）、陶然亭（北京）、爱晚亭（长沙）、湖心亭（杭州）。（　）","opts":["岁寒三友","四大名楼","四大名亭","江南三大名楼"],"ans":"C","atext":"四大名亭","src":"释义→词条","note":"四大名亭：醉翁亭（滁州）、陶然亭（北京）、爱晚亭（长沙）、湖心亭（杭州）。"},{"q":"敦煌莫高窟（甘肃）、云冈石窟（山西大同）、龙门石窟（河南洛阳）。（　）","opts":["衣冠禽兽本义","三大石窟","岁寒三友","古代服饰"],"ans":"B","atext":"三大石窟","src":"释义→词条","note":"三大石窟：敦煌莫高窟（甘肃）、云冈石窟（山西大同）、龙门石窟（河南洛阳）。"},{"q":"对梅、兰、竹、菊四种花木的美称，常喻高洁品格。（　）","opts":["岁寒三友","花中四君子","三大石窟","四大名亭"],"ans":"B","atext":"花中四君子","src":"释义→词条","note":"花中四君子：对梅、兰、竹、菊四种花木的美称，常喻高洁品格。"},{"q":"《报任安书》的作者是（　）","opts":["左丘明","刘向","苏洵","司马迁"],"ans":"D","atext":"司马迁","src":"作品→作者","note":"《报任安书》— 司马迁。原文标注：司马迁"},{"q":"《劝学》的作者是（　）","opts":["郦道元","庄周","荀子","刘向"],"ans":"C","atext":"荀子","src":"作品→作者","note":"《劝学》— 荀子。原文标注：荀子（名况）"}],"p2":[{"q":"『权，然后知轻重。』中「权」的意思是（　）","opts":["追究，审问；推崇","称量（轻重）。","旧事、前例","按照；像"],"ans":"B","atext":"称量（轻重）。","word":"权","type":"实词","note":"权：秤锤，名词作动词，称一称。"},{"q":"『至丹以荆卿为计，始速祸焉』中「速」的意思是（　）","opts":["停止","半夜","减少","招致"],"ans":"D","atext":"招致","word":"速","type":"实词","note":"速：招致，非“迅速”。"},{"q":"『令将军与臣有郤』中「郤」的意思是（　）","opts":["回归，回家；自首","献出、效力","从属二主，怀有二心","通“隙”，隔阂、嫌怨"],"ans":"D","atext":"通“隙”，隔阂、嫌怨","word":"郤","type":"实词","note":"“郤”通“隙”。"},{"q":"『而必为之辞』中「辞」的意思是（　）","opts":["属：连接；引：延长","确实，的确","托辞、借口","听说"],"ans":"C","atext":"托辞、借口","word":"辞","type":"实词","note":"为之辞：给它找个说辞/借口。"},{"q":"『今媪尊长安君之位』中「尊」的意思是（　）","opts":["把……当作边邑","使……地位尊贵","穿着礼服、戴着礼帽","尚：还；恨：遗憾"],"ans":"B","atext":"使……地位尊贵","word":"尊","type":"实词","note":"使动用法：使长安之位尊。"},{"q":"『俊臣与兴方推事对食』中「对食」的意思是（　）","opts":["共同进餐","认为……奇异","同“座”，座位","亲身，亲自"],"ans":"A","atext":"共同进餐","word":"对食","type":"实词","note":"「对食」：共同进餐"},{"q":"『郑伯克段于鄢』中「克」的意思是（　）","opts":["判断","战胜，攻克","尽、全","只、仅仅"],"ans":"B","atext":"战胜，攻克","word":"克","type":"实词","note":"此处指庄公击败共叔段，如二君相战故用“克”。"},{"q":"『曩者辱赐书』中「辱」的意思是（　）","opts":["做贵族的仆役","吝惜，吝啬。","谦辞，犹“承蒙”","通“拒”，把守"],"ans":"C","atext":"谦辞，犹“承蒙”","word":"辱","type":"实词","note":"表承蒙对方屈尊。"},{"q":"『假舟楫者，非能水也』中「水」的意思是（　）","opts":["怀抱（指抱负）","名词作动词，游水、游泳","伸长脖子，形容盼望殷切","指出缺点、错误"],"ans":"B","atext":"名词作动词，游水、游泳","word":"水","type":"实词","note":"名词“水”活用为动词。"},{"q":"『项伯杀人，臣活之』中「活」的意思是（　）","opts":["木杖荆条，古代刑具，指拷打","通\"型\"，作榜样。","亲善、和睦","使动，使……活、救活"],"ans":"D","atext":"使动，使……活、救活","word":"活","type":"实词","note":"使动用法，使之活。"}],"p3":[{"q":"君子疾夫舍曰欲之而必为之辞。","a":"君子最痛恨那种嘴上不说想要，却一定要为它找个借口的做法。","note":"疾：痛恨；辞：托辞；揭穿冉有文过饰非。","src":"季氏将伐颛臾"},{"q":"大行不顾细谨，大礼不辞小让。","a":"做大事不必顾及细枝末节，行大礼不必计较小的责备。","note":"“让”责备；互文。樊哙劝刘邦离席不必告辞。","src":"鸿门宴"},{"q":"盖尝慨夫为人之父祖者，每欲传其土田货财，而子孙未必能世富也；","a":"我曾感慨那些做父祖辈的，常常想把土地钱财传给子孙，但子孙不一定能世代富足；","note":"世：名词作状语，世代。三组排比起兴。","src":"传是楼记"},{"q":"今健庵先生既出其所得于书者，上为天子之所器重，次为中朝士大夫之所矜式，藉是以润色大业，对扬休命，有余矣，而又推之以训敕其子姓，俾后先跻巍科，取宦仕，翕然有名于当世，琬然后喟焉太息，以为读书之益弘矣哉！循是道也，虽传诸子孙世世，何不可之有？","a":"如今健庵先生既已拿出他从书中所得的，上为天子所器重，次为朝廷士大夫所敬仰效法，借此来润色大业，应对称扬美好的任命，绰绰有余了，又推而用来训导他的子孙，使他们先后登上高科、取得官职，一起在当世有名声，我然后感叹，认为读书的益处大啊！遵循这个道理，即使传给子孙世世代代，又有什么不可以呢？","note":"","src":"传是楼记"},{"q":"令壮者无取老妇，令老者无取壮妻；女子十七不嫁，其父母有罪；丈夫二十不取，其父母有罪。","a":"令壮年男子不得娶老妇，老年男子不得娶壮妻；女子十七不嫁、男子二十不娶，父母都定罪。","note":"取通娶。奖励生育的法令。","src":"勾践灭吴"},{"q":"千乘之国，摄乎大国之间，加之以师旅，因之以饥馑。","a":"一个拥有千辆兵车的国家，夹在大国之间，外有军队侵犯，内又接上饥荒。","note":"“加之以师旅”“因之以饥馑”均为状语后置，即“以师旅加之”“以饥馑因之”。","src":"子路曾皙冉有公西华侍坐"},{"q":"虎兕出于柙，龟玉毁于椟中，是谁之过与？","a":"猛虎犀牛从笼子里跑出来，龟甲美玉在匣子里毁坏，这是谁的过错呢？","note":"两处“于”字结构均状语后置；比喻季氏失责、冉有季路难辞其咎。","src":"季氏将伐颛臾"},{"q":"我决起而飞，抢榆枋而止，时则不至，而控于地而已矣。","a":"我迅速起飞，碰上榆树枋树就停下，有时飞不到，落在地上罢了。","note":"决起：疾起；抢：触、撞；控：落下。写蜩与学鸠的短见，与鹏对比。","src":"逍遥游"},{"q":"守一城，捍天下，以千百就尽之卒，战百万日滋之师，蔽遮江淮，沮遏其势，天下之不亡，其谁之功也！","a":"守住一座孤城，捍卫整个天下，率领千百名将要死尽的士兵，迎战百万日益增多的叛军，掩护了江淮大地，阻止了叛军攻势，天下之所以没有灭亡，那是谁的功劳呢！","note":"就尽：将死尽；日：名词作状语，一天天；其谁之功：反问语气。全句对偶排比，盛赞张巡许远之功。","src":"张中丞传后叙"},{"q":"此五子者，不产于秦，而穆公用之，并国二十，遂霸西戎。","a":"这五位贤士，都不出生在秦国，可是穆公重用他们，吞并了二十国，于是称霸西戎。","note":"“产”出生；“霸”名词作动词，称霸。举例论证四君用客之功。","src":"谏逐客书"},{"q":"至丹以荆卿为计，始速祸焉。","a":"等到燕太子丹用派荆轲刺杀秦王作为对策，才招致了祸患。","note":"速：招致（非迅速）。点出燕亡的直接原因。","src":"六国论"},{"q":"夫腹饥不得食，肤寒不得衣，虽慈母不能保其子，君安能以有其民哉！","a":"肚子饥饿没有吃的，皮肤寒冷没有衣穿，即使是慈爱的母亲也不能保全她的孩子，国君又怎么能拥有他的百姓呢！","note":"反问句加强语气；“安能”怎么能。推论明君必须务民农桑。","src":"论贵粟疏"},{"q":"故夫知效一官，行比一乡，德合一君，而征一国者，其自视也，亦若此矣。而宋荣子犹然笑之。且举世誉之而不加劝，举世非之而不加沮，定乎内外之分，辩乎荣辱之境，斯已矣。彼其于世，未数数然也。虽然，犹有未树也。","a":"所以那些才智足以胜任一个官职、品行能够联合一乡之人、德行能够使一国之君满意、能力能够取信于一国之人的人，他们看待自己，也像斥鴳这样罢了。而宋荣子还讥笑他们。而且全社会都称赞他，他也不会因此更加努力；全社会都非议他，他也不会因此更加沮丧。他认定了内我和外物的分际，辨明了光荣和耻辱的界限，这就罢了。他对于世俗的名誉，没有急切追求。虽然如此，他还是没有树立至高的境界。","note":"","src":"逍遥游"},{"q":"夫子喟然叹曰：“吾与点也！”","a":"孔子长叹一声说：“我赞同曾点的想法啊！”","note":"与（yù）：赞同；喟然：长叹的样子。","src":"子路曾皙冉有公西华侍坐"},{"q":"段不弟，故不言弟；如二君，故曰克。","a":"共叔段不守弟道，所以《春秋》不称弟；像两个国君交战，所以用“克”。","note":"点明《春秋》书法。弟：名词作动词，尽弟道。","src":"郑伯克段于鄢"},{"q":"凡为橱者七十有二，部居类汇，各以其次，素标缃帙，启钥灿然。","a":"一共做了七十二个书橱，按经史子集分类排列，各按次序，白色的标签、浅黄色的书套，打开锁后灿烂夺目。","note":"有通“又”；素标缃帙：形容藏书精良。写藏书之富。","src":"传是楼记"},{"q":"秋水时至，百川灌河。泾流之大，两涘渚崖之间，不辩牛马。于是焉河伯欣然自喜，以天下之美为尽在己。顺流而东行，至于北海，东面而视，不见水端。于是焉河伯始旋其面目，望洋向若而叹曰：\"野语有之曰：'闻道百，以为莫己若者。'我之谓也。且夫我尝闻少仲尼之闻而轻伯夷之义者，始吾弗信。今我睹子之难穷也，吾非至于子之门则殆矣，吾长见笑于大方之家。\"","a":"秋天的洪水按季节到来，许多河流的水注入黄河。水流的浩大，两岸和沙洲之间，连牛马都分辨不清。于是河伯欣然自喜，认为天下的美景全在自己这里。顺着水流向东行，到了北海，向东望去，看不到水的尽头。于是河伯才改变了他自得的面貌，望着大海对北海若感叹说：\"俗话有这样一种说法：'听了一百种道理，就以为没有人比得上自己。'说的就是我啊。而且我曾经听说有人小看孔子的见闻、轻视伯夷的道义，起初我不相信；如今我看到你这样难以穷尽，我如果不是来到你的门前就危险了，我将永远被有修养的人耻笑。\"","note":"","src":"秋水"},{"q":"是从我糠覈不得饱，一旦置身广厦，役婢仆，厌膏粱，彼意适，我愿慰矣，岂卖菜也而索直乎！","a":"这姑娘跟着我粗劣饭都吃不饱，一旦住进高楼大厦，使唤婢仆，饱食美味，她称心如意，我的心愿也满足了，难道是卖菜的还要讨价还价吗！","note":"厌通“餍”；直通“值”。写虞氏不要聘金，反常可疑。","src":"小翠"},{"q":"向使四君却客而不内，疏士而不用，是使国无富利之实，而秦无强大之名也。","a":"假使四位君主拒绝客卿而不予接纳，疏远贤士而不加任用，这就会使国家没有丰厚的实力，秦国也没有强大的名声了。","note":"“向使”假使；“内”通“纳”。反面假设论证（虚拟语气）。","src":"谏逐客书"},{"q":"他人有心，予忖度之。──夫子之谓也。","a":"别人有什么心思，我能揣测到。──说的就是先生您啊。","note":"\"夫子之谓也\"：宾语前置（谓夫子也），\"之\"作标志。","src":"齐桓晋文之事"}]},{"no":2,"date":"2026-10-30","date_end":"2026-10-31","pieces":["齐桓晋文之事","留侯论","谏逐客书","季氏将伐颛臾","张中丞传后叙","传是楼记"],"theme":"综合练习 2","p1":[{"q":"「且夫我尝闻少仲尼之闻而轻伯夷之义者。」出自（　）","opts":["《逍遥游》","《秋水》","《六国论》","《小翠》"],"ans":"B","atext":"《秋水》","src":"句子→篇目","note":"出自《秋水》。参考译文：况且我曾听说有人小看孔子的见闻、轻视伯夷的义行。"},{"q":"「对曰：“方六七十，如五六十，求也为之，比及三年，可使足民。如其礼乐，以俟君子。”」出自（　）","opts":["《郑伯克段于鄢》","《季氏将伐颛臾》","《子路曾皙冉有公西华侍坐》","《钴鉧潭西小丘记》"],"ans":"C","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：冉求回答说：\"方圆六七十里或者五六十里的地方，让我冉求去治理，等到三年，可以使百姓富足。至于礼乐教化，就要等待君子来推行了。\""},{"q":"「是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。行衢道者不至，事两君者不容。目不能两视而明，耳不能两听而聪。螣蛇无足而飞，鼫鼠五技而穷。《诗》曰：“尸鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮！”故君子结于一也。」出自（　）","opts":["《留侯论》","《小翠》","《六国论》","《劝学》"],"ans":"D","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：所以没有潜心专一的志向的人，就没有明显的智慧；没有埋头苦干的人，就没有显赫的功业。走岔路的人到不了目的地，同时侍奉两个君主的人不被容纳。眼睛不能同时看两处而看清，耳朵不能同时听两处"},{"q":"「小知不及大知，小年不及大年。」出自（　）","opts":["《逍遥游》","《许行》","《勾践灭吴》","《秋水》"],"ans":"A","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：小智慧比不上大智慧，短寿命比不上长寿命。"},{"q":"「然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之愈急。」出自（　）","opts":["《谏逐客书》","《六国论》","《勾践灭吴》","《吕相绝秦》"],"ans":"B","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：既然这样，那么诸侯的土地有限，强暴的秦国的欲望永远不会满足，诸侯送给它的越多，它侵犯得就越急迫。"},{"q":"「方六七十，如五六十，求也为之，比及三年，可使足民。」出自（　）","opts":["《子路曾皙冉有公西华侍坐》","《齐桓晋文之事》","《烛之武退秦师》","《邹忌讽齐王纳谏》"],"ans":"A","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：纵横六七十里或五六十里的小国，让我冉求去治理，三年可使百姓富足。"},{"q":"「民贫，则奸邪生。贫生于不足，不足生于不农，不农则不地著，不地著则离乡轻家，民如鸟兽。」出自（　）","opts":["《齐桓公伐楚》","《劝学》","《钴鉧潭西小丘记》","《论贵粟疏》"],"ans":"D","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：百姓贫穷，就会生出奸邪之事。贫穷产生于财物不足，财物不足产生于不务农，不务农就不能安居乡土，不能安居乡土就会轻易背离家乡，百姓就像鸟兽一样（难以驯服）。"},{"q":"「异史氏曰：“一狐也，以无心之德，而犹思所报；而身受再造之福者，顾失声于破甑，何其鄙哉！月缺重圆，从容而去，始知仙人之情亦更深于流俗也！”」出自（　）","opts":["《逍遥游》","《鸿门宴》","《小翠》","《秋水》"],"ans":"C","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：异史氏说：一只狐狸，因为人家无意中的恩德，还想着要报答；而身受再造之恩的人，却为打破一只瓦罐而失声痛哭，多么鄙薄啊！月亮缺了又圆，小翠从容离去，这才知道仙人的情谊也比世俗之人更深啊"},{"q":"「子犯请击之。公曰：“不可。微夫人之力不及此。因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。吾其还也。”亦去之。」出自（　）","opts":["《留侯论》","《郑伯克段于鄢》","《烛之武退秦师》","《子路曾皙冉有公西华侍坐》"],"ans":"C","atext":"《烛之武退秦师》","src":"句子→篇目","note":"出自《烛之武退秦师》。参考译文：子犯请求攻击秦军。晋文公说：\"不行。如果没有那个人的力量，我到不了今天这个地位。依靠别人的力量却又损害他，是不仁；失去自己的同盟者，是不明智；用混乱代替整齐，是不勇武。我们还是回去"},{"q":"「寡人不知其力之不足也，而又与大国执仇，以暴露百姓之骨于中原。」出自（　）","opts":["《季氏将伐颛臾》","《齐桓晋文之事》","《巫山巫峡》","《勾践灭吴》"],"ans":"D","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：我不自量力，又同大国结仇，使百姓尸骨暴露在原野上。"},{"q":"「于是焉河伯始旋其面目，望洋向若而叹曰。」出自（　）","opts":["《秋水》","《小翠》","《六国论》","《许行》"],"ans":"A","atext":"《秋水》","src":"句子→篇目","note":"出自《秋水》。参考译文：这时河伯才转过脸色，仰望着北海若感叹道。"},{"q":"「我孰与城北徐公美？」出自（　）","opts":["《论贵粟疏》","《吕相绝秦》","《邹忌讽齐王纳谏》","《传是楼记》"],"ans":"C","atext":"《邹忌讽齐王纳谏》","src":"句子→篇目","note":"出自《邹忌讽齐王纳谏》。参考译文：我同城北徐公相比，哪一个美？"},{"q":"斗拱（承重装饰）、飞檐、藻井、影壁、月洞门、须弥座。（　）","opts":["古代服饰","古代建筑构件","衣冠禽兽本义","江南三大名楼"],"ans":"B","atext":"古代建筑构件","src":"释义→词条","note":"古代建筑构件：斗拱（承重装饰）、飞檐、藻井、影壁、月洞门、须弥座。"},{"q":"明代文官绣禽、武官绣兽于补服，本指官员服饰，后转贬义。（　）","opts":["岁寒三友","衣冠禽兽本义","四大名亭","花中四君子"],"ans":"B","atext":"衣冠禽兽本义","src":"释义→词条","note":"衣冠禽兽本义：明代文官绣禽、武官绣兽于补服，本指官员服饰，后转贬义。"},{"q":"指松、竹、梅，经冬不凋，象征坚贞品格。（　）","opts":["江南三大名楼","岁寒三友","文房四宝","衣冠禽兽本义"],"ans":"B","atext":"岁寒三友","src":"释义→词条","note":"岁寒三友：指松、竹、梅，经冬不凋，象征坚贞品格。"},{"q":"冕（帝王礼帽）、冠（贵族男子首服）、帻（平民头巾）、深衣（上下连体）、袍、襦裙、履、屐。（　）","opts":["古代服饰","四大名亭","三大石窟","文房四宝"],"ans":"A","atext":"古代服饰","src":"释义→词条","note":"古代服饰：冕（帝王礼帽）、冠（贵族男子首服）、帻（平民头巾）、深衣（上下连体）、袍、襦裙、履、屐。"},{"q":"古代平民的代称。“布衣”指平民穿麻葛之衣；“黔首”指秦代百姓，因以黑巾裹头。（　）","opts":["布衣、黔首","四大佛教名山","干支与生肖","四声"],"ans":"A","atext":"布衣、黔首","src":"释义→词条","note":"布衣、黔首：古代平民的代称。“布衣”指平民穿麻葛之衣；“黔首”指秦代百姓，因以黑巾裹头。"},{"q":"五人为伍，五伍为两，四两为卒，五卒为旅，五旅为师，五师为军（周制）。（　）","opts":["布衣、黔首","八拜之交","古代军事编制","四大佛教名山"],"ans":"C","atext":"古代军事编制","src":"释义→词条","note":"古代军事编制：五人为伍，五伍为两，四两为卒，五卒为旅，五旅为师，五师为军（周制）。"},{"q":"《勾践灭吴》的作者是（　）","opts":["刘向","苏轼","左丘明","荀子"],"ans":"C","atext":"左丘明","src":"作品→作者","note":"《勾践灭吴》— 左丘明。原文标注：左丘明（相传）"},{"q":"《谏逐客书》的作者是（　）","opts":["庄周","苏轼","韩愈","李斯"],"ans":"D","atext":"李斯","src":"作品→作者","note":"《谏逐客书》— 李斯。原文标注：李斯"}],"p2":[{"q":"『可以笼而有之』中「笼」的意思是（　）","opts":["装进笼子，包笼","姑且，暂且","使动，使……成就功业","亲身，亲自"],"ans":"A","atext":"装进笼子，包笼","word":"笼","type":"实词","note":"名词作状语，用笼子装。"},{"q":"『赐我先君履』中「履」的意思是（　）","opts":["践踏的界限，指得专征伐的范围","通“汝”，你，你们","同进同退，步调一致","通“避”，躲避"],"ans":"A","atext":"践踏的界限，指得专征伐的范围","word":"履","type":"实词","note":"指齐太公可征伐的范围。"},{"q":"『子必穷矣』中「穷」的意思是（　）","opts":["绝，灭","小孩","抬眼","穷困"],"ans":"D","atext":"穷困","word":"穷","type":"实词","note":"「穷」：穷困"},{"q":"『是以太山不让土壤』中「让」的意思是（　）","opts":["（yù）告诉","暴露、冒着","投，落下，跌落。","辞让、拒绝"],"ans":"D","atext":"辞让、拒绝","word":"让","type":"实词","note":"“让”与“却、择”同义，拒绝嫌弃。"},{"q":"『焉用亡郑以陪邻』中「陪」的意思是（　）","opts":["增加","名声","抬眼","后来"],"ans":"A","atext":"增加","word":"陪","type":"实词","note":"陪邻：增加邻（晋）的土地。"},{"q":"『而绝江河』中「绝」的意思是（　）","opts":["横渡、横穿","因为","船桨","一起"],"ans":"A","atext":"横渡、横穿","word":"绝","type":"实词","note":"特指横断水流而渡。"},{"q":"『太祖悉将诸子登台』中「悉」的意思是（　）","opts":["罢了","年","都","很"],"ans":"C","atext":"都","word":"悉","type":"实词","note":"「悉」：都"},{"q":"『没死以闻』中「没死」的意思是（　）","opts":["等到","空闲。","冒死","叩头"],"ans":"C","atext":"冒死","word":"没死","type":"实词","note":"没死：冒死罪，表恭敬；闻：使上级听到、禀告。"},{"q":"『张良出，要项伯』中「要」的意思是（　）","opts":["使……变红（杀灭）","通“蓄”，积蓄（音xù）","通“邀”，邀请","往，到……去。"],"ans":"C","atext":"通“邀”，邀请","word":"要","type":"实词","note":"“要”读yāo，通“邀”。"},{"q":"『声非加疾也』中「疾」的意思是（　）","opts":["通“俸”，俸禄","通“曝”，晒干（音pù）","把……当作边邑","强，这里指声音宏大"],"ans":"D","atext":"强，这里指声音宏大","word":"疾","type":"实词","note":"“疾”此处指声势强。"}],"p3":[{"q":"臣未之闻也。","a":"我没有听说过这件事。","note":"宾语前置（未闻之），否定句代词\"之\"作宾语前置。","src":"齐桓晋文之事"},{"q":"匹夫见辱，拔剑而起，挺身而斗，此不足为勇也。","a":"普通人被侮辱，就拔起剑站起身，挺身上前搏斗，这算不上勇敢。","note":"见：表被动。以“匹夫之勇”反衬下文“大勇”。","src":"留侯论"},{"q":"王曰：\"否，吾何快于是，将以求吾所大欲也。\"","a":"宣王说：\"不，我怎么会对这些感到痛快，我是想借此求得我最想要的东西。\"","note":"","src":"齐桓晋文之事"},{"q":"无恒产而有恒心者，惟士为能；若民，则无恒产，因无恒心。","a":"没有固定产业而有恒定心志的，只有读书人能做到；至于百姓，没有固定产业，就没有恒定心志。","note":"恒产：固定产业。提出制民之产的仁政主张。","src":"齐桓晋文之事"},{"q":"昭王得范雎，废穰侯，逐华阳，强公室，杜私门，蚕食诸侯，使秦成帝业。","a":"昭王得到范雎，废黜穰侯，驱逐华阳君，加强王室权力，堵塞权贵私门，像蚕吃桑叶一样逐步侵占诸侯，使秦国成就帝王基业。","note":"“强”使动（使公室强）；“蚕食”名词作状语（像蚕一样）。四句四事，排比紧凑。","src":"谏逐客书"},{"q":"季氏将有事于颛臾。","a":"季孙氏将要对颛臾动兵。","note":"“于颛臾”状语后置；“有事”讳言用兵。","src":"季氏将伐颛臾"},{"q":"及其无救而且穷也，将其创残饿羸之余，虽欲去，必不达。","a":"等到没有救兵而且处境困窘的时候，率领着那些受伤饥饿残剩的士卒，即使想撤离，也必定到不了。","note":"穷：困厄；创残饿羸：受伤残弱、饥饿瘦弱；将（jiàng）：率领。","src":"张中丞传后叙"},{"q":"曰：\"有复于王者曰：吾力足以举百钧，而不足以举一羽；明足以察秋毫之末，而不见舆薪。则王许之乎？\"","a":"孟子说：\"如果有人向大王报告说：我的力气足以举起三千斤，却举不起一根羽毛；我的视力足以看清秋天鸟兽新生细毛的末梢，却看不见一车柴草。那么大王相信他吗？\"","note":"","src":"齐桓晋文之事"},{"q":"不得已勉承先生之命，姑为一言复之，先生亦恕其老誖否耶？","a":"不得已勉强承受先生的嘱托，姑且说几句话回复您，先生能原谅我的老昏谬乱吧？","note":"老誖（bèi）：老昏悖乱。以谦辞作结。","src":"传是楼记"},{"q":"循是道也，虽传诸子孙世世，何不可之有？","a":"遵循这条道路，即使把它传给子子孙孙世世代代，又有什么不可以呢？","note":"何不可之有：宾语前置（有何不可）。赞徐氏传书之道。","src":"传是楼记"},{"q":"后稷教民稼穑，树艺五谷，五谷熟而民人育。","a":"后稷教百姓庄稼，种植五谷，五谷成熟了百姓才能养育繁衍。","note":"树、艺：种植。写后稷教农之功。","src":"许行"},{"q":"《齐谐》者，志怪者也。《谐》之言曰：\"鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。\"野马也，尘埃也，生物之以息相吹也。天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。","a":"《齐谐》这本书，是记载怪异之事的。《齐谐》上说：\"鹏迁往南海的时候，翅膀拍击水面激起三千里波涛，乘着旋风盘旋而上升到九万里高空，是凭借六月的大风而离去的。\"像野马奔腾的雾气，飞扬的尘埃，都是生物用气息相互吹拂的结果。天空苍苍茫茫，那是它真正的颜色吗？还是因为高远而看不到尽头呢？大鹏从高空往下看，也不过就像这样罢了。","note":"","src":"逍遥游"},{"q":"吾何以传女曹哉？吾徐先世，故以清白起家，吾耳目濡染旧矣。","a":"我拿什么东西传给你们呢？我们徐家先世，本来就以清白操守起家，我耳濡目染已经很久了。","note":"女（rǔ）通“汝”，你们。领起传家之问。","src":"传是楼记"},{"q":"观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。项籍唯不能忍，是以百战百胜而轻用其锋；高祖忍之，养其全锋而待其弊，此子房教之也。当淮阴破齐而欲自王，高祖发怒，见于词色。由此观之，犹有刚强不忍之气，非子房其谁全之？","a":"看汉高祖之所以胜利、项羽之所以失败的原因，就在能忍与不能忍之间罢了。项羽只因不能忍，所以百战百胜却轻易使用他的锋芒；汉高祖能忍耐，保全他的全部锋芒来等待项羽的疲敝，这是张良教他的。当淮阴侯攻破齐国想自立为王时，汉高祖发怒，表现在言辞脸色上。由此看来，他还有刚强不能忍的气质，如果不是张良，谁能保全他呢？","note":"","src":"留侯论"},{"q":"贾人夏则资皮，冬则资絺，旱则资舟，水则资车，以待乏也。","a":"商人夏天就囤皮货，冬天就备细葛布，旱时备船，水时备车，用来等待缺乏时使用。","note":"排比设喻，说明平时要早作准备。","src":"勾践灭吴"},{"q":"于是入朝见威王，曰：“臣诚知不如徐公美。臣之妻私臣，臣之妾畏臣，臣之客欲有求于臣，皆以美于徐公。今齐地方千里，百二十城，宫妇左右莫不私王，朝廷之臣莫不畏王，四境之内莫不有求于王：由此观之，王之蔽甚矣。”","a":"于是邹忌上朝拜见齐威王，说：\"我确实知道自己不如徐公美。可是我的妻子偏爱我，我的妾害怕我，我的客人有求于我，他们都认为我比徐公美。如今齐国土地方圆千里，有一百二十座城池，宫中的妃子和身边的近臣没有不偏爱大王的，朝廷上的大臣没有不害怕大王的，全国范围内的人没有不对大王有所求的：由此看来，大王受到的蒙蔽太厉害了。\"","note":"","src":"邹忌讽齐王纳谏"},{"q":"老者衣帛食肉，黎民不饥不寒：然而不王者，未之有也。","a":"老年人穿丝帛、吃肉食，百姓不挨饿受冻：这样还不能统一天下，是从来没有过的事。","note":"衣(yì)：名作动，穿；未之有：宾语前置（未有之）。全文以仁政蓝图作结。","src":"齐桓晋文之事"},{"q":"太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令，其次诎体受辱，其次易服受辱，其次关木索、被箠楚受辱，其次剔毛发、婴金铁受辱，其次毁肌肤、断肢体受辱，最下腐刑极矣。","a":"最上等的是不使祖先受辱，其次是不使自身受辱，其次是不在道理脸色上受辱，其次是不在言辞上受辱，其次是被捆绑受辱，其次是换上囚服受辱，其次是戴上木枷绳索、遭刑杖拷打受辱，其次是剃发戴铁圈受辱，其次是毁坏肌肤、截断肢体受辱，最下等的就是受腐刑，这达到屈辱的顶点了。","note":"“太上”最上等；“辱”均使动，使……受辱；“诎”通“屈”；“婴”缠绕（颈戴铁索）。十层排比递降，极写受辱等次，突出腐刑为奇耻大辱，故下文引《记》“刑不上大夫”。","src":"报任安书"},{"q":"劳之来之，匡之直之，辅之翼之，使自得之，又从而振德之。","a":"慰劳他们，招揽他们，纠正他们，扶助他们，保护他们，使他们自得向善，又接着救济他们、对他们施恩德。","note":"振通\"赈\"，救济。写圣人忧民、教化之勤。","src":"许行"},{"q":"夫既已读之矣，而或口与躬违，心与迹忤，采其华而忘其实，是则呻占记诵之学所为哗众而窃名者也，与弗读奚以异哉！","a":"既然已经读了，但有的嘴上说的和亲身做的相违背，心里想的和实际做的相抵触，采摘它的花却忘了它的果，这就是那些吟哦记诵之学用来哗众取宠、盗取名声的东西，跟不读书又有什么不同呢！","note":"华实对举；奚以异：有何不同。批判脱离实践的记诵之学。","src":"传是楼记"}]},{"no":3,"date":"2026-10-31","date_end":"2026-11-01","pieces":["巫山巫峡","报任安书","吕相绝秦","许行","逍遥游","齐桓晋文之事"],"theme":"综合练习 3","p1":[{"q":"「夫差将欲听，与之成。子胥谏曰：“不可！夫吴之与越也，仇讎敌战之国也；三江环之，民无所移。有吴则无越，有越则无吴。将不可改于是矣！员闻之：陆人居陆，水人居水，夫上党之国，我攻而胜之，吾不能居其地，不能乘其车；夫越国，吾攻而胜之，吾能居其地，吾能乘其舟。此其利也，不可失也已。君必灭之！失此利也，虽悔之，必无及已。”」出自（　）","opts":["《许行》","《巫山巫峡》","《勾践灭吴》","《留侯论》"],"ans":"C","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：夫差想要答应，和越国讲和。伍子胥劝谏说：\"不行！吴国和越国是仇敌交战之国；三江环绕着他们，百姓无处迁移。有吴国就没有越国，有越国就没有吴国，这是不可改变的。我听说：陆地的人居住在陆"},{"q":"「给谏愈疑，谋遂寝，由此益交欢公。」出自（　）","opts":["《逍遥游》","《留侯论》","《小翠》","《秋水》"],"ans":"C","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：王给谏越发怀疑，阴谋就中止了，从此反而同王太常交好。"},{"q":"「此虽免乎行，犹有所待者也。」出自（　）","opts":["《留侯论》","《六国论》","《逍遥游》","《秋水》"],"ans":"C","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：列子这样虽然免于步行，终究还是有所凭借。"},{"q":"「猛虎处深山，百兽震恐，及在槛阱之中，摇尾而求食，积威约之渐也。」出自（　）","opts":["《报任安书》","《邹忌讽齐王纳谏》","《许行》","《传是楼记》"],"ans":"A","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：猛虎处在深山，百兽都害怕；等到它被关在笼圈陷阱之中，就摇着尾巴求食，这是长期受威力约束逐渐形成的。"},{"q":"「以母遭雷霆之劫，深受而翁庇翼；又以我两人有五年夙分，故以我来报曩恩、了夙愿耳。」出自（　）","opts":["《六国论》","《劝学》","《秋水》","《小翠》"],"ans":"D","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：因为我母亲遭到雷霆之劫，深受你父亲的庇护；又因为我同你有五年的前定缘分，所以我来报答旧日的恩情、了结夙愿罢了。"},{"q":"「尊所闻，行所知，非善读书者而能如是乎！」出自（　）","opts":["《钴鉧潭西小丘记》","《传是楼记》","《秋水》","《勾践灭吴》"],"ans":"B","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：尊重所听到的道理，力行所学到的知识，不是善于读书的人能做到这样吗！"},{"q":"「故木受绳则直，金就砺则利，君子博学而日参省乎己，则知明而行无过矣。」出自（　）","opts":["《逍遥游》","《小翠》","《劝学》","《留侯论》"],"ans":"C","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：所以木材经墨线量过就笔直，刀剑拿到磨刀石上磨就锋利；君子广博学习并且每天反省自己，就智慧明达、行为没有过错了。"},{"q":"「大隧之外，其乐也泄泄！」出自（　）","opts":["《郑伯克段于鄢》","《季氏将伐颛臾》","《谏逐客书》","《勾践灭吴》"],"ans":"A","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：走出大隧之外，那快乐啊舒畅和畅！"},{"q":"「君子曰：“颍考叔，纯孝也。爱其母，施及庄公。《诗》曰：‘孝子不匮，永锡尔类。’其是之谓乎？”」出自（　）","opts":["《报任安书》","《齐桓公伐楚》","《六国论》","《郑伯克段于鄢》"],"ans":"D","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：君子说：\"颍考叔是真正的孝子。爱自己的母亲，并把这种爱推及庄公。《诗经》说：'孝子的孝心没有穷尽，永远赐给你的同类。'大概说的就是这种情况吧？\""},{"q":"「曰：\"殆有甚焉。缘木求鱼，虽不得鱼，无后灾；以若所为，求若所欲，尽心力而为之，后必有灾。\"」出自（　）","opts":["《钴鉧潭西小丘记》","《齐桓晋文之事》","《子路曾皙冉有公西华侍坐》","《季氏将伐颛臾》"],"ans":"B","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：孟子说：\"恐怕比这更严重。爬到树上找鱼，虽然得不到鱼，却没有后患；凭您这样的做法追求您想要的东西，尽心尽力去做，以后一定有灾祸。\""},{"q":"「翁无烦怒。有新妇在，刀锯斧钺妇自受之，必不令贻害双亲。」出自（　）","opts":["《小翠》","《六国论》","《秋水》","《留侯论》"],"ans":"A","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：公公不要发怒。有儿媳在，刀锯斧钺我自己承受，一定不会让灾祸连累双亲。"},{"q":"「子路率尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；由也为之，比及三年，可使有勇，且知方也。”」出自（　）","opts":["《子路曾皙冉有公西华侍坐》","《齐桓晋文之事》","《邹忌讽齐王纳谏》","《郑伯克段于鄢》"],"ans":"A","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：子路轻率地抢先回答说：\"一个拥有千辆兵车的国家，夹在大国之间，外面有军队侵犯，国内又遇上饥荒；让我仲由去治理，等到三年，可以使百姓有勇气，而且懂得礼义道理。\""},{"q":"指管鲍之交、知音之交（伯牙子期）、刎颈之交（廉颇蔺相如）、舍命之交（羊角哀左伯桃）、胶漆之交（陈重雷义）、鸡黍之交（范式张劭）、忘年之交（孔融祢衡）、生死之交（刘备关羽张飞）。（　）","opts":["古代军事编制","敕、诏、诰","八拜之交","布衣、黔首"],"ans":"C","atext":"八拜之交","src":"释义→词条","note":"八拜之交：指管鲍之交、知音之交（伯牙子期）、刎颈之交（廉颇蔺相如）、舍命之交（羊角哀左伯桃）、胶漆之交（陈重雷义）、鸡黍之交（范式张劭）、忘年之交（孔融祢衡）、生死之交（刘备关羽张飞）。"},{"q":"子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。（　）","opts":["六书","四大佛教名山","布衣、黔首","干支与生肖"],"ans":"D","atext":"干支与生肖","src":"释义→词条","note":"干支与生肖：子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。"},{"q":"古代帝王的文书命令，皇帝发布的命令文告称诏、敕、诰。（　）","opts":["八拜之交","六书","敕、诏、诰","古代军事编制"],"ans":"C","atext":"敕、诏、诰","src":"释义→词条","note":"敕、诏、诰：古代帝王的文书命令，皇帝发布的命令文告称诏、敕、诰。"},{"q":"五台山（文殊，山西）、峨眉山（普贤，四川）、普陀山（观音，浙江）、九华山（地藏，安徽）。道教四大名山：武当山、龙虎山、齐云山、青城山。（　）","opts":["干支与生肖","八拜之交","敕、诏、诰","四大佛教名山"],"ans":"D","atext":"四大佛教名山","src":"释义→词条","note":"四大佛教名山：五台山（文殊，山西）、峨眉山（普贤，四川）、普陀山（观音，浙江）、九华山（地藏，安徽）。道教四大名山：武当山、龙虎山、齐云山、青城山。"},{"q":"这类诗大概有30首；《小雅·采薇》（　）","opts":["删诗","战争徭役诗","写作手法","风——160"],"ans":"B","atext":"战争徭役诗","src":"释义→词条","note":"战争徭役诗：这类诗大概有30首；《小雅·采薇》"},{"q":"《魏风·硕鼠》；《邶风·新台》（　）","opts":["采诗","战争徭役诗","写作手法","怨刺诗"],"ans":"D","atext":"怨刺诗","src":"释义→词条","note":"怨刺诗：《魏风·硕鼠》；《邶风·新台》"},{"q":"《邹忌讽齐王纳谏》的作者是（　）","opts":["刘向","苏轼","蒲松龄","晁错"],"ans":"A","atext":"刘向","src":"作品→作者","note":"《邹忌讽齐王纳谏》— 刘向。原文标注：刘向 辑录（《战国策》）"},{"q":"《秋水》的作者是（　）","opts":["李斯","晁错","汪琬","庄周"],"ans":"D","atext":"庄周","src":"作品→作者","note":"《秋水》— 庄周。原文标注：庄周（庄子）"}],"p2":[{"q":"『驻马观之』中「观」的意思是（　）","opts":["白绢","看；阅读","通“熟”，仔细","说，谈论。"],"ans":"B","atext":"看；阅读","word":"观","type":"实词","note":"「观」：看；阅读"},{"q":"『善属文』中「属」的意思是（　）","opts":["通“隙”，空隙，引申为身体不适","写；同“嘱”，嘱咐，嘱托","通“暮”，晚","尚：还；恨：遗憾"],"ans":"B","atext":"写；同“嘱”，嘱咐，嘱托","word":"属","type":"实词","note":"「属」：写；同“嘱”，嘱咐，嘱托"},{"q":"『宜泣而答曰』中「宜」的意思是（　）","opts":["应当，应该","半步（音kuǐ）","通“汝”，你","摆出威风"],"ans":"A","atext":"应当，应该","word":"宜","type":"实词","note":"「宜」：应当，应该"},{"q":"『能加于此评乎？』中「加」的意思是（　）","opts":["超过，胜过","戴帽子。","回归，回家；自首","并力，合力"],"ans":"A","atext":"超过，胜过","word":"加","type":"实词","note":"「加」：超过，胜过"},{"q":"『多作自能见之』中「自」的意思是（　）","opts":["这样；你","自己，自然","驻军","侵害"],"ans":"B","atext":"自己，自然","word":"自","type":"实词","note":"「自」：自己，自然"},{"q":"『微夫人之力不及此』中「夫人」的意思是（　）","opts":["通\"辨\"，分别，区别。","堵塞、杜绝","资助、供给","那个人，指秦穆公"],"ans":"D","atext":"那个人，指秦穆公","word":"夫人","type":"实词","note":"夫（fú）指示代词。今义为妻子。"},{"q":"『何乃似郤正语邪』中「何乃」的意思是（　）","opts":["许久，很久","贴近","为什么","即使"],"ans":"C","atext":"为什么","word":"何乃","type":"实词","note":"「何乃」：为什么"},{"q":"『太后命来俊臣鞫之』中「鞫」的意思是（　）","opts":["审问","种植。","原本","等待"],"ans":"A","atext":"审问","word":"鞫","type":"实词","note":"「鞫」：审问"},{"q":"『仆虽罢驽』中「罢」的意思是（　）","opts":["考订、探究","通“疲”，疲弱无能","估计，猜测","及其、非常"],"ans":"B","atext":"通“疲”，疲弱无能","word":"罢","type":"实词","note":"“罢”读pí，通“疲”；罢驽喻才能低下。"},{"q":"『能面刺寡人之过者』中「刺」的意思是（　）","opts":["教诲","后到","指责","查看"],"ans":"C","atext":"指责","word":"刺","type":"实词","note":"面刺：当面指责（过失）。"}],"p3":[{"q":"春冬之时，则素湍绿潭，回清倒影。","a":"春冬季节，白色的急流、碧绿的深潭，回旋的清波倒映着山石林木的影子。","note":"素湍：白色急流；回清：回旋的清波。一句之中动静、色彩相映。","src":"巫山巫峡"},{"q":"所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后世也。","a":"我所以暗暗忍受、苟且活下来，被囚禁在污秽之地而不肯死，是遗憾自己心愿未了，怕默默无闻而死，文章才华不能显露于后世。","note":"“所以……者，……也”表原因判断；“恨”遗憾。点明忍辱著书之志。","src":"报任安书"},{"q":"秦大夫不询于我寡君，擅及郑盟。","a":"秦国大夫不征询我们国君意见，擅自与郑国订盟。","note":"询：问。指责秦背晋私盟郑。","src":"吕相绝秦"},{"q":"当尧之时，天下犹未平，洪水横流，泛滥于天下。","a":"在尧的时候，天下还不安定，洪水横流，泛滥于天下。","note":"极言尧时之忧患，说明圣人劳心治水、教化。","src":"许行"},{"q":"且夫水之积也不厚，则其负大舟也无力。覆杯水于坳堂之上，则芥为之舟。置杯焉则胶，水浅而舟大也。风之积也不厚，则其负大翼也无力。故九万里则风斯在下矣，而后乃今培风；背负青天而莫之夭阏者，而后乃今将图南。","a":"再说水的积聚不深厚，那么它负载大船就没有力量。倒一杯水在堂上低洼处，那么一根小草浮在上面就成了船；放上一只杯子就粘住不动了，这是水太浅而船太大的缘故。风的积聚不深厚，那么它负载巨大的翅膀就没有力量。所以大鹏飞上九万里高空，风就在它的下面了，然后才凭借风力；背负青天而没有什么阻碍它，然后才打算往南飞。","note":"","src":"逍遥游"},{"q":"曰：\"然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。海内之地，方千里者九，齐集有其一；以一服八，何以异于邹敌楚哉？盖亦反其本矣。今王发政施仁，使天下仕者皆欲立于王之朝，耕者皆欲耕于王之野，商贾皆欲藏于王之市，行旅皆欲出于王之涂，天下之欲疾其君者，皆欲赴愬于王；其若是，孰能御之？\"","a":"孟子说：\"那么小国本来不可以抵挡大国，人口少的本来不可以抵挡人口多的，弱国本来不可以抵挡强国。四海之内，方圆千里的共有九份，齐国聚拢起来只占其中一份；凭一份去征服八份，这和邹国抵挡楚国有什么不同呢？何不回到根本上呢。如今大王发布政令、施行仁政，使天下做官的人都想到大王的朝廷上任职，耕田的人都想到大王的田野里耕种，商人都想到大王的市场上做买卖，旅客都想取道大王的道路，天下痛恨自己君主的人都想到大王这里来申诉；如果这样，谁能抵挡呢？\"","note":"","src":"齐桓晋文之事"},{"q":"怒而飞，其翼若垂天之云。","a":"（鹏）振翅奋起而飞，它的翅膀就像天边垂下的云。","note":"怒：奋发；垂天：天边。以夸张比喻写鹏翼之大，为下文\"小大之辩\"张本。","src":"逍遥游"},{"q":"泾流之大，两涘渚崖之间，不辩牛马。","a":"水流宽阔，两岸和水中沙洲之间，连牛马都分辨不清。","note":"辩通\"辨\"。极写河水之大，为河伯\"以天下之美为尽在己\"张本。","src":"秋水"},{"q":"范增数目项王，举所佩玉玦以示之者三，项王默然不应。","a":"范增多次向项王使眼色，再三举起所佩戴的玉玦暗示项王，项王沉默着没有反应。","note":"“目”名词作动词，递眼色；“三”多次。写范增暗示刺杀而项羽犹豫。","src":"鸿门宴"},{"q":"燕、赵、韩、魏闻之，皆朝于齐。","a":"燕、赵、韩、魏四国听到这件事，都来齐国朝见。","note":"“朝于齐”状语后置，即“于齐朝”；“朝”读cháo，朝见。","src":"邹忌讽齐王纳谏"},{"q":"上下相反，好恶乖迕，而欲国富法立，不可得也。","a":"上下相反，爱好和厌恶相违背，却想要国家富强、法律建立，是不可能的。","note":"“乖迕”违背。总结重农抑商政策名实不符之弊。","src":"论贵粟疏"},{"q":"孔子曰：“求！君子疾夫舍曰欲之而必为之辞。丘也闻有国有家者，不患寡而患不均，不患贫而患不安。盖均无贫，和无寡，安无倾。夫如是，故远人不服，则修文德以来之。既来之，则安之。今由与求也，相夫子，远人不服而不能来也；邦分崩离析而不能守也；而谋动干戈于邦内。吾恐季孙之忧，不在颛臾，而在萧墙之内也。”","a":"孔子说：\"冉求！君子痛恨那种不说自己想要却一定要另找借口的态度。我听说拥有国家的诸侯和拥有采邑的卿大夫，不担心贫穷而担心分配不均，不担心人口少而担心不安定。因为平均就不会贫穷，和睦就不会觉得人少，安定就不会倾覆。像这样，所以远方的人不归服，就修治文教德政来使他们归附。使他们来了，就要使他们安定。如今仲由和冉求你们两个人辅佐季氏，远方的人不归服却不能使他们来归；国家分崩离析却不能保全；反而想在国境之内发动战争。我恐怕季孙氏的忧患，不在颛臾，而在宫墙之内啊。\"","note":"","src":"季氏将伐颛臾"},{"q":"太后之色少解。","a":"太后的怒色稍微消解了些。","note":"少：稍微；解：消解。侧面写进谏初见成效。","src":"触龙说赵太后"},{"q":"且燕、赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。","a":"况且燕赵两国正处在秦国把其他国家几乎消灭干净的时候，可以说是智谋穷竭、势力孤单，战败而亡，实在是不得已。","note":"智力：智谋和力量（古今异义）；诚：实在。为燕赵辩护。","src":"六国论"},{"q":"元和二年四月十三日夜，愈与吴郡张籍阅家中旧书，得李翰所为《张巡传》。翰以文章自名，为此传颇详密。然尚恨有阙者：不为许远立传，又不载雷万春事首尾。","a":"元和二年四月十三日夜晚，我和吴郡张籍翻阅家中旧书，看到李翰所作的《张巡传》。李翰以文章自负，写这篇传颇为详尽周密。但还遗憾有缺漏：没有给许远立传，又没有记载雷万春事迹的始末。","note":"","src":"张中丞传后叙"},{"q":"为文章，操纸笔立书，未尝起草。","a":"写起文章来，拿起纸笔立刻写成，从不打草稿。","note":"操：拿；立书：立刻写就。侧面写张巡之才。","src":"张中丞传后叙"},{"q":"今媪尊长安君之位，而封之以膏腴之地。","a":"现在您使长安君地位尊贵，把肥沃的土地封给他。","note":"尊：使动；“封之以膏腴之地”状语后置，即“以膏腴之地封之”。","src":"触龙说赵太后"},{"q":"姜氏何厌之有？不如早为之所，无使滋蔓。","a":"姜氏有什么满足的？不如及早给他安排个地方，不要让他的势力滋长蔓延。","note":"“何厌之有”即“有何厌”，“之”为宾语前置标志；厌通餍。","src":"郑伯克段于鄢"},{"q":"且君尝为晋君赐矣，许君焦、瑕，朝济而夕设版焉。","a":"况且您曾对晋惠公施过恩惠，他答应给您焦、瑕两城，可早上渡河回国，晚上就筑城拒秦。","note":"揭晋忘恩无信。设版：筑城墙（防御）。","src":"烛之武退秦师"},{"q":"此其自多也，不似尔向之自多于水乎？","a":"他们这样自我夸耀，不就像你先前因河水上涨而自满一样吗？","note":"向：先前。收束本段，点戒矜夸自多之旨。","src":"秋水"}]},{"no":4,"date":"2026-11-01","date_end":"2026-11-02","pieces":["齐桓公伐楚","勾践灭吴","烛之武退秦师","谏逐客书","许行","触龙说赵太后"],"theme":"综合练习 4","p1":[{"q":"「王由是奇女。」出自（　）","opts":["《六国论》","《秋水》","《小翠》","《留侯论》"],"ans":"C","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：王太常从此认为小翠奇异。"},{"q":"「期年之后，虽欲言，无可进者。」出自（　）","opts":["《邹忌讽齐王纳谏》","《张中丞传后叙》","《齐桓晋文之事》","《巫山巫峡》"],"ans":"A","atext":"《邹忌讽齐王纳谏》","src":"句子→篇目","note":"出自《邹忌讽齐王纳谏》。参考译文：满一年以后，即使想进言，也没有什么可说的了。"},{"q":"「国不堪贰，君将若之何？」出自（　）","opts":["《郑伯克段于鄢》","《季氏将伐颛臾》","《齐桓公伐楚》","《论贵粟疏》"],"ans":"A","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：国家不能容忍两属的局面，您打算怎么办？"},{"q":"「父母之爱子，则为之计深远。」出自（　）","opts":["《郑伯克段于鄢》","《烛之武退秦师》","《触龙说赵太后》","《齐桓公伐楚》"],"ans":"C","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：父母爱子女，就要为他们考虑得长远些。"},{"q":"「古者富贵而名摩灭，不可胜记，唯倜傥非常之人称焉。」出自（　）","opts":["《报任安书》","《巫山巫峡》","《劝学》","《留侯论》"],"ans":"A","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：自古以来富贵而姓名埋没不传的人，多得数不清，只有卓越非凡的人才被后人称道。"},{"q":"「《诗》曰：“尸鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮！”故君子结于一也。」出自（　）","opts":["《逍遥游》","《劝学》","《鸿门宴》","《留侯论》"],"ans":"B","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：《诗经》说：“布谷鸟在桑树上，哺育它的七只小鸟。善良的君子，仪容始终专一。仪容始终专一，用心像绳结一样坚定！”所以君子的用心要坚凝专一。"},{"q":"「保民而王，莫之能御也。」出自（　）","opts":["《六国论》","《触龙说赵太后》","《巫山巫峡》","《齐桓晋文之事》"],"ans":"D","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：安抚百姓而称王天下，就没有谁能抵挡他。"},{"q":"「夫持法太急者，其锋不可犯，而其势未可乘。」出自（　）","opts":["《留侯论》","《谏逐客书》","《巫山巫峡》","《秋水》"],"ans":"A","atext":"《留侯论》","src":"句子→篇目","note":"出自《留侯论》。参考译文：施行严刑峻法太过急切的政权，它的锋芒不可触犯，它的形势也没有可乘之机。"},{"q":"「其嶔然相累而下者，若牛马之饮于溪；其冲然角列而上者，若熊罴之登于山。」出自（　）","opts":["《齐桓公伐楚》","《六国论》","《鸿门宴》","《钴鉧潭西小丘记》"],"ans":"D","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：那些高峻重叠倾斜而下的石头，好像牛马在溪边饮水；那些突起向上如兽角排列的石头，好像熊罴在攀登山峰。"},{"q":"「是故藏而勿守，犹勿藏也；守而弗读，犹勿守也。」出自（　）","opts":["《季氏将伐颛臾》","《劝学》","《传是楼记》","《烛之武退秦师》"],"ans":"C","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：所以藏书却不能守，等于没有藏；守书却不去读，等于没有守。"},{"q":"「苟得闻子大夫之言，何后之有？」出自（　）","opts":["《谏逐客书》","《留侯论》","《郑伯克段于鄢》","《勾践灭吴》"],"ans":"D","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：如果能听到大夫您的高论，又有什么晚呢？"},{"q":"「由此观之，王之蔽甚矣。」出自（　）","opts":["《子路曾皙冉有公西华侍坐》","《邹忌讽齐王纳谏》","《郑伯克段于鄢》","《季氏将伐颛臾》"],"ans":"B","atext":"《邹忌讽齐王纳谏》","src":"句子→篇目","note":"出自《邹忌讽齐王纳谏》。参考译文：由此看来，大王您受蒙蔽太厉害了。"},{"q":"普遍采用“赋”、“比”、“兴”的艺术手法；“诗经六义”：“风”、“雅”、“颂”“赋”、“比”、“兴”。（　）","opts":["写作手法","删诗","采诗","战争徭役诗"],"ans":"A","atext":"写作手法","src":"释义→词条","note":"写作手法：普遍采用“赋”、“比”、“兴”的艺术手法；“诗经六义”：“风”、“雅”、“颂”“赋”、“比”、“兴”。"},{"q":"十五国风即指十五个地区的地方土乐。：即音乐曲调（　）","opts":["战争徭役诗","写作手法","怨刺诗","风——160"],"ans":"D","atext":"风——160","src":"释义→词条","note":"风——160：十五国风即指十五个地区的地方土乐。：即音乐曲调"},{"q":"古地名中，山的南面、水的北岸为“阳”，山的北面、水的南岸为“阴”（如洛阳在洛水之北，江阴在长江之南）。（　）","opts":["古地名","江东（江表）","山高水北为阳","地理方位"],"ans":"C","atext":"山高水北为阳","src":"释义→词条","note":"山高水北为阳：古地名中，山的南面、水的北岸为“阳”，山的北面、水的南岸为“阴”（如洛阳在洛水之北，江阴在长江之南）。"},{"q":"古代中国的行政区划，后为中国的代称，一般指冀、兖、青、徐、扬、荆、豫、梁、雍九州。（　）","opts":["阴阳","古地名","关中","九州"],"ans":"D","atext":"九州","src":"释义→词条","note":"九州：古代中国的行政区划，后为中国的代称，一般指冀、兖、青、徐、扬、荆、豫、梁、雍九州。"},{"q":"山南水北为阳，山北水南为阴（如洛阳在洛水之北，江阴在长江之南，华阴在华山之北）。（　）","opts":["山高水北为阳","古代行政区划","阴阳","地理方位"],"ans":"D","atext":"地理方位","src":"释义→词条","note":"地理方位：山南水北为阳，山北水南为阴（如洛阳在洛水之北，江阴在长江之南，华阴在华山之北）。"},{"q":"古代哲学概念，指事物相互对立消长的两个方面；又地名中水北山南为阳，水南山北为阴，如“华阴”“衡阳”。（　）","opts":["古地名","五岳","九州","阴阳"],"ans":"D","atext":"阴阳","src":"释义→词条","note":"阴阳：古代哲学概念，指事物相互对立消长的两个方面；又地名中水北山南为阳，水南山北为阴，如“华阴”“衡阳”。"},{"q":"《钴鉧潭西小丘记》的作者是（　）","opts":["司马迁","苏轼","左丘明","柳宗元"],"ans":"D","atext":"柳宗元","src":"作品→作者","note":"《钴鉧潭西小丘记》— 柳宗元。原文标注：柳宗元"},{"q":"《六国论》的作者是（　）","opts":["蒲松龄","苏洵","左丘明","汪琬"],"ans":"B","atext":"苏洵","src":"作品→作者","note":"《六国论》— 苏洵。原文标注：苏洵"}],"p2":[{"q":"『何以致涕』中「何以」的意思是（　）","opts":["为什么","满一年","自己，自然","检查"],"ans":"A","atext":"为什么","word":"何以","type":"实词","note":"「何以」：为什么"},{"q":"『是以君子远庖厨也。』中「远」的意思是（　）","opts":["错误、过失","减少","远远地","远离。"],"ans":"D","atext":"远离。","word":"远","type":"实词","note":"远：形容词作动词，疏远、避开。"},{"q":"『然犹防川』中「川」的意思是（　）","opts":["河流","由于","使","背着"],"ans":"A","atext":"河流","word":"川","type":"实词","note":"「川」：河流"},{"q":"『贫民之赋可损』中「损」的意思是（　）","opts":["减少","有好处","欺骗","沿着"],"ans":"A","atext":"减少","word":"损","type":"实词","note":"与下文“损有余补不足”同。"},{"q":"『虎亦卒去』中「卒」的意思是（　）","opts":["名声","在家","姑且，暂且","最终；死"],"ans":"D","atext":"最终；死","word":"卒","type":"实词","note":"「卒」：最终；死"},{"q":"『子姑待之』中「姑」的意思是（　）","opts":["眼泪","痛恨、讨厌","姑且，暂且","沉重"],"ans":"C","atext":"姑且，暂且","word":"姑","type":"实词","note":"副词。"},{"q":"『情好绸缪』中「绸缪」的意思是（　）","opts":["跟从，跟随","隔了","通“佚”，散失","情意殷切"],"ans":"D","atext":"情意殷切","word":"绸缪","type":"实词","note":"「绸缪」：情意殷切"},{"q":"『《齐谐》者，志怪者也。』中「志」的意思是（　）","opts":["追究，审问；推崇","记载，记录。","使……亏损，损害","反复无常，不专一"],"ans":"B","atext":"记载，记录。","word":"志","type":"实词","note":"志怪：记载怪异的事物。"},{"q":"『寔徐譬之曰』中「徐」的意思是（　）","opts":["善，体恤","空闲。","趁机","慢慢地"],"ans":"D","atext":"慢慢地","word":"徐","type":"实词","note":"「徐」：慢慢地"},{"q":"『吾则改之』中「改」的意思是（　）","opts":["方法","道歉、谢罪","竭力、极力","修改，改正"],"ans":"D","atext":"修改，改正","word":"改","type":"实词","note":"「改」：修改，改正"}],"p3":[{"q":"贡之不入，寡君之罪也，敢不共给？","a":"贡品不交纳，是我们国君的罪过，怎敢不供给？","note":"判断句“……也”；共通供。楚使只认包茅之罪。","src":"齐桓公伐楚"},{"q":"越人饰美女八人，纳之太宰嚭，曰：“子苟赦越国之罪，又有美于此者将进之。”太宰嚭谏曰：“嚭闻古之伐国者，服之而已；今已服矣，又何求焉？”夫差与之成而去之。","a":"越国人打扮了八个美女，送给太宰伯嚭，说：\"您如果赦免越国的罪过，还有比这些更美的将进献给您。\"太宰伯嚭劝谏说：\"我听说古代讨伐别国的，使它降服就罢了；如今越国已经降服了，还要求什么呢？\"夫差就和越国讲和，撤兵离开了。","note":"","src":"勾践灭吴"},{"q":"若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。","a":"如果放过郑国让它做东方道路上的主人，秦国使者往来，郑国可供应他们缺的资粮，对您也无害。","note":"东道主：东方道上的主人；行李：使者；共通供。","src":"烛之武退秦师"},{"q":"臣闻吏议逐客，窃以为过矣。","a":"我听说官吏们商议驱逐客卿，私下认为这是错误的。","note":"开篇单刀直入提出中心论点；“窃”表自谦。全文以此断语统领。","src":"谏逐客书"},{"q":"远方之人闻君行仁政，愿受一廛而为氓。","a":"我这远方之人听说您施行仁政，希望得到一处住所做您的百姓。","note":"廛：一夫之居；氓：外来之民。","src":"许行"},{"q":"老臣以媪为长安君计短也，故以为其爱不若燕后。","a":"我认为您为长安君打算得太短浅了，所以觉得您爱他不如爱燕后。","note":"以……为：认为……；“不若”：不如、比不上。","src":"触龙说赵太后"},{"q":"然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。","a":"那么小国本来不可与大国为敌，人少之国本来不可与人多之国为敌，弱国本来不可与强国为敌。","note":"小、大、寡、众、弱、强均形容词作名词。三组排比。","src":"齐桓晋文之事"},{"q":"是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。","a":"所以没有精诚专一意志的人，就不会有明察的智慧；没有埋头苦干实事的人，就不会有显赫的功业。","note":"“冥冥”“惛惛”专心一意；“昭昭”“赫赫”显明显赫。对偶句强调专一笃实。","src":"劝学"},{"q":"观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。","a":"考察汉高祖之所以胜利、项羽之所以失败的原因，就在于能忍与不能忍之间罢了。","note":"项籍：项羽。以刘项成败立论，归结到“忍”字。","src":"留侯论"},{"q":"古人云：“以地事秦，犹抱薪救火，薪不尽，火不灭。”","a":"古人说：“用土地侍奉秦国，就好像抱着柴草去救火，柴草不烧完，火就不会灭。”","note":"事：侍奉。引古人作喻，形象说明赂秦之非。","src":"六国论"},{"q":"此数宝者，秦不生一焉，而陛下说之，何也？","a":"这几样宝物，秦国一样都不出产，可是陛下却喜爱它们，为什么呢？","note":"“说”通“悦”。以物设喻，转入今陛下重物轻人之论。","src":"谏逐客书"},{"q":"多行不义必自毙，子姑待之。","a":"多做不义的事，一定会自取灭亡，您姑且等着吧。","note":"毙：仆倒、灭亡。庄公知段必叛而故意纵容。","src":"郑伯克段于鄢"},{"q":"吾入关，秋毫不敢有所近，籍吏民，封府库，而待将军。","a":"我入关后，一点东西都不敢沾边，登记官吏百姓，封闭府库，等待将军到来。","note":"“秋毫”比喻极细小之物；“籍”名词作动词，登记。向项伯表忠心。","src":"鸿门宴"},{"q":"夫人情莫不贪生恶死，念父母，顾妻子。至激于义理者不然，乃有所不得已也。今仆不幸，早失父母，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？且勇者不必死节，怯夫慕义，何处不勉焉？仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后世也。","a":"人之常情没有不贪生怕死、思念父母、顾念妻子儿女的。至于被义理激奋的人却不是这样，是有不得已的地方。如今我不幸，早年失去父母，没有兄弟的亲近，孤身一人，少卿您看我对于妻子儿女怎么样呢？况且勇敢的人不一定为节义而死，怯懦的人仰慕道义，哪里不能勉励自己呢？我虽然怯懦，想苟且活命，也很懂得去就的分寸，怎么会至于自己沉溺于牢狱的耻辱呢！之所以隐忍苟活，幽居于污秽之中而不推辞，是遗憾内心有未了的心愿，平庸地死去，而文采不能显扬于后世。","note":"","src":"报任安书"},{"q":"敢尽布之执事，俾执事实图利之！","a":"冒昧地把这些全部陈述给您，请您认真考虑对秦有利的做法！","note":"敢：谦辞冒昧；布：陈述；图：考虑。绝交书的结束语。","src":"吕相绝秦"},{"q":"当淮阴破齐而欲自王，高祖发怒，见于词色。由此观之，犹有刚强不忍之气，非子房其谁全之？","a":"当韩信攻破齐国想自立为王时，高祖发怒，怒气显露在言辞脸色上。由此看来，高祖还有刚强不能忍耐的脾气，不是张良谁能成全他呢？","note":"王（wàng）：称王；见（xiàn）：流露。举例说明张良教高祖以忍。","src":"留侯论"},{"q":"夏，楚子使屈完如师。师退，次于召陵。齐侯陈诸侯之师，与屈完乘而观之。齐侯曰：“岂不穀是为？先君之好是继，与不穀同好，如何？”对曰：“君惠徼福于敝邑之社稷，辱收寡君，寡君之愿也。”齐侯曰：“以此众战，谁能御之！以此攻城，何城不克！”对曰：“君若以德绥诸侯，谁敢不服？君若以力，楚国方城以为城，汉水以为池，虽众，无所用之！”","a":"夏天，楚成王派屈完到诸侯军中。诸侯军队后撤，驻扎在召陵。齐桓公把诸侯的军队列成阵势，和屈完同乘一辆车观看。桓公说：\"难道是为了我吗？不过是为了继续先君的友好关系，和我共同友好，怎么样？\"屈完回答说：\"承蒙您为敝国社稷求福，屈尊接纳我们国君，这是我们国君的愿望。\"桓公说：\"用这样的军队作战，谁能抵挡？用这样的军队攻城，哪座城攻不下？\"屈完回答说：\"您如果用德行安抚诸侯，谁敢不服？您如果凭借武力，楚国以方城山为城墙，以汉水为护城河，您军队虽多，也没有用处！\"","note":"","src":"齐桓公伐楚"},{"q":"盖文王拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》。","a":"周文王被拘禁而推演《周易》；孔子受困厄而写作《春秋》；屈原被放逐，才创作出《离骚》。","note":"排比句；“拘”“厄”“放逐”皆被动意味。连串史例论证发愤著书。","src":"报任安书"},{"q":"人方蹈我之瑕，反以闺阁之丑登门而告之，余祸不远矣！","a":"人家正要抓我的把柄，我倒把闺房中的丑事上门去告诉他，我的祸事不远了！","note":"蹈瑕：利用过失。写王公的忧虑。","src":"小翠"},{"q":"燕、赵之君，始有远略，能守其土，义不赂秦。","a":"燕国和赵国的君主，起初有长远的谋略，能够守住他们的国土，坚持正义，不贿赂秦国。","note":"义：名词作状语，坚持正义。肯定燕赵守土抗秦。","src":"六国论"}]},{"no":5,"date":"2026-11-02","date_end":"2026-11-03","pieces":["六国论","吕相绝秦","小翠","逍遥游","劝学","邹忌讽齐王纳谏"],"theme":"综合练习 5","p1":[{"q":"「诸侯备闻此言，斯是用痛心疾首，暱就寡人。」出自（　）","opts":["《巫山巫峡》","《小翠》","《六国论》","《吕相绝秦》"],"ans":"D","atext":"《吕相绝秦》","src":"句子→篇目","note":"出自《吕相绝秦》。参考译文：诸侯都听到了这些话，因此对秦痛心疾首，而来亲近我们。"},{"q":"「其颓岩所余，比之诸岭，尚为竦桀。」出自（　）","opts":["《许行》","《鸿门宴》","《巫山巫峡》","《留侯论》"],"ans":"C","atext":"《巫山巫峡》","src":"句子→篇目","note":"出自《巫山巫峡》。参考译文：那些崩塌后残存的岩石，与其他山岭相比，仍然显得高耸突出。"},{"q":"「白狄及君同州，君之仇雠，而我之昏姻也。」出自（　）","opts":["《吕相绝秦》","《张中丞传后叙》","《烛之武退秦师》","《触龙说赵太后》"],"ans":"A","atext":"《吕相绝秦》","src":"句子→篇目","note":"出自《吕相绝秦》。参考译文：白狄和您同处雍州，是您的仇敌，却是我们的姻亲。"},{"q":"「沛公至军，立诛杀曹无伤。」出自（　）","opts":["《鸿门宴》","《齐桓公伐楚》","《报任安书》","《六国论》"],"ans":"A","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：沛公回到军中，立刻杀掉了曹无伤。"},{"q":"「其石之突怒偃蹇，负土而出，争为奇状者，殆不可数」出自（　）","opts":["《齐桓公伐楚》","《吕相绝秦》","《钴鉧潭西小丘记》","《留侯论》"],"ans":"C","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：小丘上的石头拔地而起、高耸傲然，顶着泥土钻出来，争着呈现奇形怪状的，几乎数也数不清。"},{"q":"「蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。」出自（　）","opts":["《许行》","《留侯论》","《六国论》","《劝学》"],"ans":"D","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：蚯蚓没有锋利的爪牙、强健的筋骨，却上能吃泥土，下能饮地下泉水，是因为用心专一啊。"},{"q":"「《诗》三百篇，大底圣贤发愤之所为作也。」出自（　）","opts":["《触龙说赵太后》","《张中丞传后叙》","《论贵粟疏》","《报任安书》"],"ans":"D","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：《诗经》三百篇，大都是圣贤们抒发愤懑而写作的。"},{"q":"「仆闻之：修身者，智之符也；爱施者，仁之端也；取予者，义之表也；耻辱者，勇之决也；立名者，行之极也。士有此五者，然后可以托于世，而列于君子之林矣。故祸莫憯于欲利，悲莫痛于伤心，行莫丑于辱先，诟莫大于宫刑。刑余之人，无所比数，非一世也，所从来远矣。」出自（　）","opts":["《报任安书》","《巫山巫峡》","《许行》","《小翠》"],"ans":"A","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：我听说：修养自身，是智慧的凭证；乐善好施，是仁的开端；取舍有度，是义的体现；懂得耻辱，是勇的决断；树立名声，是行的极致。士人具备这五点，然后才可以托身于世，排列在君子的行列中。所以"},{"q":"「由其中以望，则山之高，云之浮，溪之流，鸟兽之遨游，举熙熙然回巧献技，以效兹丘之下。」出自（　）","opts":["《逍遥游》","《季氏将伐颛臾》","《吕相绝秦》","《钴鉧潭西小丘记》"],"ans":"D","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：站在小丘中央四望，那高峻的山、飘浮的云、流淌的溪、遨游的鸟兽，全都和悦地呈献巧态、施展技艺，在这小丘之下效力。"},{"q":"「犹不能恃无功之尊、无劳之奉，而守金玉之重也，而况人臣乎。」出自（　）","opts":["《传是楼记》","《烛之武退秦师》","《触龙说赵太后》","《季氏将伐颛臾》"],"ans":"C","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：尚且不能凭仗没有功勋的尊位、没有劳绩的俸禄来守住珍宝，何况是人臣呢。"},{"q":"「左师触龙言愿见太后。太后盛气而揖之。入而徐趋，至而自谢，曰：“老臣病足，曾不能疾走，不得见久矣。窃自恕，而恐太后玉体之有所郄也，故愿望见太后。”太后曰：“老妇恃辇而行。”曰：“日食饮得无衰乎？”曰：“恃粥耳。”曰：“老臣今者殊不欲食，乃自强步，日三四里，少益耆食，和于身。”太后曰：“老妇不能。”太后之色少解。」出自（　）","opts":["《触龙说赵太后》","《齐桓晋文之事》","《季氏将伐颛臾》","《巫山巫峡》"],"ans":"A","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：左师触龙说希望拜见太后。太后怒气冲冲地等着他。触龙进门后慢慢地小步快走，到了太后面前自己谢罪说：\"老臣脚有毛病，竟不能快走，很久没能来拜见您了。我私下原谅自己，又恐怕太后的身体有什"},{"q":"「邦分崩离析而不能守也，而谋动干戈于邦内。」出自（　）","opts":["《谏逐客书》","《季氏将伐颛臾》","《吕相绝秦》","《传是楼记》"],"ans":"B","atext":"《季氏将伐颛臾》","src":"句子→篇目","note":"出自《季氏将伐颛臾》。参考译文：国家分崩离析却不能保全，反而想在国境之内大动干戈。"},{"q":"秦行郡县制，汉为州郡县，唐为道州县，宋为路州县，元为行省，明清为省府县。（　）","opts":["江东（江表）","古地名","古代行政区划","山高水北为阳"],"ans":"C","atext":"古代行政区划","src":"释义→词条","note":"古代行政区划：秦行郡县制，汉为州郡县，唐为道州县，宋为路州县，元为行省，明清为省府县。"},{"q":"古地区名，指长江下游以南的江南地区，又称江左。（　）","opts":["地理方位","山高水北为阳","古代行政区划","江东（江表）"],"ans":"D","atext":"江东（江表）","src":"释义→词条","note":"江东（江表）：古地区名，指长江下游以南的江南地区，又称江左。"},{"q":"江左（江东，长江下游以南）、江表（长江以南）、关中（函谷关以西）、山东（崤山以东）、江南、中原、塞北、西域。（　）","opts":["地理方位","阴阳","关中","古地名"],"ans":"D","atext":"古地名","src":"释义→词条","note":"古地名：江左（江东，长江下游以南）、江表（长江以南）、关中（函谷关以西）、山东（崤山以东）、江南、中原、塞北、西域。"},{"q":"古地区名，指函谷关（一说潼关）以西的今陕西渭河流域一带。（　）","opts":["古地名","九州","关中","阴阳"],"ans":"C","atext":"关中","src":"释义→词条","note":"关中：古地区名，指函谷关（一说潼关）以西的今陕西渭河流域一带。"},{"q":"五大名山的总称——东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。（　）","opts":["九州","古地名","关中","五岳"],"ans":"D","atext":"五岳","src":"释义→词条","note":"五岳：五大名山的总称——东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。"},{"q":"普鲁斯特《追忆似水年华》（法）、乔伊斯《尤利西斯》（爱尔兰）、伍尔夫《达洛维夫人》（英）、福克纳《喧哗与骚动》（美）。（　）","opts":["外国文学三大短篇小说巨匠","文艺复兴","意识流小说代表","司汤达"],"ans":"C","atext":"意识流小说代表","src":"释义→词条","note":"意识流小说代表：普鲁斯特《追忆似水年华》（法）、乔伊斯《尤利西斯》（爱尔兰）、伍尔夫《达洛维夫人》（英）、福克纳《喧哗与骚动》（美）。"},{"q":"《吕相绝秦》的作者是（　）","opts":["司马迁","左丘明","柳宗元","荀子"],"ans":"B","atext":"左丘明","src":"作品→作者","note":"《吕相绝秦》— 左丘明。原文标注：左丘明（相传）"},{"q":"《传是楼记》的作者是（　）","opts":["柳宗元","郦道元","刘向","汪琬"],"ans":"D","atext":"汪琬","src":"作品→作者","note":"《传是楼记》— 汪琬。原文标注：汪琬"}],"p2":[{"q":"『而陛下说之』中「说」的意思是（　）","opts":["通“仇”，仇敌","通\"凭\"，凭借、乘。","仰视的样子。","通“悦”，喜悦、喜爱"],"ans":"D","atext":"通“悦”，喜悦、喜爱","word":"说","type":"实词","note":"“说”读yuè，通“悦”。"},{"q":"『卒然临之而不惊』中「卒」的意思是（　）","opts":["突然、仓猝","担任；写","前往拜访","仅仅，只"],"ans":"A","atext":"突然、仓猝","word":"卒","type":"实词","note":"卒（cù）通“猝”。"},{"q":"『冠者五六人』中「冠者」的意思是（　）","opts":["民，外来的移民。","伸长脖子，形容盼望殷切","劝说、游说（音shuì）","成年人（古男子二十岁行冠礼）"],"ans":"D","atext":"成年人（古男子二十岁行冠礼）","word":"冠者","type":"实词","note":"冠（guàn）：行冠礼；冠者即成年人。"},{"q":"『将免者以告』中「免」的意思是（　）","opts":["近年间","使动，使……成就功业","通“娩”，分娩","通\"辨\"，分辨，辨别。"],"ans":"C","atext":"通“娩”，分娩","word":"免","type":"实词","note":"免通娩。"},{"q":"『即千万言谀之』中「言」的意思是（　）","opts":["从前","言语；字","临时驻扎","砍削"],"ans":"B","atext":"言语；字","word":"言","type":"实词","note":"「言」：言语；字"},{"q":"『顷岁，孙莘老识欧阳文忠公』中「顷岁」的意思是（　）","opts":["展开、散开","近年间","遇合、际遇","担任；写"],"ans":"B","atext":"近年间","word":"顷岁","type":"实词","note":"「顷岁」：近年间"},{"q":"『有妇人昼日置二小儿沙上而浣衣于水者』中「浣」的意思是（　）","opts":["趁机","跑","仔细","洗"],"ans":"D","atext":"洗","word":"浣","type":"实词","note":"「浣」：洗"},{"q":"『而特出于荆轲、聂政之计』中「特」的意思是（　）","opts":["只、仅仅","全、都","护城河","抬眼"],"ans":"A","atext":"只、仅仅","word":"特","type":"实词","note":"特：只不过。"},{"q":"『故务民于农桑』中「务」的意思是（　）","opts":["致力、从事、使……致力","怀抱（指抱负）","舍，进驻，安居","几乎、几乎多得"],"ans":"A","atext":"致力、从事、使……致力","word":"务","type":"实词","note":"务民：使百姓致力于。"},{"q":"『潸然流涕』中「涕」的意思是（　）","opts":["猪","穿。","眼泪","·交给"],"ans":"C","atext":"眼泪","word":"涕","type":"实词","note":"「涕」：眼泪"}],"p3":[{"q":"有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。","a":"有这样有利的形势，却被秦国积久的威势所挟制，一天天地削减、一月月地割让，而走向灭亡。","note":"为……所：被动句式；日、月：名词作状语。沉痛总结历史教训。","src":"六国论"},{"q":"而欲徼福于先君献、穆。","a":"您施恩求福于我们先君献公、穆公。","note":"徼（yāo）：求。秦侯后悔战祸蔓延，想求福于晋先君献、穆，重结旧好。","src":"吕相绝秦"},{"q":"生一子名元丰，绝痴，十六岁不能知牝牡，因而乡党无与为婚。","a":"生了一个儿子名叫元丰，痴呆到极点，十六岁还不懂男女之事，因此乡里没有人肯同他家结亲。","note":"牝牡：雌雄，指男女。交代小翠嫁痴儿的缘由。","src":"小翠"},{"q":"夫列子御风而行，泠然善也，旬有五日而后反。彼于致福者，未数数然也。此虽免乎行，犹有所待者也。","a":"列子驾着风飞行，轻飘飘地十分轻妙，过了十五天才返回。他对于求福的事，并不急切追求。这样虽然免于步行，但还是有所凭借的。","note":"","src":"逍遥游"},{"q":"吾尝终日而思矣，不如须臾之所学也。","a":"我曾经整天地思索，却比不上片刻学习的收获大。","note":"“而”连词表修饰；“须臾”片刻。对比“思”与“学”，强调学重于思。","src":"劝学"},{"q":"王曰：“善。”乃下令：“群臣吏民能面刺寡人之过者，受上赏；上书谏寡人者，受中赏；能谤讥于市朝，闻寡人之耳者，受下赏。”令初下，群臣进谏，门庭若市；数月之后，时时而间进；期年之后，虽欲言，无可进者。燕、赵、韩、魏闻之，皆朝于齐。此所谓战胜于朝廷。","a":"齐威王说：\"好。\"于是下令：\"群臣、官吏、百姓能够当面指责我的过错的，受上等奖赏；上书劝谏我的，受中等奖赏；能够在公共场所批评议论我的过失、传到我耳朵里的，受下等奖赏。\"命令刚下达时，群臣都来进谏，宫门庭院像集市一样热闹；几个月以后，还时时有人偶尔进谏；满一年以后，即使想进谏，也没有什么可说的了。燕国、赵国、韩国、魏国听说了这件事，都到齐国来朝见。这就是人们所说的在朝廷上战胜别国。","note":"","src":"邹忌讽齐王纳谏"},{"q":"此所谓战胜于朝廷。","a":"这就是所说的在朝廷上战胜敌国。","note":"判断句（“此所谓……”）；“战胜于朝廷”状语后置，即“于朝廷战胜”，指内政修明不必用兵即可使敌国畏服。","src":"邹忌讽齐王纳谏"},{"q":"君若以力，楚国方城以为城，汉水以为池，虽众，无所用之！","a":"您如果动用武力，楚国有方城山作城墙，汉水作护城河，您的军队虽多，也用不上！","note":"“方城以为城，汉水以为池”宾语前置（以方城为城）。刚柔并济，不卑不亢。","src":"齐桓公伐楚"},{"q":"嘉木立，美竹露，奇石显。","a":"美好的树木挺立起来，秀美的竹子显露出来，奇峭的石头显现出来。","note":"立、露、显三个动词写整治后的变化，一字一顿。","src":"钴鉧潭西小丘记"},{"q":"故推恩足以保四海，不推恩无以保妻子。","a":"所以推广恩德足以安定天下，不推广恩德连妻子儿女都保全不了。","note":"妻子：古今异义，妻子和儿女。对比说推恩之效。","src":"齐桓晋文之事"},{"q":"勤苦如此，尚复被水旱之灾，急政暴赋，赋敛不时，朝令而暮当具。","a":"勤劳辛苦到这种地步，还要遭受水旱灾害，赋税又急迫暴虐，征收不按时节，早晨下命令晚上就要备齐。","note":"“被”遭受；“不时”不按时节；“朝令暮当具”极言赋税之急。","src":"论贵粟疏"},{"q":"大隧之中，其乐也融融！","a":"走进大隧之中，那快乐啊和暖融洽！","note":"融融：和乐貌。郑庄公入隧赋诗。","src":"郑伯克段于鄢"},{"q":"曲士不可以语于道者，束于教也。","a":"见识浅陋的人不能和他谈大道，是因为他被所受教养束缚。","note":"判断句；曲士：乡曲之士。三者由空间、时间、教养三层写局限。","src":"秋水"},{"q":"一旦山陵崩，长安君何以自托于赵？","a":"一旦您去世，长安君凭什么在赵国立足呢？","note":"山陵崩：讳称太后死；“何以”宾语前置，即“以何”。","src":"触龙说赵太后"},{"q":"肉腐出虫，鱼枯生蠹。怠慢忘身，祸灾乃作。","a":"肉腐烂就生蛆，鱼干枯就长虫。懈怠疏忽忘乎自身，灾祸就会发生。","note":"“蠹”蛀虫；“作”兴起。比喻荣辱祸福皆由自身招致。","src":"劝学"},{"q":"文公躬擐甲胄，跋履山川，逾越险阻。","a":"文公亲自披甲戴盔，跋涉山川，越过艰难险阻。","note":"躬：亲自；擐（huàn）：穿。四字句排比，气势充沛。","src":"吕相绝秦"},{"q":"其间首尾百六十里，谓之巫峡，盖因山为名也。","a":"这之间首尾长一百六十里，叫做巫峡，大概是因为巫山而得名的。","note":"盖：句首语气词，表推测；因：介词，凭借。判断兼解释得名由来。","src":"巫山巫峡"},{"q":"吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。","a":"我妻子认为我美，是偏爱我；妾认为我美，是害怕我；客人认为我美，是有求于我。","note":"三个判断句排比，“……者，……也”表判断；“美”为意动用法，“私”为偏爱。","src":"邹忌讽齐王纳谏"},{"q":"以若所为，求若所欲，犹缘木而求鱼也。","a":"凭这样的做法，去追求这样的欲望，就像爬到树上去找鱼。","note":"缘：攀援。成语\"缘木求鱼\"所本，喻方向方法错，必无所获。","src":"齐桓晋文之事"},{"q":"夫寒之于衣，不待轻暖；饥之于食，不待甘旨；饥寒至身，不顾廉耻。人情，一日不再食则饥，终岁不制衣则寒。夫腹饥不得食，肤寒不得衣，虽慈母不能保其子，君安能以有其民哉！明主知其然也，故务民于农桑，薄赋敛，广畜积，以实仓廪，备水旱，故民可得而有也。","a":"人在寒冷时对衣服的要求，不会等到轻暖的才穿；饥饿时对食物的要求，不会等到甘美的才吃；饥寒临身，就不顾廉耻了。人之常情是：一天不吃两顿饭就饿，整年不添置衣服就冷。腹中饥饿得不到食物，身上寒冷得不到衣服，即使是慈母也不能保住她的孩子，君主又怎么能保有他的百姓呢！英明的君主知道这个道理，所以使百姓致力于农桑，减轻赋税，广泛积蓄，来充实粮仓，防备水旱灾害，因此百姓才能得到并保有。","note":"","src":"论贵粟疏"}]},{"no":6,"date":"2026-11-03","date_end":"2026-11-04","pieces":["子路曾皙冉有公西华侍坐","小翠","传是楼记","报任安书","许行","郑伯克段于鄢"],"theme":"综合练习 6","p1":[{"q":"「抟扶摇羊角而上者九万里，绝云气，负青天。」出自（　）","opts":["《鸿门宴》","《许行》","《逍遥游》","《留侯论》"],"ans":"C","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：乘着旋风像羊角般盘旋而上九万里，穿越云气，背负青天。"},{"q":"「曰：\"是心足以王矣。百姓皆以王为爱也，臣固知王之不忍也。\"」出自（　）","opts":["《齐桓晋文之事》","《季氏将伐颛臾》","《吕相绝秦》","《鸿门宴》"],"ans":"A","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：孟子说：\"有这样的心就足以称王天下了。百姓都以为大王是吝惜，我本来就知道大王是不忍心。\""},{"q":"「呜呼！以赂秦之地封天下之谋臣，以事秦之心礼天下之奇才，并力西向，则吾恐秦人食之不得下咽也。悲夫！有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。为国者无使为积威之所劫哉！」出自（　）","opts":["《劝学》","《谏逐客书》","《六国论》","《吕相绝秦》"],"ans":"C","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：唉！如果拿贿赂秦国的土地封赏天下的谋臣，拿侍奉秦国的心意礼遇天下的奇才，合力向西，那么我恐怕秦国人连吃饭都咽不下去了。可悲啊！有这样的形势，却被秦国积久的威势所胁迫，天天削弱、月月"},{"q":"「邻之厚，君之薄也。」出自（　）","opts":["《鸿门宴》","《郑伯克段于鄢》","《烛之武退秦师》","《吕相绝秦》"],"ans":"C","atext":"《烛之武退秦师》","src":"句子→篇目","note":"出自《烛之武退秦师》。参考译文：邻邦（晋）力量雄厚了，就是您（秦）力量削弱了。"},{"q":"「若琬则无以与于此矣。居平质驽才下，患于有书而不能读。延及暮年，则又跧伏穷山僻壤之中，耳目固陋，旧学消亡，盖本不足以记斯楼。不得已勉承先生之命，姑为一言复之，先生亦恕其老誖否耶？」出自（　）","opts":["《触龙说赵太后》","《传是楼记》","《巫山巫峡》","《小翠》"],"ans":"B","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：像我汪琬就无法参与到这里面了。平素资质愚钝、才能低下，苦于有书而不能读。到了晚年，又蜷伏在穷山僻壤之中，耳目闭塞，旧学荒废，本来不足以记述这座楼。不得已勉强接受先生的命令，姑且写几"},{"q":"「西方有木焉，名曰射干，茎长四寸，生于高山之上，而临百仞之渊，木茎非能长也，所立者然也。」出自（　）","opts":["《小翠》","《劝学》","《六国论》","《许行》"],"ans":"B","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：西方有一种草，名叫射干，茎长四寸，生长在高山上，下临百仞深谷，并不是茎能长高，是它生长的地方使它这样的。"},{"q":"「天下有大勇者，卒然临之而不惊，无故加之而不怒。」出自（　）","opts":["《报任安书》","《谏逐客书》","《留侯论》","《传是楼记》"],"ans":"C","atext":"《留侯论》","src":"句子→篇目","note":"出自《留侯论》。参考译文：天下有一种真正勇敢的人，突发情况压到他身上他不惊慌，无故受到侮辱他不愤怒。"},{"q":"「孰是君也，而可无死乎？」出自（　）","opts":["《勾践灭吴》","《许行》","《劝学》","《齐桓公伐楚》"],"ans":"A","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：哪有这样好的国君，怎么能不为他效死呢？"},{"q":"「\"今恩足以及禽兽，而功不至于百姓者，独何与？然则一羽之不举，为不用力焉；舆薪之不见，为不用明焉；百姓之不见保，为不用恩焉。故王之不王，不为也，非不能也。\"」出自（　）","opts":["《齐桓晋文之事》","《邹忌讽齐王纳谏》","《吕相绝秦》","《烛之武退秦师》"],"ans":"A","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：孟子说：\"如今您的恩惠足以施及禽兽，而功业却达不到百姓身上，偏偏为什么呢？这样看来，一根羽毛举不起，是因为不用力气；一车柴草看不见，是因为不用眼力；百姓得不到安抚，是因为不用恩惠。"},{"q":"「君何患焉？若阙地及泉，隧而相见，其谁曰不然？」出自（　）","opts":["《郑伯克段于鄢》","《钴鉧潭西小丘记》","《留侯论》","《论贵粟疏》"],"ans":"A","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：您忧虑什么呢？如果掘地见到泉水，挖隧道相见，谁能说不对？"},{"q":"「蟹六跪而二螯，非蛇鳝之穴无可寄托者，用心躁也。」出自（　）","opts":["《逍遥游》","《留侯论》","《劝学》","《六国论》"],"ans":"C","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：螃蟹有六条腿两只蟹钳，可是没有蛇鳝的洞穴就无处藏身，是因为用心浮躁啊。"},{"q":"「若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉！故曰：至人无己，神人无功，圣人无名。」出自（　）","opts":["《勾践灭吴》","《报任安书》","《逍遥游》","《鸿门宴》"],"ans":"C","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：至于顺应天地的本性，驾驭六气的变化，来遨游于无穷无尽的境界的人，他还凭借什么呢！所以说：至人没有自我，神人没有功业，圣人没有名声。"},{"q":"主人公:冉·阿让（化名马德兰）、妓女芳汀、私生女珂赛特、共和派青年马利尤斯（　）","opts":["《悲惨世界》(长篇小说)","文艺复兴『三杰』","玛格丽特·米切尔（美国）","福楼拜（法国）批判现实"],"ans":"A","atext":"《悲惨世界》(长篇小说)","src":"释义→词条","note":"《悲惨世界》(长篇小说)：主人公:冉·阿让（化名马德兰）、妓女芳汀、私生女珂赛特、共和派青年马利尤斯"},{"q":"《日瓦戈医生》——诺贝尔文学奖；十月革命胜利前后日瓦尔一生的生活变动及人生宿命（　）","opts":["洛贝·德·维伽","诺贝尔文学奖","帕斯捷尔纳克（苏联）","欧里庇得斯"],"ans":"C","atext":"帕斯捷尔纳克（苏联）","src":"释义→词条","note":"帕斯捷尔纳克（苏联）：《日瓦戈医生》——诺贝尔文学奖；十月革命胜利前后日瓦尔一生的生活变动及人生宿命"},{"q":"莎士比亚悲剧代表作，主人公丹麦王子哈姆雷特是人文主义者的典型，著名独白『生存还是毁灭，这是一个值得考虑的问题』。（　）","opts":["诺贝尔文学奖","《哈姆雷特》","意识流小说代表","亚里士多德"],"ans":"B","atext":"《哈姆雷特》","src":"释义→词条","note":"《哈姆雷特》：莎士比亚悲剧代表作，主人公丹麦王子哈姆雷特是人文主义者的典型，著名独白『生存还是毁灭，这是一个值得考虑的问题』。"},{"q":"《金驴记》又称《变形记》是欧洲最早的长篇小说。（　）","opts":["阿普列尤斯——公认的“小说之父”","新喜剧（前323-前263）","肖洛霍夫（苏联）","《巴黎圣母院》(长篇小说)"],"ans":"A","atext":"阿普列尤斯——公认的“小说之父”","src":"释义→词条","note":"阿普列尤斯——公认的“小说之父”：《金驴记》又称《变形记》是欧洲最早的长篇小说。"},{"q":"古希腊三大悲剧作家之一，代表作《俄狄浦斯王》，被亚里士多德誉为最完美的悲剧。（　）","opts":["索福克勒斯","贺拉斯","存在主义文学","『小人物』主题"],"ans":"A","atext":"索福克勒斯","src":"释义→词条","note":"索福克勒斯：古希腊三大悲剧作家之一，代表作《俄狄浦斯王》，被亚里士多德誉为最完美的悲剧。"},{"q":"《包法利夫人》；受过贵族化教育的农家女爱玛，乡镇医生的丈夫包法利，梦想传奇式爱情，却因偷情失败而成为高利贷者盘剥的对象，最后服毒自尽。（　）","opts":["『多余人』形象","意识流小说代表","福楼拜（法国）批判现实","洛贝·德·维伽"],"ans":"C","atext":"福楼拜（法国）批判现实","src":"释义→词条","note":"福楼拜（法国）批判现实：《包法利夫人》；受过贵族化教育的农家女爱玛，乡镇医生的丈夫包法利，梦想传奇式爱情，却因偷情失败而成为高利贷者盘剥的对象，最后服毒自尽。"},{"q":"《小翠》的作者是（　）","opts":["庄周","蒲松龄","苏洵","汪琬"],"ans":"B","atext":"蒲松龄","src":"作品→作者","note":"《小翠》— 蒲松龄。原文标注：蒲松龄"},{"q":"《烛之武退秦师》的作者是（　）","opts":["柳宗元","左丘明","苏洵","韩愈"],"ans":"B","atext":"左丘明","src":"作品→作者","note":"《烛之武退秦师》— 左丘明。原文标注：左丘明（相传）"}],"p2":[{"q":"『国不堪贰』中「贰」的意思是（　）","opts":["请别人代自己做事","通“磨”，磨灭","两属，怀有二心","灾患、损耗"],"ans":"C","atext":"两属，怀有二心","word":"贰","type":"实词","note":"数词用作动词。"},{"q":"『视君状貌』中「视」的意思是（　）","opts":["迎接","满足","佩服","看"],"ans":"D","atext":"看","word":"视","type":"实词","note":"「视」：看"},{"q":"『二人并告归乡里』中「并」的意思是（　）","opts":["肃清","甚、很","一起","释放"],"ans":"C","atext":"一起","word":"并","type":"实词","note":"「并」：一起"},{"q":"『故尤有味』中「尤」的意思是（　）","opts":["结束，完毕","更加，尤其","于是，就；终于","两属，怀有二心"],"ans":"B","atext":"更加，尤其","word":"尤","type":"实词","note":"「尤」：更加，尤其"},{"q":"『不可胜数』中「胜」的意思是（　）","opts":["很","原本","尽","通晓"],"ans":"C","atext":"尽","word":"胜","type":"实词","note":"胜：尽。"},{"q":"『妻善织缟』中「缟」的意思是（　）","opts":["招致","崇尚","增加","白绢"],"ans":"D","atext":"白绢","word":"缟","type":"实词","note":"「缟」：白绢"},{"q":"『而欲徙于越』中「徙」的意思是（　）","opts":["背着","迁移","再，又","用杖打"],"ans":"B","atext":"迁移","word":"徙","type":"实词","note":"「徙」：迁移"},{"q":"『吾妻之美我者，私我也』中「私」的意思是（　）","opts":["猪","偏爱","远离。","晚上"],"ans":"B","atext":"偏爱","word":"私","type":"实词","note":"形容词“私”（自私的）活用为动词“偏爱”。"},{"q":"『遂使之行成于吴』中「行成」的意思是（　）","opts":["使。。。停留","通“早”","应当，应该","求和，议和"],"ans":"D","atext":"求和，议和","word":"行成","type":"实词","note":"行成：求和。"},{"q":"『当淮阴破齐而欲自王』中「王」的意思是（　）","opts":["称王","指责","违背","即使"],"ans":"A","atext":"称王","word":"王","type":"实词","note":"王（wàng）：称王。"}],"p3":[{"q":"由也为之，比及三年，可使有勇，且知方也。","a":"让我仲由去治理，等到三年，可使人人有勇气，而且懂得礼义。","note":"方：正道，指明辨是非的礼义。","src":"子路曾皙冉有公西华侍坐"},{"q":"兄闻，喜曰：“弟必大贵，此狐来避雷霆劫也。”","a":"哥哥听说后，高兴地说：“弟弟必定大贵，这是狐狸来躲避雷霆之劫啊。”","note":"点出小翠一家报恩的前缘。","src":"小翠"},{"q":"琬顾谓藏之之难不若守之之难，守之之难不若读之之难，尤不若躬体而心得之之难。","a":"我却认为藏书的难比不上守书的难，守书的难比不上读书的难，更比不上亲身实践而心有所得的难。","note":"层层递进的主旨句。顾：转折连词。","src":"传是楼记"},{"q":"是以肠一日而九回，居则忽忽若有所亡，出则不知其所往。","a":"因此痛苦之情在腹中一天九转，在家就恍恍惚惚若有所失，出门就不知要往哪里去。","note":"“肠一日九回”夸张写内心痛苦；两个并列句写精神恍惚。","src":"报任安书"},{"q":"草创未就，会遭此祸，惜其不成，是以就极刑而无愠色。","a":"草稿还没有完成，恰巧遇上这场大祸，我痛惜书没有写成，因此身受最重的刑罚也没有怨恨的神色。","note":"“就”接近、承受；“愠”怨恨。说明为著书而忍辱。","src":"报任安书"},{"q":"陈相见许行而大悦，尽弃其学而学焉。陈相见孟子，道许行之言曰：\"滕君，则诚贤君也；虽然，未闻道也。贤者与民并耕而食，饔飧而治。今也滕有仓廪府库，则是厉民而以自养也，恶得贤？\"","a":"陈相见到许行非常高兴，完全抛弃自己原来的学说而向他学习。陈相见到孟子，转述许行的话说：\"滕君确实是个贤明的君主；虽然如此，他还没有懂得真正的道理。贤人应该和百姓一起耕种来获取食物，自己做饭一边治理天下。如今滕国有粮仓府库，这是损害百姓来供养自己，怎么能算贤明呢？\"","note":"","src":"许行"},{"q":"其是之谓乎？","a":"大概说的就是这种情况吧？","note":"“是之谓”即“谓是”，宾语前置。","src":"郑伯克段于鄢"},{"q":"阙秦以利晋，唯君图之。","a":"损害秦国而使晋国得利，希望您考虑这件事。","note":"唯：表希望的语气副词。说辞落脚点。","src":"烛之武退秦师"},{"q":"因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。","a":"靠过别人的力量反而损害他，是不仁；失去同盟国，是不智；以混乱相攻代替步调一致，是不武。","note":"排比三句。知通智；所与：同盟者。","src":"烛之武退秦师"},{"q":"不义不暱，厚将崩。","a":"对君不义、对兄不亲，土地再厚大也会垮台。","note":"暱同昵，亲近；厚：势力雄厚；崩：崩溃。","src":"郑伯克段于鄢"},{"q":"今逐客以资敌国，损民以益雠，内自虚而外树怨于诸侯，求国无危，不可得也。","a":"如今驱逐客卿来资助敌国，减损百姓来增加仇敌，对内造成自己空虚，对外在诸侯中树立怨恨，想求得国家没有危险，是不可能的啊。","note":"“雠”通“仇”；“树怨于诸侯”状语后置。总结全文，指出逐客必致危亡。","src":"谏逐客书"},{"q":"故不登高山，不知天之高也；不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。干、越、夷、貉之子，生而同声，长而异俗，教使之然也。《诗》曰：“嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。”神莫大于化道，福莫长于无祸。","a":"所以不登高山，就不知道天有多高；不面临深溪，就不知道地有多厚；不听取先王的遗训，就不知道学问的博大。干国、越国、夷族、貉族的孩子，初生时哭声相同，长大后习俗各异，是教化使他们这样的。《诗经》说：\"唉，你们君子，不要常贪图安逸休息。谨慎地安守你的职位，爱好正直的品德。神灵听到这些，会赐给你大福。\"精神的修养没有比受道的熏陶感化更大的，福分没有比无灾无祸更长久的。","note":"","src":"劝学"},{"q":"昭王之不复，君其问诸水滨。","a":"昭王没有回去，您还是去问水边的人吧。","note":"诸=之于。婉言拒绝承担昭王溺死之责。","src":"齐桓公伐楚"},{"q":"城北徐公，齐国之美丽者也。","a":"城北的徐公，是齐国的美男子。","note":"“……者也”表判断句。","src":"邹忌讽齐王纳谏"},{"q":"居则曰：“不吾知也！”如或知尔，则何以哉？","a":"（你们）平时常说：“不了解我啊！”如果有人了解你们，那打算怎么做呢？","note":"“不吾知”“何以”均为宾语前置，即“不知吾”“以何”。","src":"子路曾皙冉有公西华侍坐"},{"q":"六国破灭，非兵不利，战不善，弊在赂秦。","a":"六国灭亡，不是武器不锋利、仗打得不好，弊病在于贿赂秦国。","note":"开门见山提出中心论点；兵：兵器。判断句兼否定排比。","src":"六国论"},{"q":"丘也闻有国有家者，不患寡而患不均，不患贫而患不安。","a":"我听说诸侯和大夫，不担忧贫困而担忧分配不均，不担忧人少而担忧不安定。","note":"“也”句中语气词；孔子提出均贫富、安邦国的政治主张。","src":"季氏将伐颛臾"},{"q":"昆山徐健庵先生，筑楼于所居之后，凡七楹。","a":"昆山徐健庵先生，在他的住宅后面建造了一座楼，一共有七间。","note":"楹：房屋一间。开门见山交代楼的主人、位置、规模。","src":"传是楼记"},{"q":"人固有一死，或重于泰山，或轻于鸿毛，用之所趋异也。","a":"人本来就有一死，有的人死得比泰山还重，有的人死得比鸿毛还轻，这是因为他们所追求的东西不同啊。","note":"“于”介词表比较；“趋”趋向、目的。全句为生死价值观名句，判断句。","src":"报任安书"},{"q":"枕席而卧，则清泠之状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋。","a":"设枕铺席躺下，清凉明净的景色与眼睛相契合，回旋潺潺的水声与耳朵相契合，悠远虚空的境界与精神相契合，深沉幽静的气氛与心灵相契合。","note":"四“谋”字排比，由目、耳到神、心，层层深入；情景交融的名句。","src":"钴鉧潭西小丘记"}]},{"no":7,"date":"2026-11-04","date_end":"2026-11-05","pieces":["吕相绝秦","秋水","劝学","许行","烛之武退秦师","论贵粟疏"],"theme":"综合练习 7","p1":[{"q":"「有能助寡人谋而退吴者，吾与之共知越国之政。」出自（　）","opts":["《张中丞传后叙》","《勾践灭吴》","《传是楼记》","《触龙说赵太后》"],"ans":"B","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：有能帮我出谋划策击退吴军的，我和他共同掌管越国国政。"},{"q":"「粟者，王者大用，政之本务。」出自（　）","opts":["《齐桓公伐楚》","《烛之武退秦师》","《小翠》","《论贵粟疏》"],"ans":"D","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：粮食，是帝王最有用的东西，是政事的根本要务。"},{"q":"「圣人之忧民如此，而暇耕乎？」出自（　）","opts":["《秋水》","《劝学》","《许行》","《鸿门宴》"],"ans":"C","atext":"《许行》","src":"句子→篇目","note":"出自《许行》。参考译文：圣人这样为百姓操劳，哪里还有空闲种地呢？"},{"q":"「夫晋何厌之有？」出自（　）","opts":["《烛之武退秦师》","《六国论》","《钴鉧潭西小丘记》","《郑伯克段于鄢》"],"ans":"A","atext":"《烛之武退秦师》","src":"句子→篇目","note":"出自《烛之武退秦师》。参考译文：晋国哪里有满足的时候？"},{"q":"「以此众战，谁能御之！以此攻城，何城不克！」出自（　）","opts":["《齐桓晋文之事》","《六国论》","《齐桓公伐楚》","《谏逐客书》"],"ans":"C","atext":"《齐桓公伐楚》","src":"句子→篇目","note":"出自《齐桓公伐楚》。参考译文：用这样的军队作战，谁能抵挡！用这样的军队攻城，什么城攻不下！"},{"q":"「有复言令长安君为质者，老妇必唾其面。」出自（　）","opts":["《留侯论》","《吕相绝秦》","《烛之武退秦师》","《触龙说赵太后》"],"ans":"D","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：有再说让长安君去做人质的人，我一定朝他脸上吐唾沫。"},{"q":"「子曰：“以吾一日长乎尔，毋吾以也。居则曰：‘不吾知也！’如或知尔，则何以哉？”」出自（　）","opts":["《季氏将伐颛臾》","《触龙说赵太后》","《齐桓晋文之事》","《子路曾皙冉有公西华侍坐》"],"ans":"D","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：孔子说：\"因为我比你们年长几岁，不要因为这个就不敢说了。你们平时常说：'没有人了解我呀！'如果有人了解你们，那你们打算怎么做呢？\""},{"q":"「挟太山以超北海，语人曰：我不能。是诚不能也。」出自（　）","opts":["《郑伯克段于鄢》","《齐桓晋文之事》","《鸿门宴》","《报任安书》"],"ans":"B","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：挟着泰山跳过北海，告诉人说：我做不到。这是真的做不到。"},{"q":"「距关，毋内诸侯，秦地可尽王也。」出自（　）","opts":["《勾践灭吴》","《报任安书》","《鸿门宴》","《齐桓公伐楚》"],"ans":"C","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：把守函谷关，不要让诸侯进来，秦地可以全部称王了。"},{"q":"「民者，在上所以牧之，趋利如水走下，四方无择也。夫珠玉金银，饥不可食，寒不可衣，然而众贵之者，以上用之故也。其为物轻微易藏，在于把握，可以周海内而无饥寒之患。此令臣轻背其主，而民易去其乡，盗贼有所劝，亡逃者得轻资也。粟米布帛生于地，长于时，聚于力，非可一日成也；数石之重，中人弗胜，不为奸邪所利，一日弗得而饥寒至。是故明君贵五谷而贱金玉。」出自（　）","opts":["《论贵粟疏》","《触龙说赵太后》","《烛之武退秦师》","《劝学》"],"ans":"A","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：百姓，是君主所统治的，他们趋向利益就像水往低处流，不选择方向。珠玉金银，饿了不能吃，冷了不能穿，然而众人都珍视它们，是因为君主使用它们的缘故。这些东西作为物品轻小容易收藏，拿在手中"},{"q":"「\"以粟易械器者，不为厉陶冶；陶冶亦以其械器易粟者，岂为厉农夫哉？且许子何不为陶冶，舍皆取诸其宫中而用之？何为纷纷然与百工交易？何许子之不惮烦？\"」出自（　）","opts":["《小翠》","《劝学》","《逍遥游》","《许行》"],"ans":"D","atext":"《许行》","src":"句子→篇目","note":"出自《许行》。参考译文：\"用粮食换器具的人，不算损害陶匠铁匠；陶匠铁匠也用他们的器具换粮食，难道算损害农夫吗？况且许先生为什么不自己烧陶炼铁，什么东西都从自己家里取来用？为什么忙忙碌碌地和各种工匠交易？为"},{"q":"「沛公已去，间至军中。张良入谢，曰：“沛公不胜桮杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下，玉斗一双，再拜奉大将军足下。”项王曰：“沛公安在？”良曰：“闻大王有意督过之，脱身独去，已至军矣。”项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：“唉！竖子不足与谋。夺项王天下者必沛公也。吾属今为之虏矣！”」出自（　）","opts":["《鸿门宴》","《谏逐客书》","《吕相绝秦》","《齐桓公伐楚》"],"ans":"A","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：沛公已经离开，从小路到了军中。张良进去谢罪，说：\"沛公不能多喝酒，不能亲自告辞。谨派我张良捧白璧一双，再拜献给大王足下，玉斗一双，再拜奉给大将军足下。\"项王说：\"沛公在哪里？\"张良"},{"q":"英国作家，代表作《德伯家的苔丝》，属批判现实主义。（　）","opts":["蒙田","哈代","荷马","海明威"],"ans":"B","atext":"哈代","src":"释义→词条","note":"哈代：英国作家，代表作《德伯家的苔丝》，属批判现实主义。"},{"q":"指意大利的但丁、彼特拉克、薄伽丘。（注意：美术三杰为达·芬奇、米开朗琪罗、拉斐尔）（　）","opts":["奥斯特洛夫斯基","新喜剧（前323-前263）","索福克勒斯","文艺复兴『三杰』"],"ans":"D","atext":"文艺复兴『三杰』","src":"释义→词条","note":"文艺复兴『三杰』：指意大利的但丁、彼特拉克、薄伽丘。（注意：美术三杰为达·芬奇、米开朗琪罗、拉斐尔）"},{"q":"16世纪最著名的流浪汉小说；开创了“流浪汉小说”叙事结构（　）","opts":["托马斯.莫尔","《小癞子》","诺贝尔文学奖","荷马"],"ans":"B","atext":"《小癞子》","src":"释义→词条","note":"《小癞子》：16世纪最著名的流浪汉小说；开创了“流浪汉小说”叙事结构"},{"q":"俄国文学重要主题，写底层小人物的悲惨命运。代表：普希金《驿站长》、果戈理《外套》、陀思妥耶夫斯基《穷人》、契诃夫《小公务员之死》。（　）","opts":["柏拉图","亚里士多德","『小人物』主题","外国文学三大短篇小说巨匠"],"ans":"C","atext":"『小人物』主题","src":"释义→词条","note":"『小人物』主题：俄国文学重要主题，写底层小人物的悲惨命运。代表：普希金《驿站长》、果戈理《外套》、陀思妥耶夫斯基《穷人》、契诃夫《小公务员之死》。"},{"q":"美国作家，1954年获诺贝尔文学奖，代表作《老人与海》（名句『一个人并不是生来要给打败的，你尽可以把他消灭掉，可就是打不败他』）、《永别了，武器》。（　）","opts":["奥维德","欧里庇得斯","海明威","《小癞子》"],"ans":"C","atext":"海明威","src":"释义→词条","note":"海明威：美国作家，1954年获诺贝尔文学奖，代表作《老人与海》（名句『一个人并不是生来要给打败的，你尽可以把他消灭掉，可就是打不败他』）、《永别了，武器》。"},{"q":"18世纪末至19世纪上半叶欧洲文学思潮，强调主观情感、想象、自由，反抗古典主义束缚。代表：雨果（法）、拜伦、雪莱（英）、普希金（俄）、惠特曼（美）。（　）","opts":["乔伊斯","浪漫主义","《小癞子》","索福克勒斯"],"ans":"B","atext":"浪漫主义","src":"释义→词条","note":"浪漫主义：18世纪末至19世纪上半叶欧洲文学思潮，强调主观情感、想象、自由，反抗古典主义束缚。代表：雨果（法）、拜伦、雪莱（英）、普希金（俄）、惠特曼（美）。"},{"q":"《触龙说赵太后》的作者是（　）","opts":["刘向","郦道元","苏洵","荀子"],"ans":"A","atext":"刘向","src":"作品→作者","note":"《触龙说赵太后》— 刘向。原文标注：刘向 辑录（《战国策》）"},{"q":"《逍遥游》的作者是（　）","opts":["司马迁","庄周","蒲松龄","柳宗元"],"ans":"B","atext":"庄周","src":"作品→作者","note":"《逍遥游》— 庄周。原文标注：庄周（庄子）"}],"p2":[{"q":"『或谓之曰』中「或」的意思是（　）","opts":["抬眼","担任；写","确实，的确","有的人"],"ans":"D","atext":"有的人","word":"或","type":"实词","note":"「或」：有的人"},{"q":"『夫人朝夕退而游焉』中「焉」的意思是（　）","opts":["使动，使……活、救活","兼词，“于之”，在那里","半步（音kuǐ）","通“供”，供给"],"ans":"B","atext":"兼词，“于之”，在那里","word":"焉","type":"实词","note":"「焉」：兼词，“于之”，在那里"},{"q":"『通古今之变』中「通」的意思是（　）","opts":["名词作动词，筑巢","通晓、贯通","通“供”，供给","通“磨”，磨灭"],"ans":"B","atext":"通晓、贯通","word":"通","type":"实词","note":"通晓古今变化。"},{"q":"『不能通知二父志』中「通知」的意思是（　）","opts":["用酒食款待、犒劳","触碰，撞上，突过。","透彻理解、完全了解","迅疾的样子，一跃而起。"],"ans":"C","atext":"透彻理解、完全了解","word":"通知","type":"实词","note":"今义为“告知”，古义为“通晓”。"},{"q":"『欲其旅进旅退』中「旅进旅退」的意思是（　）","opts":["同进同退，步调一致","通“隙”，空隙，引申为身体不适","疲困、衰败","通“避”，躲避"],"ans":"A","atext":"同进同退，步调一致","word":"旅进旅退","type":"实词","note":"旅：俱，共同。"},{"q":"『两岸连山，略无阙处』中「阙」的意思是（　）","opts":["缺口、中断","指国家","回答","增加"],"ans":"A","atext":"缺口、中断","word":"阙","type":"实词","note":"“阙”通“缺”，指山势中断之处。"},{"q":"『负土而出』中「负」的意思是（　）","opts":["封侯","冒死","背着","你们"],"ans":"C","atext":"背着","word":"负","type":"实词","note":"拟人化，石头像背着泥土钻出来。"},{"q":"『王由是奇女』中「奇」的意思是（　）","opts":["通\"已\"，停止。","通“汝”，你，你们","认为……奇异","使动，使……来、招致"],"ans":"C","atext":"认为……奇异","word":"奇","type":"实词","note":"奇：意动，以……为奇。"},{"q":"『争为奇状者，殆不可数』中「殆」的意思是（　）","opts":["其、他们的","通“纵”，合纵","几乎、几乎多得","名词作状语，用火"],"ans":"C","atext":"几乎、几乎多得","word":"殆","type":"实词","note":"殆不可数：几乎数不清。"},{"q":"『数百步复反』中「反」的意思是（　）","opts":["亲善、和睦","同“返”，返回","挫败、屈辱","动词，做官；形容词，做官的"],"ans":"B","atext":"同“返”，返回","word":"反","type":"实词","note":"「反」：同“返”，返回"}],"p3":[{"q":"文公恐惧，绥静诸侯，秦师克还无害，则是我有大造于西也。","a":"文公为之恐惧，安抚诸侯，秦军才得以全身而退，这么说我们对西方（秦）有大功。","note":"绥静：安抚；大造：大恩惠。","src":"吕相绝秦"},{"q":"而吾未尝以此自多者，自以比形于天地，而受气于阴阳。","a":"可是我从不因此自我夸耀，因为我自以为从天地禀受了形体。","note":"多：意动，夸耀；比形：寄形、禀形。写海若不自满。","src":"秋水"},{"q":"康公，我之自出。","a":"康公，是我们晋国的外甥（晋女所生）。","note":"判断句。康公母为晋穆姬，故云“我之自出”。","src":"吕相绝秦"},{"q":"蔑死我君，寡我襄公，迭我殽地。","a":"蔑视我们故去的国君，欺侮我们襄公，侵犯我们的殽地。","note":"寡：意动，欺藐；迭：通“轶”，侵犯。","src":"吕相绝秦"},{"q":"是故质的张而弓矢至焉，林木茂而斧斤至焉，树成荫而众鸟息焉，醯酸而蚋聚焉。","a":"所以靶子一摆开，弓箭就射来了；树林一茂盛，斧头就来了；树荫一成片，鸟就栖息了；醋一变酸，蚊蚋就聚拢来了。","note":"“质的”箭靶（的dì）；“焉”兼词。四句博喻，说明物各从其类、言行动则招应。","src":"劝学"},{"q":"然则治天下独可耕且为与？","a":"那么唯独治理天下就能一边种地一边兼做吗？","note":"反问，归谬法。由\"百工不可耕且为\"推出治天下亦有分工。","src":"许行"},{"q":"贤者与民并耕而食，饔飧而治。","a":"贤君应当和百姓一起种地吃饭，一面做饭一面治理国事。","note":"饔飧：自炊。这是农家\"君民并耕\"的主张，孟子反驳的靶子。","src":"许行"},{"q":"当尧之时，天下犹未平，洪水横流，泛滥于天下。草木畅茂，禽兽繁殖，五谷不登，禽兽偪人。兽蹄鸟迹之道，交于中国。尧独忧之，举舜而敷治焉。舜使益掌火，益烈山泽而焚之，禽兽逃匿。禹疏九河，瀹济漯，而注诸海；决汝汉，排淮泗，而注之江，然后中国可得而食也。当是时也，禹八年于外，三过其门而不入，虽欲耕，得乎？","a":"在尧的时候，天下还没有平定，洪水四处横流，泛滥于天下。草木茂盛，禽兽繁殖，五谷不收，禽兽侵害人类。野兽的蹄印和鸟的踪迹，纵横交错于中原。尧独自为此忧虑，举用舜来治理。舜派伯益掌管火政，伯益在山泽中燃起大火焚烧，禽兽逃跑躲藏。禹疏通九河，疏导济水、漯水，使它们流入大海；开凿汝水、汉水，排除淮水、泗水，使它们流入长江，然后中原才能种植收获。在这个时候，禹在外八年，三次经过自己的家门都没有进去，虽然他想耕种，能行吗？","note":"","src":"许行"},{"q":"佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”公从之。辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”公曰：“吾不能早用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉。”许之。","a":"佚之狐对郑文公说：\"国家危险了，如果派烛之武去见秦国国君，军队一定会撤退。\"郑文公听从了。烛之武推辞说：\"我壮年的时候，尚且不如别人；如今老了，不能做什么了。\"郑文公说：\"我不能早早重用您，如今情况紧急才来求您，这是我的过错。然而郑国灭亡了，对您也有不利啊。\"烛之武答应了。","note":"","src":"烛之武退秦师"},{"q":"有者半贾而卖，无者取倍称之息，于是有卖田宅、鬻子孙以偿债者矣。","a":"有粮的人半价出卖，没粮的人借加倍利息的高利贷，于是就有了卖掉田宅、卖掉子孙来还债的人。","note":"“贾”通“价”；“倍称之息”加倍利息；“鬻”卖。写农民破产。","src":"论贵粟疏"},{"q":"穆、襄即世，康、灵即位。康公，我之自出，又欲阙翦我公室，倾覆我社稷，帅我蝥贼，以来荡摇我边疆。我是以有令狐之役。康犹不悛，入我河曲，伐我涑川，俘我王官，翦我羁马。我是以有河曲之战。东道之不通，则是康公绝我好也。","a":"穆公、襄公去世，康公、灵公即位。康公是我晋国女子所生，却又想铲除我公室，颠覆我国家，带领我晋国的内奸，来扰乱我边疆，因此我们才打了令狐之战。康公仍然不改，侵入我河曲，攻打我涑川，掳掠我王官，剪除我羁马，因此我们才打了河曲之战。东方道路不通，就是康公断绝了我们之间的友好。","note":"","src":"吕相绝秦"},{"q":"此其比万物也，不似毫末之在于马体乎？","a":"人和万物相比，不就像一根毫毛在马身上吗？","note":"毫末：毫毛尖端。极言人之渺小。","src":"秋水"},{"q":"故君子居必择乡，游必就士，所以防邪辟而近中正也。","a":"所以君子居住一定要选择乡里，交游一定要接近贤士，这是用来防止邪恶而接近正道的。","note":"“所以”：用来……的（方法）。由环境之喻得出重择乡交友的结论。","src":"劝学"},{"q":"此非所以跨海内、制诸侯之术也。","a":"这不是用来统一天下、制服诸侯的方法啊。","note":"“所以”：用来……的方法；判断句（否定判断）。紧切秦王兼并天下之心。","src":"谏逐客书"},{"q":"千金之子，不死于盗贼，何者？其身之可爱，而盗贼之不足以死也。","a":"富贵人家的子弟，不死在盗贼手里，为什么呢？因为他的生命值得爱惜，不值得为盗贼而死。","note":"可爱：值得爱惜（古今异义）。设喻说明张良不应行刺冒险。","src":"留侯论"},{"q":"齐侯与蔡姬乘舟于囿，荡公。公惧变色；禁之，不可。公怒，归之，未之绝也。蔡人嫁之。","a":"齐桓公和蔡姬在园囿中乘船，蔡姬摇晃船身戏弄桓公。桓公害怕，脸色都变了；制止她，她不停。桓公发怒，把她送回蔡国，但还没有断绝婚姻关系。蔡国人却把她改嫁了。","note":"","src":"齐桓公伐楚"},{"q":"南方有鸟焉，名曰蒙鸠，以羽为巢，而编之以发，系之苇苕，风至苕折，卵破子死。巢非不完也，所系者然也。","a":"南方有一种鸟，名叫蒙鸠，用羽毛做巢，用毛发编织起来，系在芦苇的嫩条上，风一吹芦苇条折断，鸟蛋摔破，雏鸟死掉。巢不是不完善，是系的地方使它这样的。","note":"","src":"劝学"},{"q":"位尊而无功，奉厚而无劳，而挟重器多也。","a":"地位尊贵却没有功勋，俸禄丰厚却没有劳绩，拥有的珍宝太重了。","note":"奉通“俸”；三个并列分句，排比重申“无功不能受尊”之理。","src":"触龙说赵太后"},{"q":"一座大惊，皆感激为云泣下。","a":"满座的人大为震惊，都被感动得为南霁云流下眼泪。","note":"感激：感动奋发（古今异义）。写断指之事的震撼力。","src":"张中丞传后叙"},{"q":"老吾老，以及人之老；幼吾幼，以及人之幼：天下可运于掌。","a":"敬爱自己的老人，推广到敬爱别人的老人；爱护自己的孩子，推广到爱护别人的孩子：统一天下就像在手掌上转动东西一样容易。","note":"老、幼均形作动/形作名；及：推及。\"推恩\"的核心。","src":"齐桓晋文之事"}]},{"no":8,"date":"2026-11-05","date_end":"2026-11-06","pieces":["巫山巫峡","秋水","逍遥游","触龙说赵太后","传是楼记","郑伯克段于鄢"],"theme":"综合练习 8","p1":[{"q":"「以吾一日长乎尔，毋吾以也。」出自（　）","opts":["《子路曾皙冉有公西华侍坐》","《邹忌讽齐王纳谏》","《郑伯克段于鄢》","《烛之武退秦师》"],"ans":"A","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：因为我比你们年纪大一点，不要因为我（年长）就不敢说话了。"},{"q":"「斥鴳笑之曰：\"彼且奚适也？我腾跃而上，不过数仞而下，翱翔蓬蒿之间，此亦飞之至也，而彼且奚适也？\"此小大之辩也。」出自（　）","opts":["《传是楼记》","《巫山巫峡》","《逍遥游》","《谏逐客书》"],"ans":"C","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：斥鴳讥笑它说：\"它将要到哪里去呢？我腾跃向上飞，不过几丈高就落下来，在蓬蒿丛中盘旋，这也算是飞的最高限度了。可是它将要到哪里去呢？\"这就是小和大的区别。"},{"q":"「诺，恣君之所使之。」出自（　）","opts":["《触龙说赵太后》","《论贵粟疏》","《鸿门宴》","《郑伯克段于鄢》"],"ans":"A","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：好吧，任凭您指派他吧。"},{"q":"「于是为长安君约车百乘，质于齐，齐兵乃出。」出自（　）","opts":["《留侯论》","《六国论》","《触龙说赵太后》","《张中丞传后叙》"],"ans":"C","atext":"《触龙说赵太后》","src":"句子→篇目","note":"出自《触龙说赵太后》。参考译文：于是替长安君备车百辆，到齐国做人质，齐国才出兵。"},{"q":"「吾力足以举百钧，而不足以举一羽；明足以察秋毫之末，而不见舆薪。」出自（　）","opts":["《齐桓晋文之事》","《鸿门宴》","《邹忌讽齐王纳谏》","《触龙说赵太后》"],"ans":"A","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：我的力气足以举起三千斤，却拿不起一根羽毛；视力足以看清秋天兽毛的末梢，却看不见整车柴草。"},{"q":"「无禄，文公即世，穆为不吊，蔑死我君，寡我襄公，迭我殽地，奸绝我好，伐我保城，殄灭我费滑，散离我兄弟，挠乱我同盟，倾覆我国家。我襄公未忘君之旧勋，而惧社稷之陨，是以有殽之师。犹愿赦罪于穆公，穆公弗听，而即楚谋我。天诱其衷，成王陨命，穆公是以不克逞志于我。」出自（　）","opts":["《六国论》","《劝学》","《吕相绝秦》","《小翠》"],"ans":"C","atext":"《吕相绝秦》","src":"句子→篇目","note":"出自《吕相绝秦》。参考译文：不幸，文公去世，穆公却不为我们的丧事表示哀悼，轻视我们死去的国君，欺侮我们新君襄公，突然进犯我们殽地，断绝我们的友好，攻打我们守卫的城邑，灭掉我们的费滑，离散我们的兄弟之国，扰乱我"},{"q":"「说者又谓远与巡分城而守，城之陷，自远所分始。以此诟远，此又与儿童之见无异。人之将死，其藏腑必有先受其病者；引绳而绝之，其绝必有处。观者见其然，从而尤之，其亦不达于理矣！小人之好议论，不乐成人之美，如是哉！如巡、远之所成就，如此卓卓，犹不得免，其他则又何说！」出自（　）","opts":["《张中丞传后叙》","《六国论》","《论贵粟疏》","《邹忌讽齐王纳谏》"],"ans":"A","atext":"《张中丞传后叙》","src":"句子→篇目","note":"出自《张中丞传后叙》。参考译文：议论的人又说许远和张巡分城而守，城池的陷落，是从许远所分守的地方开始的。用这个来诟骂许远，这又和儿童的见识没有两样。人将要死的时候，他的内脏一定有先受病害的地方；拉绳子把它拉断，断"},{"q":"「王太常，越人。总角时，昼卧榻上。忽阴晦，巨霆暴作，一物大于猫，来伏身下，展转不离。移时晴霁，物即径出。视之非猫，始怖，隔房呼兄。兄闻，喜曰：“弟必大贵，此狐来避雷霆劫也。”后果少年登进士，以县令入为侍御。」出自（　）","opts":["《小翠》","《逍遥游》","《留侯论》","《许行》"],"ans":"A","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：王太常是越地人。童年时，白天躺在榻上。忽然天色阴暗，巨雷暴发，有一个比猫大的东西，跑来伏在他身下，辗转不离。过了一些时候天晴了，那东西就径直出去了。看它不是猫，才害怕起来，隔着房间"},{"q":"「千金之子，不死于盗贼，何者？其身之可爱，而盗贼之不足以死也。子房以盖世之才，不为伊尹、太公之谋，而特出于荆轲、聂政之计，以侥幸于不死，此圯上老人所为深惜者也。是故倨傲鲜腆而深折之。彼其能有所忍也，然后可以就大事，故曰：“孺子可教也。”」出自（　）","opts":["《逍遥游》","《巫山巫峡》","《留侯论》","《秋水》"],"ans":"C","atext":"《留侯论》","src":"句子→篇目","note":"出自《留侯论》。参考译文：千金之家的子弟，不会死在盗贼手里，为什么呢？因为他的身体值得爱惜，而盗贼不值得为他去死。张良凭盖世的才能，不去谋划伊尹、太公那样的大计，却偏偏使出荆轲、聂政那样的刺客之计，靠侥幸得"},{"q":"「丘之小不能一亩，可以笼而有之。」出自（　）","opts":["《钴鉧潭西小丘记》","《鸿门宴》","《烛之武退秦师》","《逍遥游》"],"ans":"A","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：这小丘小得不足一亩，简直可以把它装在笼子里占有它。"},{"q":"「民者，在上所以牧之，趋利如水走下，四方无择也。」出自（　）","opts":["《留侯论》","《论贵粟疏》","《张中丞传后叙》","《郑伯克段于鄢》"],"ans":"B","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：百姓，是君主所统治的；他们追逐利益就像水往低处流，东西南北是不加选择的。"},{"q":"「云知贺兰终无为云出师意，即驰去；将出城，抽矢射佛寺浮图，矢着其上砖半箭」出自（　）","opts":["《郑伯克段于鄢》","《季氏将伐颛臾》","《吕相绝秦》","《张中丞传后叙》"],"ans":"D","atext":"《张中丞传后叙》","src":"句子→篇目","note":"出自《张中丞传后叙》。参考译文：南霁云知道贺兰进明终究没有为自己出兵的意思，就骑马疾驰而去；将要出城时，抽出箭射向佛寺的宝塔，箭射中塔上的砖深入半箭。"},{"q":"“西班牙戏剧之父”；代表作《羊泉村》（　）","opts":["洛贝·德·维伽","《哈姆雷特》","福楼拜（法国）批判现实","索福克勒斯"],"ans":"A","atext":"洛贝·德·维伽","src":"释义→词条","note":"洛贝·德·维伽：“西班牙戏剧之父”；代表作《羊泉村》"},{"q":"柏拉图和老师苏格拉底，学生亚里士多德并称为希腊三贤；《理想国》（　）","opts":["柏拉图","福楼拜","司汤达","亚里士多德"],"ans":"A","atext":"柏拉图","src":"释义→词条","note":"柏拉图：柏拉图和老师苏格拉底，学生亚里士多德并称为希腊三贤；《理想国》"},{"q":"苏联作家，代表作《钢铁是怎样炼成的》，塑造无产阶级英雄保尔·柯察金。（　）","opts":["海明威","奥斯特洛夫斯基","大学才子派","诺贝尔文学奖"],"ans":"B","atext":"奥斯特洛夫斯基","src":"释义→词条","note":"奥斯特洛夫斯基：苏联作家，代表作《钢铁是怎样炼成的》，塑造无产阶级英雄保尔·柯察金。"},{"q":"爱尔兰作家，代表作《尤利西斯》，意识流小说代表作。（　）","opts":["古典主义","司汤达","乔伊斯","英国"],"ans":"C","atext":"乔伊斯","src":"释义→词条","note":"乔伊斯：爱尔兰作家，代表作《尤利西斯》，意识流小说代表作。"},{"q":"对比手法描写；主人公：埃斯梅拉达（吉普赛姑娘）、克洛德（圣母院副主教）、伽西莫多（圣母院敲钟人）、弗比斯、居第尔（　）","opts":["意识流小说代表","福楼拜（法国）批判现实","玛格丽特·米切尔（美国）","《巴黎圣母院》(长篇小说)"],"ans":"D","atext":"《巴黎圣母院》(长篇小说)","src":"释义→词条","note":"《巴黎圣母院》(长篇小说)：对比手法描写；主人公：埃斯梅拉达（吉普赛姑娘）、克洛德（圣母院副主教）、伽西莫多（圣母院敲钟人）、弗比斯、居第尔"},{"q":"夏洛克（莎士比亚《威尼斯商人》）、阿巴贡（莫里哀《悭吝人》）、葛朗台（巴尔扎克《欧也妮·葛朗台》）、泼留希金（果戈理《死魂灵》）。（　）","opts":["诺贝尔文学奖","『多余人』形象","亚里士多德","世界四大吝啬鬼"],"ans":"D","atext":"世界四大吝啬鬼","src":"释义→词条","note":"世界四大吝啬鬼：夏洛克（莎士比亚《威尼斯商人》）、阿巴贡（莫里哀《悭吝人》）、葛朗台（巴尔扎克《欧也妮·葛朗台》）、泼留希金（果戈理《死魂灵》）。"},{"q":"《鸿门宴》的作者是（　）","opts":["荀子","司马迁","郦道元","苏轼"],"ans":"B","atext":"司马迁","src":"作品→作者","note":"《鸿门宴》— 司马迁。原文标注：司马迁（选自《史记·项羽本纪》）"},{"q":"《齐桓公伐楚》的作者是（　）","opts":["郦道元","左丘明","李斯","刘向"],"ans":"B","atext":"左丘明","src":"作品→作者","note":"《齐桓公伐楚》— 左丘明。原文标注：左丘明（相传）"}],"p2":[{"q":"『数石之重，中人弗胜』中「胜」的意思是（　）","opts":["土地方圆（地：土地；方：方圆）","承受、经得起（音shēng）","直上穿过，超越。","形容词作动词，交好、友善"],"ans":"B","atext":"承受、经得起（音shēng）","word":"胜","type":"实词","note":"读shēng，胜任。"},{"q":"『其花披哆而色燥』中「披哆」的意思是（　）","opts":["常，永久固定的。","展开、散开","通“俸”，俸禄","指国家"],"ans":"B","atext":"展开、散开","word":"披哆","type":"实词","note":"「披哆」：展开、散开"},{"q":"『君若以德绥诸侯』中「绥」的意思是（　）","opts":["为什么","迎接","向东","安抚"],"ans":"D","atext":"安抚","word":"绥","type":"实词","note":"以德安抚。"},{"q":"『庶几其一惧』中「惧」的意思是（　）","opts":["向东","同意","害怕","认为"],"ans":"C","atext":"害怕","word":"惧","type":"实词","note":"「惧」：害怕"},{"q":"『婴金铁受辱』中「婴」的意思是（　）","opts":["险峻的山峰","缠绕、被加在身","节操、操守","缺点，毛病"],"ans":"B","atext":"缠绕、被加在身","word":"婴","type":"实词","note":"婴：绕，指颈戴铁索。"},{"q":"『翕然有名于当世』中「翕然」的意思是（　）","opts":["一致的样子","近年间","停止、平息","肃杀、凄清"],"ans":"A","atext":"一致的样子","word":"翕然","type":"实词","note":"翕（xī）然：一致。"},{"q":"『李牧连却之』中「却」的意思是（　）","opts":["使……退却、击退","区分、分类","使……亏损，损害","通\"诉\"，申诉，控诉。"],"ans":"A","atext":"使……退却、击退","word":"却","type":"实词","note":"却：使动用法。"},{"q":"『遥呼曰』中「遥」的意思是（　）","opts":["同意","飞奔的马","远远地","为什么"],"ans":"C","atext":"远远地","word":"遥","type":"实词","note":"「遥」：远远地"},{"q":"『宰使人廉之』中「廉」的意思是（　）","opts":["考察，查访","沉重","缺点，毛病","积蓄，准备"],"ans":"A","atext":"考察，查访","word":"廉","type":"实词","note":"「廉」：考察，查访"},{"q":"『越王勾践栖于会稽之上』中「栖」的意思是（　）","opts":["屯驻，退守","闲逛，游乐；学习","仔细","没有"],"ans":"A","atext":"屯驻，退守","word":"栖","type":"实词","note":"本为鸟栖，此指退守。"}],"p3":[{"q":"当崩之日，水逆流百余里，涌起数十丈。","a":"就在山崖崩塌那天，江水逆流而上一百多里，激起的波浪高达几十丈。","note":"写新崩滩由山崩成滩，侧笔见水势之险。","src":"巫山巫峡"},{"q":"秋水时至，百川灌河。","a":"秋天的洪水按季节到来，千百条河流注入黄河。","note":"时：按季节（名词作状语）；灌：注入。开篇写河伯初见壮阔而自喜。","src":"秋水"},{"q":"之二虫又何知！","a":"这两只小动物又懂得什么呢！","note":"之：此；何知：宾语前置（知何）。二虫指蜩与学鸠。","src":"逍遥游"},{"q":"老臣今者殊不欲食，乃自强步，日三四里，少益耆食，和于身。","a":"我近来很不想吃东西，就自己勉强走走，每天三四里，渐渐稍微想吃点东西，身体舒适些了。","note":"耆通“嗜”；“日三四里”“日”名词作状语；触龙以养生话题缓解太后情绪。","src":"触龙说赵太后"},{"q":"善读书者根柢于性命而究极于事功：沿流以溯源，无不探也；明体以适用，无不达也。","a":"善于读书的人以性命义理为根基，而最终落实于事功：顺着流来追溯源，没有探究不到的；明了本体而加以应用，没有不通达的。","note":"根柢、究极：名作动。体用结合的读书观。","src":"传是楼记"},{"q":"书曰：“郑伯克段于鄢。”段不弟，故不言弟；如二君，故曰克；称郑伯，讥失教也；谓之郑志。不言出奔，难之也。","a":"《春秋》记载说：\"郑伯在鄢地战胜了段。\"段不守做弟弟的本分，所以不说\"弟\"；如同两个国君相战，所以用\"克\"；称\"郑伯\"，是讥讽他失去对弟弟的教诲；说这是郑伯的本意。不写\"出奔\"，是为难以下笔（含有责难郑伯之意）。","note":"","src":"郑伯克段于鄢"},{"q":"君子生非异也，善假于物也。","a":"君子的天性同一般人并没什么差别，只是善于借助外物罢了。","note":"判断句；“生”通“性”，天性；“假”借助。点明学习本质在于善假外物。","src":"劝学"},{"q":"积土成山，风雨兴焉；积水成渊，蛟龙生焉；积善成德，而神明自得，圣心备焉。故不积跬步，无以至千里；不积小流，无以成江海。骐骥一跃，不能十步；驽马十驾，功在不舍。锲而舍之，朽木不折；锲而不舍，金石可镂。蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。蟹六跪而二螯，非蛇鳝之穴无可寄托者，用心躁也。","a":"堆土成山，风雨就从那里兴起；积水成渊，蛟龙就在那里生长；积累善行养成品德，那么精神智慧自然获得，圣人的心境就具备了。所以不一步步积累，就无法到达千里之外；不汇集细小水流，就无法形成江海。骏马一跃，不能超过十步；劣马走十天也能达到，成功在于不停止。用刀刻一下就放下，即使是朽木也不能折断；不停地刻，金石也能雕刻成功。蚯蚓没有锋利的爪牙、强健的筋骨，却能上吃泥土，下饮地下水，是用心专一的缘故。螃蟹有六条腿和两只钳子，如果没有蛇和鳝鱼的洞穴就无处安身，是用心浮躁的缘故。","note":"","src":"劝学"},{"q":"夫子房受书于圯上之老人也，其事甚怪；然亦安知其非秦之世，有隐君子者出而试之。观其所以微见其意者，皆圣贤相与警戒之义；而世不察，以为鬼物，亦已过矣。且其意不在书。","a":"张良从圯上老人那里接受兵书，这件事很怪异；但也怎么知道不是秦朝时有一位隐居的君子出来考验他呢。看他用来稍稍显露心意的方式，都是圣贤相互警戒的道理；而世人不加审察，认为是鬼怪，也太过分了。况且老人的用意并不在兵书上。","note":"","src":"留侯论"},{"q":"赵太后新用事，秦急攻之。赵氏求救于齐，齐曰：“必以长安君为质，兵乃出。”太后不肯，大臣强谏。太后明谓左右：“有复言令长安君为质者，老妇必唾其面。”","a":"赵太后刚刚执政，秦国就加紧进攻赵国。赵国向齐国求救，齐国说：\"一定要用长安君作为人质，才出兵。\"赵太后不肯答应，大臣们极力劝谏。太后明确地告诉左右的人说：\"有再说让长安君去做人质的，我一定朝他脸上吐唾沫。\"","note":"","src":"触龙说赵太后"},{"q":"危而不持，颠而不扶，则将焉用彼相矣？","a":"（盲人）站不稳却不扶持，跌倒了却不搀扶，那还用那个辅助者干什么？","note":"以搀扶瞎子喻辅佐之责；焉：何必。","src":"季氏将伐颛臾"},{"q":"然亦安知其非秦之世，有隐君子者出而试之。","a":"然而又怎么知道那不是秦朝末年有一位隐居的高士，出来考验张良呢？","note":"安：怎么。翻案圯上老人授书的神怪之说。","src":"留侯论"},{"q":"然后卑事夫差，宦士三百人于吴，其身亲为夫差前马。","a":"然后谦卑地侍奉夫差，派三百人到吴国做奴仆，勾践亲自做夫差的马前卒。","note":"写勾践忍辱负重。前马：前驱。","src":"勾践灭吴"},{"q":"勾践之困于会稽，而归臣妾于吴者，三年而不倦。","a":"越王勾践被围困在会稽，而归顺吴国做奴仆，三年都不懈怠。","note":"归臣妾于吴：做奴仆。被动/状语后置。举勾践能忍为证。","src":"留侯论"},{"q":"鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。","a":"鹏迁往南海时，翅膀拍击水面三千里，乘着旋风盘旋而上九万里，凭借六月的大风离去。","note":"击：拍打；抟：盘旋；扶摇：旋风；六月息：六月海风。\"去以六月息\"为状语后置（以六月息去）。","src":"逍遥游"},{"q":"吾恐季孙之忧，不在颛臾，而在萧墙之内也。","a":"我恐怕季孙的忧虑不在颛臾，而在鲁国宫门之内啊。","note":"判断性结尾；“萧墙之内”暗指鲁君，成语“祸起萧墙”出处。","src":"季氏将伐颛臾"},{"q":"陈良之徒陈相与其弟辛，负耒耜而自宋之滕，曰：\"闻君行圣人之政，是亦圣人也，愿为圣人氓。\"","a":"陈良的门徒陈相和他的弟弟陈辛，背着农具从宋国来到滕国，说：\"听说您施行圣人的政治，您也是圣人了，愿意做圣人的百姓。\"","note":"","src":"许行"},{"q":"四方之士来者，必庙礼之。","a":"四方来投的贤士，一定在庙堂上招待他们。","note":"庙：名词作状语，在庙堂上。","src":"勾践灭吴"},{"q":"甚矣，书之多厄也！","a":"书籍遭遇的灾患太多了啊！","note":"主谓倒装（甚矣前置）。感叹藏书之难。","src":"传是楼记"},{"q":"安见方六七十如五六十而非邦也者？","a":"怎么见得纵横六七十里或五六十里的地方就不是国家呢？","note":"安：怎么、哪里；反问句，肯定冉有所治亦是邦国。","src":"子路曾皙冉有公西华侍坐"}]},{"no":9,"date":"2026-11-06","date_end":"2026-11-07","pieces":["子路曾皙冉有公西华侍坐","许行","张中丞传后叙","秋水","齐桓公伐楚","谏逐客书"],"theme":"综合练习 9","p1":[{"q":"「九月甲午，晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。晋军函陵，秦军氾南。」出自（　）","opts":["《报任安书》","《郑伯克段于鄢》","《季氏将伐颛臾》","《烛之武退秦师》"],"ans":"D","atext":"《烛之武退秦师》","src":"句子→篇目","note":"出自《烛之武退秦师》。参考译文：九月甲午日，晋文公、秦穆公联合围攻郑国，因为郑国曾对晋文公无礼，而且同时又亲附楚国。晋军驻扎在函陵，秦军驻扎在氾水之南。"},{"q":"「王说，曰：\"诗云：他人有心，予忖度之。──夫子之谓也。夫我乃行之，反而求之，不得吾心；夫子言之，于我心有戚戚焉。此心之所以合于王者，何也？\"」出自（　）","opts":["《谏逐客书》","《报任安书》","《留侯论》","《齐桓晋文之事》"],"ans":"D","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：宣王高兴地说：\"《诗经》说：别人有心思，我能揣度到。说的就是先生您啊。我这样做了，回过头来寻找这样做的原因，却得不到自己的本心；先生您说出来，在我心里引起了共鸣。这种心之所以符合称"},{"q":"「古之善读书者，始乎博，终乎约，博之而非夸多斗靡也，约之而非保残安陋也。善读书者根柢于性命而究极于事功：沿流以溯源，无不探也；明体以适用，无不达也。尊所闻，行所知，非善读书者而能如是乎！」出自（　）","opts":["《齐桓晋文之事》","《传是楼记》","《勾践灭吴》","《逍遥游》"],"ans":"B","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：古代善于读书的人，从广博开始，到简约结束，广博不是为了夸耀多、争逐华丽，简约不是为了保守残缺、安于浅陋。善于读书的人以性命为根本而穷究事功：沿流溯源，没有什么不探究的；明体适用，没"},{"q":"「夫人无奈之，因杖其子。元丰大号，女始色变，屈膝乞宥。夫人怒顿解，释杖去。」出自（　）","opts":["《小翠》","《劝学》","《秋水》","《许行》"],"ans":"A","atext":"《小翠》","src":"句子→篇目","note":"出自《小翠》。参考译文：夫人拿她没办法，就用棍子打自己的儿子。元丰大哭，小翠这才脸色大变，跪下求饶。夫人的怒气顿时消了，放下棍子走了。"},{"q":"「夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。」出自（　）","opts":["《论贵粟疏》","《鸿门宴》","《许行》","《巫山巫峡》"],"ans":"B","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：秦王有虎狼一样的心肠，杀人唯恐杀不完，处罚人唯恐用不尽酷刑，天下人都背叛他。"},{"q":"「仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，略考其行事。」出自（　）","opts":["《勾践灭吴》","《张中丞传后叙》","《报任安书》","《传是楼记》"],"ans":"C","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：我私下不自量力，近来把自己的心思寄托在拙劣的文辞上，收集天下散失的历史传闻，粗略考证那些事迹。"},{"q":"「且举世誉之而不加劝，举世非之而不加沮。」出自（　）","opts":["《谏逐客书》","《许行》","《逍遥游》","《劝学》"],"ans":"C","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：全社会都称赞他，他却并不更加奋勉；全社会都非议他，他却并不更加沮丧。"},{"q":"「夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。」出自（　）","opts":["《论贵粟疏》","《逍遥游》","《季氏将伐颛臾》","《钴鉧潭西小丘记》"],"ans":"C","atext":"《季氏将伐颛臾》","src":"句子→篇目","note":"出自《季氏将伐颛臾》。参考译文：那颛臾，上代先王曾让它主持东蒙山祭祀，而且在鲁国疆域之内，是鲁国的藩属臣属。"},{"q":"「野语有之曰：'闻道百，以为莫己若者。'我之谓也。」出自（　）","opts":["《小翠》","《逍遥游》","《秋水》","《六国论》"],"ans":"C","atext":"《秋水》","src":"句子→篇目","note":"出自《秋水》。参考译文：俗语说：'听到上百条道理，便认为没人比得上自己。'说的就是我啊。"},{"q":"「奚以之九万里而南为？」出自（　）","opts":["《逍遥游》","《论贵粟疏》","《留侯论》","《报任安书》"],"ans":"A","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：哪里用得着飞上九万里的高空再向南飞呢？"},{"q":"「昆山徐健庵先生，筑楼于所居之后，凡七楹。间命工斫木为橱，贮书若干万卷，区为经史子集四种。经则传注义疏之书附焉，史则日录、家乘、山经、野史之书附焉，子则附以卜筮、医药之书，集则附以乐府、诗余之书。凡为橱者七十有二，部居类汇，各以其次，素标缃帙，启钥灿然。」出自（　）","opts":["《齐桓晋文之事》","《邹忌讽齐王纳谏》","《烛之武退秦师》","《传是楼记》"],"ans":"D","atext":"《传是楼记》","src":"句子→篇目","note":"出自《传是楼记》。参考译文：昆山徐健庵先生，在他住所的后面建了一座楼，共七间。让工匠砍削木材做成书橱，贮藏书籍若干万卷，分为经、史、子、集四类。经部则附上传注义疏之类的书，史部则附上日录、家乘、山经、野史之类"},{"q":"「今齐地方千里，百二十城。」出自（　）","opts":["《钴鉧潭西小丘记》","《邹忌讽齐王纳谏》","《六国论》","《留侯论》"],"ans":"B","atext":"《邹忌讽齐王纳谏》","src":"句子→篇目","note":"出自《邹忌讽齐王纳谏》。参考译文：如今齐国的土地方圆千里，有一百二十座城。"},{"q":"埃德蒙。斯宾塞：长诗《仙后》（　）","opts":["柏拉图","英国","贺拉斯","哈代"],"ans":"B","atext":"英国","src":"释义→词条","note":"英国：埃德蒙。斯宾塞：长诗《仙后》"},{"q":"1901年设立，依据诺贝尔遗嘱颁发给『在文学方面创作出具有理想倾向的最佳作品的人』。亚洲首位获奖者为印度泰戈尔（1913）。（　）","opts":["诺贝尔文学奖","浪漫主义","洛贝·德·维伽","果戈理"],"ans":"A","atext":"诺贝尔文学奖","src":"释义→词条","note":"诺贝尔文学奖：1901年设立，依据诺贝尔遗嘱颁发给『在文学方面创作出具有理想倾向的最佳作品的人』。亚洲首位获奖者为印度泰戈尔（1913）。"},{"q":"俄国作家，代表作《死魂灵》（塑造守财奴泼留希金）、《钦差大臣》。（　）","opts":["柏拉图","斯威夫特","索福克勒斯","果戈理"],"ans":"D","atext":"果戈理","src":"释义→词条","note":"果戈理：俄国作家，代表作《死魂灵》（塑造守财奴泼留希金）、《钦差大臣》。"},{"q":"《静静的顿河》（长篇小说）——获得诺贝尔文学奖；主人公：葛利高里（哥萨克的重大事件）（　）","opts":["玛格丽特·米切尔（美国）","新喜剧（前323-前263）","肖洛霍夫（苏联）","古典主义"],"ans":"C","atext":"肖洛霍夫（苏联）","src":"释义→词条","note":"肖洛霍夫（苏联）：《静静的顿河》（长篇小说）——获得诺贝尔文学奖；主人公：葛利高里（哥萨克的重大事件）"},{"q":"法国作家，代表作《追忆似水年华》，意识流小说开山之作。（　）","opts":["奥斯特洛夫斯基","欧里庇得斯","普鲁斯特","索福克勒斯"],"ans":"C","atext":"普鲁斯特","src":"释义→词条","note":"普鲁斯特：法国作家，代表作《追忆似水年华》，意识流小说开山之作。"},{"q":"法国批判现实主义作家，代表作《红与黑》，主人公于连是个人奋斗者的典型。（　）","opts":["人文主义","司汤达","意大利人","大江健三郎"],"ans":"B","atext":"司汤达","src":"释义→词条","note":"司汤达：法国批判现实主义作家，代表作《红与黑》，主人公于连是个人奋斗者的典型。"},{"q":"《郑伯克段于鄢》的作者是（　）","opts":["晁错","汪琬","郦道元","左丘明"],"ans":"D","atext":"左丘明","src":"作品→作者","note":"《郑伯克段于鄢》— 左丘明。原文标注：左丘明（相传）"},{"q":"《张中丞传后叙》的作者是（　）","opts":["苏洵","荀子","郦道元","韩愈"],"ans":"D","atext":"韩愈","src":"作品→作者","note":"《张中丞传后叙》— 韩愈。原文标注：韩愈"}],"p2":[{"q":"『安无倾』中「倾」的意思是（　）","opts":["倾覆","踢","责备","害怕"],"ans":"A","atext":"倾覆","word":"倾","type":"实词","note":"安则国家没有倾覆之患。"},{"q":"『善读书者根柢于性命』中「根柢」的意思是（　）","opts":["植根、立足","确实，的确","往，到……去","鉴戒、教训"],"ans":"A","atext":"植根、立足","word":"根柢","type":"实词","note":"根柢：名作动，扎根。"},{"q":"『适鬻金者之所』中「鬻」的意思是（　）","opts":["洗","发誓","卖","驻军"],"ans":"C","atext":"卖","word":"鬻","type":"实词","note":"「鬻」：卖"},{"q":"『世人患作文字少』中「患」的意思是（　）","opts":["这里","护城河","听说","毛病"],"ans":"D","atext":"毛病","word":"患","type":"实词","note":"「患」：毛病"},{"q":"『欲砺其齿』中「砺」的意思是（　）","opts":["果然","通晓","磨","半夜"],"ans":"C","atext":"磨","word":"砺","type":"实词","note":"「砺」：磨"},{"q":"『沛公军霸上』中「军」的意思是（　）","opts":["不足、不到","名词作动词，驻军","平时、平素家居","通\"智\"，智慧。"],"ans":"B","atext":"名词作动词，驻军","word":"军","type":"实词","note":"军：驻扎。"},{"q":"『欲持去』中「持」的意思是（　）","opts":["侵害","从前","拿","只是"],"ans":"C","atext":"拿","word":"持","type":"实词","note":"「持」：拿"},{"q":"『君子博学而日参省乎己』中「参」的意思是（　）","opts":["检验、检查（音cān）","符合、合乎（音zhòng）","称量（轻重）。","通“磨”，磨灭"],"ans":"A","atext":"检验、检查（音cān）","word":"参","type":"实词","note":"参省：检查反省。"},{"q":"『治于人者食人，治人者食于人。』中「食」的意思是（　）","opts":["兼词，相当于“于此”","其、他们的","献出、效力","供养，养活。"],"ans":"D","atext":"供养，养活。","word":"食","type":"实词","note":"食(sì)：使动，供养、养活。"},{"q":"『升堂拜饮』中「升」的意思是（　）","opts":["教诲","冒死","登","同意"],"ans":"C","atext":"登","word":"升","type":"实词","note":"「升」：登"}],"p3":[{"q":"非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。","a":"不敢说能做到，只是愿意学习。宗庙祭祀或诸侯会盟，我愿穿着礼服、戴着礼帽，做一个小小的赞礼人。","note":"端章甫：名词活用为动词；“小相”是公西华自谦之辞。","src":"子路曾皙冉有公西华侍坐"},{"q":"今也滕有仓廪府库，则是厉民而以自养也，恶得贤？","a":"如今滕国有储粮的仓廪、存财的府库，这是损害百姓来供养自己，怎么算贤明呢？","note":"厉：损害；恶(wū)：怎么。陈相转述许行的责难。","src":"许行"},{"q":"吾归破贼，必灭贺兰！此矢所以志也。","a":"我回去打败叛贼之后，必定消灭贺兰！这支箭就是我用来作标记的。","note":"志：通“识”，标记；所以：用来……的。","src":"张中丞传后叙"},{"q":"两家子弟材智下，不能通知二父志，以为巡死而远就虏，疑畏死而辞服于贼。","a":"两家子弟才能低下，不能透彻理解他们父辈的志向，认为张巡战死而许远被俘，怀疑许远是怕死而向敌人屈服了。","note":"通知：通晓（古今异义）；辞服：屈服。此为全文批驳的靶子。","src":"张中丞传后叙"},{"q":"伯夷辞之以为名，仲尼语之以为博。","a":"伯夷辞让它来求得名声，孔子谈论它来显示渊博。","note":"之：代天下。暗刺伯夷、孔子亦\"自多\"。","src":"秋水"},{"q":"君若以德绥诸侯，谁敢不服？","a":"您如果用德行安抚诸侯，谁敢不服？","note":"绥：安抚。屈完先以“德”为对。","src":"齐桓公伐楚"},{"q":"夫物不产于秦，可宝者多；士不产于秦，而愿忠者众。","a":"物品不出产在秦国，可宝贵的却很多；贤士不出生在秦国，愿意效忠的却很多。","note":"“宝”形容词意动/形作动，以为宝。并列对举，收束物与人两层。","src":"谏逐客书"},{"q":"群臣吏民能面刺寡人之过者，受上赏。","a":"大小官吏百姓能够当面指责我过错的，受上等奖赏。","note":"“能面刺寡人之过者”为“者”字结构作定语后置（即“能面刺寡人之过之群臣吏民”）；“面”名词作状语。","src":"邹忌讽齐王纳谏"},{"q":"赵氏求救于齐，齐曰：“必以长安君为质，兵乃出。”","a":"赵国向齐国求救，齐国说：“一定要用长安君作人质，救兵才派出。”","note":"“求救于齐”状语后置，即“于齐求救”；“乃”：才。","src":"触龙说赵太后"},{"q":"孟子对曰：\"仲尼之徒无道桓文之事者，是以后世无传焉，臣未之闻也。无以，则王乎？\"","a":"孟子回答说：\"孔子的门徒中没有谈论齐桓公、晋文公霸业的，所以后世没有流传，我没有听说过。如果一定要我说，那就说说行王道吧？\"","note":"","src":"齐桓晋文之事"},{"q":"余虽与晋出入，余唯利是视。","a":"我虽然同晋往来，我只图利。","note":"“唯利是视”即“唯视利”，宾语前置。引楚人转述秦语，揭秦唯利是图。","src":"吕相绝秦"},{"q":"都城过百雉，国之害也。","a":"都邑城墙超过百雉，是国家的祸害。","note":"判断句。都：卿大夫都邑；雉：长三丈高一丈为一雉。","src":"郑伯克段于鄢"},{"q":"人之将死，其藏腑必有先受其病者；引绳而绝之，其绝必有处。","a":"人将要死的时候，他的内脏必定有先得病的部位；拉紧绳子而断它，绳子的断裂必定有个地方。","note":"藏腑：即脏腑。以两个比喻说明城陷必有先后，不能因此归咎许远。","src":"张中丞传后叙"},{"q":"至人无己，神人无功，圣人无名。","a":"道德修养最高的人忘却自我，神人不求功业，圣人不求声名。","note":"全文主旨句。三者递降（至人最高），点明逍遥的理想人格：无己、无功、无名。","src":"逍遥游"},{"q":"莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。","a":"暮春时节，穿上春装，约上五六个成年人、六七个少年，在沂水边洗洗澡，在舞雩台上吹吹风，唱着歌回来。","note":"莫通“暮”；“浴乎沂”“风乎舞雩”状语后置；“风”名词作动词。","src":"子路曾皙冉有公西华侍坐"},{"q":"三子者出，曾皙后。曾皙曰：“夫三子者之言何如？”","a":"那三个人出去了，曾皙留在后面。曾皙问：\"那三位的话怎么样？\"","note":"","src":"子路曾皙冉有公西华侍坐"},{"q":"君处北海，寡人处南海，唯是风马牛不相及也。","a":"君侯住在北方，寡人住在南方，即使马牛走失，也不会跑到对方境内。","note":"风：放、走失（一说牝牡相诱）。喻齐楚相距极远、互不相干。","src":"齐桓公伐楚"},{"q":"今君王既栖于会稽之上，然后乃求谋臣，无乃后乎？","a":"如今君王已经退守会稽，这才来求谋臣，恐怕太晚了吧？","note":"无乃……乎：恐怕……吧，表委婉反问。","src":"勾践灭吴"},{"q":"冉有曰：“今夫颛臾，固而近于费。今不取，后世必为子孙忧。”","a":"冉有说：\"如今那颛臾，城墙坚固而且靠近费邑。现在不攻取，后世一定会成为子孙的忧患。\"","note":"","src":"季氏将伐颛臾"},{"q":"孔子曰：“求！周任有言曰：‘陈力就列，不能者止。’危而不持，颠而不扶，则将焉用彼相矣？且尔言过矣。虎兕出于柙，龟玉毁于椟中，是谁之过与？”","a":"孔子说：\"冉求！周任有句话说：'施展才能来担任职务，不能胜任的就辞职。'盲人遇到危险不去搀扶，跌倒了不去扶起，那又何必用那个辅助的人呢？况且你的话错了。老虎犀牛从笼子里跑出来，龟甲美玉在匣子里毁坏了，这是谁的过错呢？\"","note":"","src":"季氏将伐颛臾"}]},{"no":10,"date":"2026-11-07","date_end":"2026-11-08","pieces":["谏逐客书","留侯论","齐桓晋文之事","巫山巫峡","郑伯克段于鄢","秋水"],"theme":"综合练习 10","p1":[{"q":"「目不能两视而明，耳不能两听而聪。」出自（　）","opts":["《许行》","《劝学》","《小翠》","《鸿门宴》"],"ans":"B","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：眼睛不能同时看两样东西而都看明白，耳朵不能同时听两种声音而都听清楚。"},{"q":"「吾非至于子之门则殆矣，吾长见笑于大方之家。」出自（　）","opts":["《秋水》","《留侯论》","《许行》","《小翠》"],"ans":"A","atext":"《秋水》","src":"句子→篇目","note":"出自《秋水》。参考译文：我要不是来到您的门前就危险了，我将永远被懂得大道理的人耻笑。"},{"q":"「假舆马者，非利足也，而致千里；假舟楫者，非能水也，而绝江河。」出自（　）","opts":["《劝学》","《六国论》","《小翠》","《鸿门宴》"],"ans":"A","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：借助车马的人，并非脚走得快，却能到达千里之外；借助船桨的人，并非会游水，却能横渡江河。"},{"q":"「为国者无使为积威之所劫哉！」出自（　）","opts":["《巫山巫峡》","《六国论》","《小翠》","《勾践灭吴》"],"ans":"B","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：治理国家的人千万不要让自己被别人积久的威势所挟制啊！"},{"q":"「不及黄泉，无相见也。」出自（　）","opts":["《烛之武退秦师》","《邹忌讽齐王纳谏》","《郑伯克段于鄢》","《巫山巫峡》"],"ans":"C","atext":"《郑伯克段于鄢》","src":"句子→篇目","note":"出自《郑伯克段于鄢》。参考译文：不到黄泉（死后），不再见面。"},{"q":"「若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉！」出自（　）","opts":["《齐桓公伐楚》","《逍遥游》","《秋水》","《论贵粟疏》"],"ans":"B","atext":"《逍遥游》","src":"句子→篇目","note":"出自《逍遥游》。参考译文：至于顺应天地万物的本性，把握六气的变化，来遨游于无穷境界的人，他还凭借什么呢！"},{"q":"「沛公左司马曹无伤使人言于项羽曰：“沛公欲王关中，使子婴为相，珍宝尽有之。”」出自（　）","opts":["《秋水》","《逍遥游》","《鸿门宴》","《巫山巫峡》"],"ans":"C","atext":"《鸿门宴》","src":"句子→篇目","note":"出自《鸿门宴》。参考译文：沛公的左司马曹无伤派人对项羽说：“沛公想在关中称王，让子婴做相，珍宝全部占有了。”"},{"q":"「蓬生麻中，不扶而直；白沙在涅，与之俱黑。兰槐之根是为芷，其渐之滫，君子不近，庶人不服。其质非不美也，所渐者然也。故君子居必择乡，游必就士，所以防邪辟而近中正也。」出自（　）","opts":["《逍遥游》","《秋水》","《许行》","《劝学》"],"ans":"D","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：蓬草生长在麻丛中，不用扶持就自然挺直；白沙混在黑泥里，就和黑泥一样黑。兰槐的根叫芷，如果把它浸在臭水里，君子就不接近，百姓也不佩戴。它的本质不是不美，是浸染使它这样的。所以君子居住"},{"q":"「春耕，夏耘，秋获，冬藏，伐薪樵，治官府，给徭役。」出自（　）","opts":["《论贵粟疏》","《劝学》","《郑伯克段于鄢》","《齐桓晋文之事》"],"ans":"A","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：春天耕种，夏天除草，秋天收获，冬天储藏，还要砍柴薪、修缮官府、服徭役。"},{"q":"「不匝旬而得异地者二，虽古好事之士，或未能至焉。」出自（　）","opts":["《吕相绝秦》","《钴鉧潭西小丘记》","《子路曾皙冉有公西华侍坐》","《留侯论》"],"ans":"B","atext":"《钴鉧潭西小丘记》","src":"句子→篇目","note":"出自《钴鉧潭西小丘记》。参考译文：不满十天就得到两处奇美的地方，即使是古代酷爱山水的人，也许未必能有这样的际遇吧。"},{"q":"「盖均无贫，和无寡，安无倾。」出自（　）","opts":["《季氏将伐颛臾》","《齐桓公伐楚》","《逍遥游》","《烛之武退秦师》"],"ans":"A","atext":"《季氏将伐颛臾》","src":"句子→篇目","note":"出自《季氏将伐颛臾》。参考译文：财富平均便无所谓贫穷，上下和睦便不觉得人少，境内安定便不会倾覆。"},{"q":"「吾尝终日而思矣，不如须臾之所学也；吾尝跂而望矣，不如登高之博见也。登高而招，臂非加长也，而见者远；顺风而呼，声非加疾也，而闻者彰。假舆马者，非利足也，而致千里；假舟楫者，非能水也，而绝江河。君子生非异也，善假于物也。」出自（　）","opts":["《逍遥游》","《留侯论》","《小翠》","《劝学》"],"ans":"D","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：我曾经整天地思考，却不如片刻的学习收获大；我曾经踮起脚跟远望，却不如登上高处看得广阔。登上高处招手，手臂并没有加长，可是远处的人能看得见；顺着风呼喊，声音并没有更响，可是听的人听得"},{"q":"法国作家，代表作《包法利夫人》，被视为现实主义典范。（　）","opts":["大学才子派","乔叟","蒙田","福楼拜"],"ans":"D","atext":"福楼拜","src":"释义→词条","note":"福楼拜：法国作家，代表作《包法利夫人》，被视为现实主义典范。"},{"q":"因长篇小说《飘》（《乱世佳人》）一生唯一的作品；梗概：美国南北战争时，斯嘉丽、瑞德、艾希礼、梅兰妮四人的爱情纠葛（　）","opts":["《巴黎圣母院》(长篇小说)","洛贝·德·维伽","玛格丽特·米切尔（美国）","文艺复兴『三杰』"],"ans":"C","atext":"玛格丽特·米切尔（美国）","src":"释义→词条","note":"玛格丽特·米切尔（美国）：因长篇小说《飘》（《乱世佳人》）一生唯一的作品；梗概：美国南北战争时，斯嘉丽、瑞德、艾希礼、梅兰妮四人的爱情纠葛"},{"q":"《乌托邦》：对话体幻想小说（　）","opts":["意大利人","巴尔扎克","托马斯.莫尔","柏拉图"],"ans":"C","atext":"托马斯.莫尔","src":"释义→词条","note":"托马斯.莫尔：《乌托邦》：对话体幻想小说"},{"q":"古希腊三大悲剧作家之一，代表作《美狄亚》，擅长刻画女性心理。（　）","opts":["欧里庇得斯","文艺复兴『三杰』","斯威夫特","贺拉斯"],"ans":"A","atext":"欧里庇得斯","src":"释义→词条","note":"欧里庇得斯：古希腊三大悲剧作家之一，代表作《美狄亚》，擅长刻画女性心理。"},{"q":"20世纪拉美文学流派，用魔幻手法反映现实。代表：马尔克斯《百年孤独》（哥伦比亚）、阿斯图里亚斯（危地马拉）。（　）","opts":["『多余人』形象","古罗马","魔幻现实主义","文艺复兴『三杰』"],"ans":"C","atext":"魔幻现实主义","src":"释义→词条","note":"魔幻现实主义：20世纪拉美文学流派，用魔幻手法反映现实。代表：马尔克斯《百年孤独》（哥伦比亚）、阿斯图里亚斯（危地马拉）。"},{"q":"托马斯·基德；《哈姆雷特》，对莎士比亚的同名剧有影响（　）","opts":["大学才子派","『多余人』形象","英国","荷马"],"ans":"A","atext":"大学才子派","src":"释义→词条","note":"大学才子派：托马斯·基德；《哈姆雷特》，对莎士比亚的同名剧有影响"},{"q":"《巫山巫峡》的作者是（　）","opts":["汪琬","郦道元","司马迁","庄周"],"ans":"B","atext":"郦道元","src":"作品→作者","note":"《巫山巫峡》— 郦道元。原文标注：郦道元"},{"q":"《留侯论》的作者是（　）","opts":["苏轼","晁错","柳宗元","司马迁"],"ans":"A","atext":"苏轼","src":"作品→作者","note":"《留侯论》— 苏轼。原文标注：苏轼"}],"p2":[{"q":"『用之所趋异也』中「趋」的意思是（　）","opts":["沿：顺流而下；溯：逆流而上","趋向、追求（音qū）","溃败，溃散","名词作动词，使眼色"],"ans":"B","atext":"趋向、追求（音qū）","word":"趋","type":"实词","note":"所趋：追求的目的。"},{"q":"『期年之后』中「期年」的意思是（　）","opts":["违背、抵触","崇尚","满一年","赠送或赠予"],"ans":"C","atext":"满一年","word":"期年","type":"实词","note":"期（jī）年：一周年。"},{"q":"『以议执政之善否』中「否」的意思是（　）","opts":["远离。","不好","叩头","于是"],"ans":"B","atext":"不好","word":"否","type":"实词","note":"「否」：不好"},{"q":"『事之如父』中「事」的意思是（　）","opts":["被","砍削","几乎","侍奉"],"ans":"D","atext":"侍奉","word":"事","type":"实词","note":"「事」：侍奉"},{"q":"『虢叔死焉』中「焉」的意思是（　）","opts":["于此，在那里","估计，猜测","通“抵”，大抵、大都","恼怒、怨恨（音yùn）"],"ans":"A","atext":"于此，在那里","word":"焉","type":"实词","note":"兼词，相当于“于是/于之”。"},{"q":"『举坐欢笑』中「举」的意思是（　）","opts":["迅疾的样子，一跃而起。","对……感到奇怪。","考订、探究","全部，都；举动，行为"],"ans":"D","atext":"全部，都；举动，行为","word":"举","type":"实词","note":"「举」：全部，都；举动，行为"},{"q":"『汝倩人也？』中「倩」的意思是（　）","opts":["通“疲”，疲弱无能","黑色染料黑泥（音niè）","率领，带着","请别人代自己做事"],"ans":"D","atext":"请别人代自己做事","word":"倩","type":"实词","note":"「倩」：请别人代自己做事"},{"q":"『保民而王，莫之能御也。』中「王」的意思是（　）","opts":["名词作状语，像对待兄长一样","行王道，成就王业，以王道统一天下。","通\"辨\"，分辨，辨别。","赠送，留给（读wèi）"],"ans":"B","atext":"行王道，成就王业，以王道统一天下。","word":"王","type":"实词","note":"王(wàng)：名词作动词，行王道。"},{"q":"『间命工斫木为橱』中「斫」的意思是（　）","opts":["宽恕","砍削","贴近","等到"],"ans":"B","atext":"砍削","word":"斫","type":"实词","note":"斫（zhuó）：砍。"},{"q":"『然尚恨有阙者』中「阙」的意思是（　）","opts":["缺漏、不足","改，悔改","出言屈服、投降","其、他们的"],"ans":"A","atext":"缺漏、不足","word":"阙","type":"实词","note":"指李翰《张巡传》记事上的缺漏。"}],"p3":[{"q":"今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓“借寇兵而赍盗粮”者也。","a":"如今却抛弃百姓去资助敌国，拒绝宾客去使诸侯成就霸业，使天下贤士退缩不敢西进，停步不敢入秦，这就是所说的“把武器借给敌寇、把粮食送给盗贼”啊。","note":"“乃”却；“业”使动；“赍”赠送；判断句以“此所谓……者也”收束，比喻逐客之害。","src":"谏逐客书"},{"q":"是故倨傲鲜腆而深折之。","a":"所以老人故意态度傲慢无礼地重重折辱他。","note":"鲜腆：无礼；折：折辱。揭示老人试“忍”的用意。","src":"留侯论"},{"q":"曰：\"臣闻之胡龁曰：'王坐于堂上，有牵牛而过堂下者。王见之，曰：牛何之？对曰：将以衅钟。王曰：舍之！吾不忍其觳觫，若无罪而就死地。对曰：然则废衅钟与？曰：何可废也？以羊易之。'不识有诸？\"","a":"孟子说：\"我从胡龁那里听说：大王坐在堂上，有人牵着牛从堂下经过。大王看见了，问：牛要牵到哪里去？回答说：要用它的血涂钟。大王说：放了它！我不忍心看它恐惧发抖的样子，就像没有罪过却要被处死。回答说：那么废弃涂钟的仪式吗？大王说：怎么能废弃呢？用羊换它。不知道有这回事吗？\"","note":"","src":"齐桓晋文之事"},{"q":"自三峡七百里中，两岸连山，略无阙处；重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。","a":"在三峡七百里之间，两岸群山相连，几乎没有中断的地方；层层悬崖、排排峭壁遮天蔽日，如果不是正午和半夜，就看不见太阳和月亮。","note":"略：完全；阙：通“缺”；亭午：正午。全句正面写山之高连绵，用“自非……不见……”的双重否定反衬山势高峻。","src":"巫山巫峡"},{"q":"当此之时，子房之不死者，其间不能容发，盖亦已危矣。","a":"在那个时候，张良死里逃生，其间的危险连一根头发都容不下，真是太危险了。","note":"间不能容发：极言危险。盖：大概。","src":"留侯论"},{"q":"大叔完聚，缮甲兵，具卒乘，将袭郑。夫人将启之。公闻其期，曰：“可矣！”命子封帅车二百乘以伐京。京叛大叔段。段入于鄢，公伐诸鄢。五月辛丑，大叔出奔共。","a":"太叔修治城郭、聚集百姓，修缮铠甲兵器，准备步兵战车，打算偷袭郑国国都。武姜准备为他打开城门。庄公探听到他起兵的日期，说：\"可以了！\"命令子封率领二百辆战车去攻打京邑。京邑的人背叛了太叔段，段逃到鄢地，庄公又到鄢地讨伐他。五月辛丑日，太叔出逃到共国。","note":"","src":"郑伯克段于鄢"},{"q":"此其所挟持者甚大，而其志甚远也。","a":"这是因为他内心所怀抱的抱负很大，而他的志向又很远大。","note":"挟持者：指抱负。说明能忍的根源在于志大。","src":"留侯论"},{"q":"故深折其少年刚锐之气，使之忍小忿而就大谋。","a":"所以深深挫折他年轻人刚强锐利的脾气，使他能忍住小的愤怒而成就远大的谋略。","note":"忍小忿而就大谋：化用《论语》“小不忍则乱大谋”。","src":"留侯论"},{"q":"天下之水，莫大于海。","a":"天下的水，没有比海更大的。","note":"\"莫大于海\"：状语后置（于海大）。极写海之大。","src":"秋水"},{"q":"故渔者歌曰：巴东三峡巫峡长，猿鸣三声泪沾裳。","a":"所以打鱼的人唱道：巴东三峡之中巫峡最长，猿猴啼叫几声就令人泪水沾湿衣裳。","note":"引渔歌作结，“长”与“泪”呼应，把景语化为情语。","src":"巫山巫峡"},{"q":"媪之送燕后也，持其踵，为之泣，念悲其远也，亦哀之矣。","a":"您送燕后出嫁时，握着她的脚后跟为她哭泣，想到她远嫁而悲伤，也够哀怜她了。","note":"踵：脚后跟；持踵：古礼女儿出嫁，亲人不忍其行；“之”用于主谓间。","src":"触龙说赵太后"},{"q":"君子之于禽兽也：见其生，不忍见其死；闻其声，不忍食其肉。是以君子远庖厨也。","a":"君子对于飞禽走兽，看见它活着，便不忍心看它死去；听到它哀鸣的声音，便不忍心吃它的肉。因此君子远离厨房。","note":"远：形作动，远离。\"是以\"即\"以是\"，宾语前置。","src":"齐桓晋文之事"},{"q":"上惊验之，其旒冕乃梁黠心所制，袍则败布黄袱也。上怒其诬。","a":"皇帝惊讶地查验，那旒冕原来是高粱秸心做的，龙袍不过是旧黄布包袱。皇帝对王给谏的诬告大怒。","note":"写小翠以假乱真，智破政敌。","src":"小翠"},{"q":"王曰：\"吾惛，不能进于是矣。愿夫子辅吾志，明以教我；我虽不敏，请尝试之。\"","a":"宣王说：\"我昏乱糊涂，不能进到这一步了。希望先生帮助我实现志向，明确地教导我；我虽然不聪明，也请让我试一试。\"","note":"","src":"齐桓晋文之事"},{"q":"小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋。而彭祖乃今以久特闻，众人匹之，不亦悲乎！","a":"小智不能了解大智，寿命短的不了解寿命长的。怎么知道是这样呢？朝菌不知道一个月的时间，寒蝉不知道一年的时间，这就是寿命短的。楚国南边有一种叫冥灵的大树，把五百年当作一个春季，五百年当作一个秋季；上古有一种大椿树，把八千年当作一个春季，八千年当作一个秋季。可是彭祖如今却以长寿特别闻名，人们都和他相比，不也很可悲吗！","note":"","src":"逍遥游"},{"q":"对曰：“非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。”","a":"公西赤回答说：\"不敢说能做到，但愿意学习。宗庙祭祀的事，或者诸侯会盟的事，我愿意穿着礼服、戴着礼帽，做一个小小的司仪。\"","note":"","src":"子路曾皙冉有公西华侍坐"},{"q":"及陷于罪，然后从而刑之，是罔民也。","a":"等到他们犯了罪，接着就用刑罚处置他们，这是陷害百姓。","note":"罔通\"网\"，名作动，陷害。判断句。","src":"齐桓晋文之事"},{"q":"陈力就列，不能者止。","a":"能施展才力就任职，不能这样就辞职。","note":"引古史官周任之言，责冉有、季路不能止谏。","src":"季氏将伐颛臾"},{"q":"太史公疑子房以为魁梧奇伟，而其状貌乃如妇人女子，不称其志气。呜呼！此其所以为子房欤！","a":"司马迁原以为张良魁梧奇伟，可他的相貌却像妇人女子，同他的志气并不相称。唉！这正是张良之所以为张良啊！","note":"称（chèn）：相称。借司马迁之叹作结，余味不尽。","src":"留侯论"},{"q":"且夫水之积也不厚，则其负大舟也无力。","a":"况且水积聚得不深厚，那么它浮载大船就没有力量。","note":"\"之\"用于主谓之间取消句子独立性；负：浮载。以水与舟喻风与鹏，说明万物有所待。","src":"逍遥游"}]},{"no":11,"date":"2026-11-08","date_end":"2026-11-09","pieces":["吕相绝秦","秋水","六国论","齐桓晋文之事","许行","郑伯克段于鄢"],"theme":"综合练习 11","p1":[{"q":"「百工之事，固不可耕且为也。」出自（　）","opts":["《留侯论》","《劝学》","《许行》","《六国论》"],"ans":"C","atext":"《许行》","src":"句子→篇目","note":"出自《许行》。参考译文：各种工匠的工作，本来就不能一边种地一边兼做。"},{"q":"「吾不欲匹夫之勇也，欲其旅进旅退。」出自（　）","opts":["《逍遥游》","《小翠》","《秋水》","《勾践灭吴》"],"ans":"D","atext":"《勾践灭吴》","src":"句子→篇目","note":"出自《勾践灭吴》。参考译文：我不要匹夫之勇，要他们同进同退、步调一致。"},{"q":"「曰：“莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”」出自（　）","opts":["《齐桓晋文之事》","《子路曾皙冉有公西华侍坐》","《邹忌讽齐王纳谏》","《烛之武退秦师》"],"ans":"B","atext":"《子路曾皙冉有公西华侍坐》","src":"句子→篇目","note":"出自《子路曾皙冉有公西华侍坐》。参考译文：曾皙说：\"暮春三月，春天的衣服已经穿上了，五六个成年男子，六七个少年，在沂水里洗浴，在舞雩台上吹风，唱着歌回来。\""},{"q":"「后秦击赵者再，李牧连却之。洎牧以谗诛，邯郸为郡，惜其用武而不终也。」出自（　）","opts":["《报任安书》","《小翠》","《六国论》","《论贵粟疏》"],"ans":"C","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：后来秦国两次攻打赵国，李牧接连打退了它。等到李牧因受谗言被杀，邯郸就成了秦国的一个郡，可惜赵国用武力抗秦却没能坚持到底。"},{"q":"「臣闻地广者粟多，国大者人众，兵强则士勇。是以太山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。是以地无四方，民无异国，四时充美，鬼神降福，此五帝三王之所以无敌也。今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓“借寇兵而赍盗粮”者也。」出自（　）","opts":["《谏逐客书》","《勾践灭吴》","《传是楼记》","《触龙说赵太后》"],"ans":"A","atext":"《谏逐客书》","src":"句子→篇目","note":"出自《谏逐客书》。参考译文：我听说土地广阔粮食就多，国家大人口就众，兵器精良士兵就勇敢。所以泰山不拒绝土壤，才能成就它的高大；河海不挑剔细流，才能成就它的深广；君王不拒绝民众，才能彰明他的德行。所以地不分四方"},{"q":"「苟以天下之大，下而从六国破亡之故事，是又在六国下矣。」出自（　）","opts":["《六国论》","《秋水》","《勾践灭吴》","《鸿门宴》"],"ans":"A","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：假如凭着偌大的天下，却重蹈六国灭亡的旧事，这就又在六国之下了。"},{"q":"「要之，死日然后是非乃定。」出自（　）","opts":["《钴鉧潭西小丘记》","《报任安书》","《烛之武退秦师》","《触龙说赵太后》"],"ans":"B","atext":"《报任安书》","src":"句子→篇目","note":"出自《报任安书》。参考译文：总而言之，一个人到死了以后，是非功过才能论定。"},{"q":"「虽愚人亦能数日而知死所矣。」出自（　）","opts":["《巫山巫峡》","《逍遥游》","《张中丞传后叙》","《留侯论》"],"ans":"C","atext":"《张中丞传后叙》","src":"句子→篇目","note":"出自《张中丞传后叙》。参考译文：即使是愚蠢的人也能数着日子知道自己的死期了。"},{"q":"「乘坚策肥，履丝曳缟。」出自（　）","opts":["《齐桓晋文之事》","《许行》","《触龙说赵太后》","《论贵粟疏》"],"ans":"D","atext":"《论贵粟疏》","src":"句子→篇目","note":"出自《论贵粟疏》。参考译文：乘坐坚固的车子，驱赶肥壮的马，脚穿丝鞋，身披白绢长衣。"},{"q":"「为长者折枝，语人曰：我不能。是不为也，非不能也。」出自（　）","opts":["《谏逐客书》","《齐桓晋文之事》","《郑伯克段于鄢》","《季氏将伐颛臾》"],"ans":"B","atext":"《齐桓晋文之事》","src":"句子→篇目","note":"出自《齐桓晋文之事》。参考译文：给长辈弯腰作揖，告诉人说：我做不到。这是不肯做，不是不能做。"},{"q":"「青，取之于蓝，而青于蓝；冰，水为之，而寒于水。」出自（　）","opts":["《劝学》","《六国论》","《秋水》","《小翠》"],"ans":"A","atext":"《劝学》","src":"句子→篇目","note":"出自《劝学》。参考译文：靛青从蓝草中提取，却比蓝草更青；冰由水凝结而成，却比水更寒冷。"},{"q":"「以赂秦之地封天下之谋臣，以事秦之心礼天下之奇才，并力西向，则吾恐秦人食之不得下咽也。」出自（　）","opts":["《报任安书》","《六国论》","《传是楼记》","《勾践灭吴》"],"ans":"B","atext":"《六国论》","src":"句子→篇目","note":"出自《六国论》。参考译文：如果用贿赂秦国的土地来封赏天下的谋臣，用侍奉秦国的心意来礼遇天下的奇才，合力向西抗秦，那么我恐怕秦国人连吃饭都咽不下去。"},{"q":"日本作家，1994年获诺贝尔文学奖，是继川端康成之后第二位获该奖的日本作家，代表作《个人的体验》。（　）","opts":["普鲁斯特","大江健三郎","亚里士多德","贺拉斯"],"ans":"B","atext":"大江健三郎","src":"释义→词条","note":"大江健三郎：日本作家，1994年获诺贝尔文学奖，是继川端康成之后第二位获该奖的日本作家，代表作《个人的体验》。"},{"q":"意大利诗人，人文主义奠基者，代表作《歌集》，被称为『人文主义之父』。（　）","opts":["果戈理","彼特拉克","巴尔扎克","乔伊斯"],"ans":"B","atext":"彼特拉克","src":"释义→词条","note":"彼特拉克：意大利诗人，人文主义奠基者，代表作《歌集》，被称为『人文主义之父』。"},{"q":"法国批判现实主义大师，创作总集《人间喜剧》（90余部），代表作《高老头》（塑造吝啬鬼葛朗台的是《欧也妮·葛朗台》）、《欧也妮·葛朗台》。（　）","opts":["存在主义文学","司汤达","英国","巴尔扎克"],"ans":"D","atext":"巴尔扎克","src":"释义→词条","note":"巴尔扎克：法国批判现实主义大师，创作总集《人间喜剧》（90余部），代表作《高老头》（塑造吝啬鬼葛朗台的是《欧也妮·葛朗台》）、《欧也妮·葛朗台》。"},{"q":"神话诗《变形记》；有“神话词典”之称（　）","opts":["古典主义","乔叟","意大利人","奥维德"],"ans":"D","atext":"奥维德","src":"释义→词条","note":"奥维德：神话诗《变形记》；有“神话词典”之称"},{"q":"英国浪漫主义诗人，代表作《西风颂》（名句『冬天来了，春天还会远吗』）、《解放了的普罗米修斯》。（　）","opts":["海明威","奥维德","雪莱","乔叟"],"ans":"C","atext":"雪莱","src":"释义→词条","note":"雪莱：英国浪漫主义诗人，代表作《西风颂》（名句『冬天来了，春天还会远吗』）、《解放了的普罗米修斯》。"},{"q":"20世纪法国文学流派，关注荒诞与自由选择。代表：萨特《恶心》、加缪《局外人》。（　）","opts":["文艺复兴","文艺复兴『三杰』","存在主义文学","『多余人』形象"],"ans":"C","atext":"存在主义文学","src":"释义→词条","note":"存在主义文学：20世纪法国文学流派，关注荒诞与自由选择。代表：萨特《恶心》、加缪《局外人》。"},{"q":"《论贵粟疏》的作者是（　）","opts":["苏洵","李斯","晁错","蒲松龄"],"ans":"C","atext":"晁错","src":"作品→作者","note":"《论贵粟疏》— 晁错。原文标注：晁错"}],"p2":[{"q":"『季氏将有事于颛臾』中「有事」的意思是（　）","opts":["名词作状语，像对待兄长一样","脚后跟，引申为走到、亲自到。","通“掘”，挖掘","这里指有战事、用兵"],"ans":"D","atext":"这里指有战事、用兵","word":"有事","type":"实词","note":"古以祭祀、盟会、兵戎为国之大事；冉有讳言“伐”，故称“有事”。"},{"q":"『功施到今』中「施」的意思是（　）","opts":["屯驻，退守","延续、遍及（音yì）","超过，胜过","与。。。比，哪一个。。。"],"ans":"B","atext":"延续、遍及（音yì）","word":"施","type":"实词","note":"延续。"},{"q":"『则将焉用彼相矣』中「相」的意思是（　）","opts":["加倍、利息加倍（称chèn）","同“座”，座位","扶助盲人的人，此指辅佐者","同“他”，别的"],"ans":"C","atext":"扶助盲人的人，此指辅佐者","word":"相","type":"实词","note":"相（xiàng）：扶相；下文“相夫子”的“相”为动词“辅佐”。"},{"q":"『朝服衣冠』中「朝」的意思是（　）","opts":["赤脚走路","在早晨","超过，胜过","再，又"],"ans":"B","atext":"在早晨","word":"朝","type":"实词","note":"读zhāo，修饰动词“服”。"},{"q":"『第善谑』中「第」的意思是（　）","opts":["有人","宽恕","欺骗","只是"],"ans":"D","atext":"只是","word":"第","type":"实词","note":"第：但、只是。"},{"q":"『陶公少时』中「少」的意思是（　）","opts":["仔细","年少","后来","铺平"],"ans":"B","atext":"年少","word":"少","type":"实词","note":"「少」：年少"},{"q":"『杀人如不能举，刑人如恐不胜』中「胜」的意思是（　）","opts":["使……听到","尽、全","摇晃，晃动","听说"],"ans":"B","atext":"尽、全","word":"胜","type":"实词","note":"举、胜皆“尽”义。"},{"q":"『丘之小不能一亩』中「不能」的意思是（　）","opts":["不足、不到","通“俸”，俸禄","追究，审问；推崇","在家"],"ans":"A","atext":"不足、不到","word":"不能","type":"实词","note":"“不能”即“不足、不满”。"},{"q":"『太祖甚异之』中「异」的意思是（　）","opts":["认为……多，夸耀，赞许。","意动用法，对。。。感到惊异；和。。。不同","通\"辨\"，分别，区别。","通\"网\"，张网捕捉，引申为陷害。"],"ans":"B","atext":"意动用法，对。。。感到惊异；和。。。不同","word":"异","type":"实词","note":"「异」：意动用法，对。。。感到惊异；和。。。不同"},{"q":"『亦欲以究天人之际』中「究」的意思是（　）","opts":["穷尽、推究","荒废时日","飞奔的马","兵器、武器"],"ans":"A","atext":"穷尽、推究","word":"究","type":"实词","note":"究：探究穷尽。"}],"p3":[{"q":"我君景公引领西望曰：庶抚我乎！","a":"我们景公伸长脖子西望说：大概会安抚我们了吧！","note":"引领：伸颈。写盼秦和好之切。","src":"吕相绝秦"},{"q":"井蛙不可以语于海者，拘于虚也。","a":"井里的蛙不能和它谈海，是因为它被居处所局限。","note":"判断句；虚通\"墟\"，居处。\"拘于虚\"为被动/状语后置。比喻眼界受空间限制。","src":"秋水"},{"q":"六国破灭，非兵不利，战不善，弊在赂秦。赂秦而力亏，破灭之道也。或曰：“六国互丧，率赂秦耶？”曰：“不赂者以赂者丧，盖失强援，不能独完。故曰：弊在赂秦也。”","a":"六国灭亡，不是兵器不锋利，仗打得不好，弊病在于贿赂秦国。贿赂秦国就使国力亏损，这是灭亡的原因。有人说：\"六国相继灭亡，都是因为贿赂秦国吗？\"回答说：\"不贿赂的国家因为贿赂的国家而灭亡，因为失去了强大的援助，不能独自保全。所以说：弊病在于贿赂秦国。\"","note":"","src":"六国论"},{"q":"王笑曰：\"是诚何心哉？我非爱其财而易之以羊也，宜乎百姓之谓我爱也。\"","a":"宣王笑着说：\"这究竟是什么心理呢？我不是吝惜钱财才用羊换它，百姓说我吝惜也是应该的。\"","note":"","src":"齐桓晋文之事"},{"q":"\"然则治天下独可耕且为与？有大人之事，有小人之事。且一人之身，而百工之所为备。如必自为而后用之，是率天下而路也。故曰：或劳心，或劳力；劳心者治人，劳力者治于人；治于人者食人，治人者食于人：天下之通义也。","a":"\"那么治理天下难道可以一边耕种一边做吗？有做官的人的事，有百姓的事。而且一个人的生活所需，要靠各种工匠的成品来齐备。如果一定要自己做了才用，这是引导天下的人疲于奔命。所以说：有的人动脑筋，有的人出力；动脑筋的人治理别人，出力的人被别人治理；被别人治理的人供养别人，治理别人的人被别人供养：这是天下通行的道理。","note":"","src":"许行"},{"q":"夏虫不可以语于冰者，笃于时也。","a":"夏天的虫不能和它谈冰，是因为它被时令所局限。","note":"判断句；笃：局限。比喻受时间限制，即\"夏虫语冰\"。","src":"秋水"},{"q":"尔有母遗，繄我独无！","a":"你有母亲可以孝敬，唯独我没有！","note":"遗（wèi）：孝敬。繄（yī）：惟、独。庄公悔恨之言。","src":"郑伯克段于鄢"},{"q":"百姓皆以王为爱也，臣固知王之不忍也。","a":"百姓都认为大王是吝啬，我本来就知道您是于心不忍。","note":"爱：吝啬；以：认为。\"王之不忍\"之字取消句子独立性。","src":"齐桓晋文之事"},{"q":"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。","a":"有时遇到皇帝命令急需传达，早晨从白帝城出发，傍晚就到江陵，这中间一千二百里，即使骑着飞奔的马、驾着长风，也没有这样快。","note":"朝、暮：名词作状语，在早晨、在傍晚；奔：活用为名词“奔马”。以夸张与对比写水流之速。","src":"巫山巫峡"},{"q":"无庸，将自及。","a":"不用除他，他会自己招致灾祸。","note":"庸通用；及：及于祸。","src":"郑伯克段于鄢"},{"q":"蜩与学鸠笑之曰：\"我决起而飞，抢榆枋而止，时则不至，而控于地而已矣，奚以之九万里而南为？\"适莽苍者，三餐而反，腹犹果然；适百里者，宿舂粮；适千里者，三月聚粮。之二虫又何知！","a":"蝉和斑鸠讥笑它说：\"我一下子起飞，碰到榆树檀树就停下来，有时飞不到，就落到地上罢了，哪里用得着飞上九万里再往南去呢？\"到近郊去的人，只带三顿饭就可以往返，肚子还是饱饱的；到百里外去的人，要前一天夜里舂米备粮；到千里外去的人，要用三个月积聚干粮。这两只小虫又知道什么呢！","note":"","src":"逍遥游"},{"q":"闻其故，惊颜如土，大哭曰：“此祸水也！指日赤吾族矣！”","a":"听了缘故，王太常脸色如土，大哭道：“这是祸水啊！很快就要使我家族杀身灭门了！”","note":"赤：使动，杀尽。写王公惊惶。","src":"小翠"},{"q":"三江环之，民无所移。有吴则无越，有越则无吴。","a":"三江环绕吴越，百姓无法外迁。有吴就没有越，有越就没有吴。","note":"子胥陈说吴越势不两立。","src":"勾践灭吴"},{"q":"越国以鄙远，君知其难也，焉用亡郑以陪邻？","a":"越过晋国而把远方的郑国作边邑，您知道那很难，哪里用得着灭亡郑国来增加邻邦（晋）的土地？","note":"鄙：意动；陪：增加。亡郑只利晋。","src":"烛之武退秦师"},{"q":"高祖忍之，养其全锋而待其弊，此子房教之也。","a":"高祖能忍，保全自己全部的锋芒而等待对方疲敝，这都是张良教给他的。","note":"弊：疲困。写张良以“忍”教高祖。","src":"留侯论"},{"q":"季氏将伐颛臾。冉有、季路见于孔子曰：“季氏将有事于颛臾。”","a":"季康子准备讨伐颛臾。冉有、子路去见孔子说：\"季氏将对颛臾采取军事行动。\"","note":"","src":"季氏将伐颛臾"},{"q":"远诚畏死，何苦守尺寸之地，食其所爱之肉，以与贼抗而不降乎？","a":"许远如果真的怕死，为什么要坚守这小小地盘，吃他所爱之人的肉，来和叛军对抗而不投降呢？","note":"诚：果真，表假设；何苦：何必。反诘句，有力反驳“畏死”之说。","src":"张中丞传后叙"},{"q":"夏四月戊午，晋侯使吕相绝秦，曰：“昔逮我献公及穆公相好，戮力同心，申之以盟誓，重之以昏姻。天祸晋国，文公如齐，惠公如秦。无禄，献公即世。穆公不忘旧德，俾我惠公用能奉祀于晋。又不能成大勋，而为韩之师。亦悔于厥心，用集我文公，是穆之成也。","a":"夏天四月戊午日，晋厉公派吕相去和秦国断绝邦交，说：\"从前我们献公和贵国穆公相互友好，合力同心，用盟誓加以申明，又用婚姻关系加以巩固。上天降祸给晋国，文公流亡齐国，惠公流亡秦国。不幸，献公去世。穆公没有忘记过去的恩德，使我惠公能够回国主持祭祀。后来惠公没能成就大功，于是发生了韩原之战。穆公心中也有悔意，就帮助我文公回国，这是穆公的成就。","note":"","src":"吕相绝秦"},{"q":"朝菌不知晦朔，蟪蛄不知春秋，此小年也。","a":"朝菌不知道一个月的首尾，蟪蛄不知道一年的四季，这就是短寿。","note":"判断句。晦朔：农历每月最后一天和初一；蟪蛄：寒蝉。比喻小年。","src":"逍遥游"},{"q":"如必自为而后用之，是率天下而路也。","a":"如果一定要自己制作出来才使用，这是率领天下的人疲于奔命。","note":"路：疲惫、疲于道路。比喻强迫人人皆自为其用的恶果。","src":"许行"}]}]};
